/// Revision of the generator's rendering contract.
///
/// Any change that can alter generated bytes for an unchanged scan and an
/// unchanged repository config must bump this revision, so recorded generator
/// state can prove which revision produced the recorded outputs. Never reset
/// or reuse a revision.
pub const GENERATOR_REVISION: &str = "69";

const GENERATED_HEADER: &str = "# Generated by velnor-workflow. Regenerate; do not hand-edit.\n";

/// The workflow file that carries the canonical fleet-consumer caller: its
/// bytes are hash-pinned by the released `velnor-actions` reusable it calls,
/// so the generator preserves the render-consumer header instead of stamping
/// its own. The header flips only together with the fleet pins, at a fleet
/// release that expects the new bytes.
const FLEET_CALLER_WORKFLOW: &str = "ci.yml";
const FLEET_CALLER_HEADER: &str = "# Generated by velnor-actions-generator. DO NOT EDIT.\n";

const WORKFLOW_TEMPLATE_DIR: &str = ".github/ci/workflow-templates";
/// The workflow file the per-owner-block update-channel matrix renders into.
const PACKAGE_UPDATE_WORKFLOW: &str = "package-update.yml";
/// The workflow file a declared release publisher renders into.
pub(crate) const RELEASE_WORKFLOW: &str = "release.yml";
/// The consumer-side updater the granted channels are implemented by.
const PACKAGE_UPDATER_WORKFLOW: &str = "package-updater.yml";
// Keep the sidecar path stable so Velnor can adopt repositories generated by
// the former standalone tool without losing overwrite ownership proof.
pub(crate) const OWNERSHIP_STATE: &str = ".github/ci/.github-actions-generator-state";
const OWNERSHIP_STATE_HEADER: &str = "# Generated ownership state; do not edit.\n";
// Schema 2 adds the generation inputs (`config`, `scan`, `generator`) beside
// the recorded outputs. The older layout is never parsed; see
// `parse_ownership_state` for the fail-closed migration rule.
const OWNERSHIP_STATE_SCHEMA: &str = "2";
const OPEN_TOFU_VERSION: &str = "1.12.6";
pub(crate) const VELNOR_WORKFLOW_SETUP_ACTION: &str =
    "tailrocks/velnor/.github/actions/setup-velnor-workflow";
/// The same composite from the owner's own checkout. The owner never pins
/// itself by `uses:@<sha>`: that third self-referential pin broke every D19
/// bump (`velnor-runner`'s compiled action manifest had to list it), so the
/// owner runs the action at the checked-out ref and `rev:` alone selects the
/// runtime.
pub(crate) const VELNOR_WORKFLOW_LOCAL_SETUP_ACTION: &str =
    "./.github/actions/setup-velnor-workflow";
/// The same composite resolved out of the policy job's sibling checkout.
/// The owner policy job never checks the repository out at the workspace
/// root — a root checkout wipes `policy-checkout/` under `clean: true` —
/// so it checks the BASE tree's action directory out under
/// `policy-setup-action/` and runs the composite from there.
pub(crate) const VELNOR_WORKFLOW_POLICY_SETUP_ACTION: &str =
    "./policy-setup-action/.github/actions/setup-velnor-workflow";
/// The owner package-release publisher checks the candidate source out under
/// `source/` before running repository-owned verification tasks. Its local
/// setup action is therefore resolved from that exact checkout, not from the
/// publisher workspace root.
pub(crate) const VELNOR_WORKFLOW_SOURCE_SETUP_ACTION: &str =
    "./source/.github/actions/setup-velnor-workflow";
pub(crate) const VELNOR_CI_REPORT_ACTION: &str =
    "tailrocks/velnor/.github/actions/report-velnor-ci-outcomes";
pub(crate) const VELNOR_CI_LOCAL_REPORT_ACTION: &str =
    "./.github/actions/report-velnor-ci-outcomes";
const VELNOR_WORKFLOW_INSTALL_GIT_URL: &str = "https://github.com/tailrocks/velnor";
/// The source commit this binary was built from, stamped by `build.rs`
/// (`unknown` when the build tree had no git). `velnor-workflow --revision`
/// prints it; provenance metadata, never the product lookup key.
pub const SOURCE_REVISION: &str = env!("VELNOR_WORKFLOW_SOURCE_SHA");
/// The source-closure digest of the tree this binary was built from (see
/// [`closure`]), stamped by `build.rs` (`unknown` when the build tree had
/// no git). `velnor-workflow --closure` prints it; the D19 guard accepts a
/// renderer whose closure equals the declared pin's closure.
pub const SOURCE_CLOSURE: &str = env!("VELNOR_WORKFLOW_CLOSURE_DIGEST");
/// JSON build identity embedded by `build.rs`; consumers bind this report to
/// the release manifest after attestation and digest verification.
pub const SOURCE_BUILD_IDENTITY: &str = env!("VELNOR_WORKFLOW_BUILD_IDENTITY");
/// Names a `velnor-workflow` binary built at the pinned policy revision. The
/// D19 guard consults it first; generated hosted jobs export it after
/// installing the runtime artifact's policy binary so `--check` never needs
/// the network.
pub const VELNOR_WORKFLOW_PINNED_BINARY_ENV: &str = "VELNOR_WORKFLOW_PINNED_BINARY";
// The D19 generator pin is not a source literal: a constant naming the commit
// that carries it can never equal that commit, so a tree rendered by the
// pinned generator could never be byte-identical to the tree that declares the
// pin. The pin is configuration (`[generator] revision`, see
// `ProjectConfig::workflow_revision`), and the policy validator reads it from
// the audited tree. This environment variable carries the revision of the
// policy validator the *base* branch runs; `velnor-workflow policy` requires
// the audited tree's pin to descend from it.
const VELNOR_POLICY_REVISION_ENV: &str = "VELNOR_WORKFLOW_POLICY_REVISION";
const MR_BOXINGTON_VERSION: &str = "1.12.0";
/// mbx's action-store budget setting (`gc.max_size`). It is the bound the
/// automatic sweep prunes the store to after a build, and the only budget
/// that applies on a hosted runner: `gc.max_total_size` is unset there and
/// governs the Velnor hosts' combined store (`config/fleet/velnor-host.env`).
pub(crate) const MR_BOXINGTON_STORE_BUDGET_ENV: &str = "MBX_GC_MAX_SIZE";
/// The action-store budget every GitHub-backend Mr. Boxington job exports.
///
/// mbx derives `gc.max_size` from the cache disk — 5% of it, clamped to
/// `[5 GiB, 500 GiB]` — so a hosted `ubuntu-24.04` runner's ~72 GiB root disk
/// lands on the 5 GiB floor. A hosted job's store is job-scoped: the action
/// imports the restored bundle at setup and exports the session's action
/// results in its post step, so a sweep that fires between two Cargo
/// commands evicts results the export still needs and the job fails after
/// every test passed (`mbx[error]: action result is missing`). The first
/// failing `main` run measured the largest Rust unit at 5.2 GiB stored before
/// gc evicted 96 of its action results. 12 GiB holds that unit with headroom
/// and stays inside the hosted image's free disk (about 20 GiB on
/// `ubuntu-24.04`); it is a ceiling on the store, not a reservation.
///
/// `jdx/mr-boxington-action` v1.4.0 selects directory-form object bundles
/// with mbx >=1.12.0, so a GitHub cache restore is not unpacked a second time
/// by `mbx cache import`. It also defaults `MBX_GC_AUTO=0` on hosted runners
/// in objects mode unless a job opts back in. The Velnor runner admits that
/// exact ref in its compiled capability manifest; the explicit 12 GiB budget
/// remains the safety ceiling for jobs that enable collection, keeping the
/// store bounded rather than growing to the runner's disk.
pub(crate) const MR_BOXINGTON_HOSTED_STORE_BUDGET: &str = "12GiB";

/// The step that exports the hosted action-store budget for the rest of the
/// job. `$GITHUB_ENV` is the only transport that reaches every later step,
/// including the action's own import and post-step export, so the budget is
/// rendered as a step ahead of the action rather than as `env:` on one step.
pub(crate) fn render_mr_boxington_store_budget_step(output: &mut String) {
    output.push_str(&mr_boxington_store_budget_step());
}

fn mr_boxington_store_budget_step() -> String {
    format!(
        "      - name: Bound the Mr. Boxington store\n        shell: bash\n        run: echo \"{MR_BOXINGTON_STORE_BUDGET_ENV}={MR_BOXINGTON_HOSTED_STORE_BUDGET}\" >> \"$GITHUB_ENV\"\n"
    )
}
