/// Immutable, reviewed action commits used by every emitted workflow.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ActionPin {
    Checkout,
    CacheRestore,
    CacheSave,
    OpenTofuSetup,
    UploadArtifact,
    DownloadArtifact,
    Bun,
    Node,
    RustTool,
    Mise,
    Gradle,
    Sccache,
    MrBoxington,
    // d2a-parity vocabulary: unconstructed in d2a too, where the crate-root
    // `pub` enum is lint-exempt as external API.
    #[allow(dead_code)]
    Mold,
    GithubRuntime,
    DockerBuildx,
    DockerLogin,
    #[allow(dead_code)]
    DockerQemu,
    DockerBuild,
    #[allow(dead_code)]
    Cosign,
    Attest,
    CratesAuth,
    ConfigurePages,
    UploadPages,
    DeployPages,
    Renovate,
}

