#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub(crate) struct ReleaseSpec {
    /// The publisher this contract renders, as the config declares it. The
    /// renderer implements a fixed set; anything else renders nothing.
    pub(crate) kind: String,
    /// Explicit release verification lanes. `None` preserves the historical
    /// provider-universe fanout for configs that have not adopted the typed
    /// release contract; it is never inferred from event routing.
    pub(crate) verification_providers: Option<provider::ProviderSet>,
    pub(crate) package: String,
    pub(crate) packages: Vec<String>,
    pub(crate) binary: String,
    pub(crate) targets: Vec<String>,
    pub(crate) image: String,
    /// The workspace package the image lane compiles into the container.
    /// Empty selects `package`.
    pub(crate) image_package: String,
    pub(crate) source_repository: String,
    pub(crate) consumer_repository: String,
    pub(crate) artifact_path: String,
    pub(crate) description: String,
    /// The consumer release-manifest schema URN the publisher stamps into
    /// `release-manifest.json`. A consumer-contract value the repository
    /// declares; the generic renderer never invents one.
    pub(crate) manifest_schema: String,
    /// The typed APT architecture set. Empty selects both arches; any
    /// explicit set must equal exactly both arches.
    pub(crate) apt_arches: Vec<String>,
    /// The pinned APT publisher signing-key fingerprint (full 40-hex).
    pub(crate) signer_fingerprint: String,
    /// The environment secret holding the APT signing passphrase (name only).
    pub(crate) passphrase_secret: String,
    /// The environment secret holding the APT signing-key material (name
    /// only). The publisher imports it into an isolated keyring and refuses
    /// unless the private key agrees with the pinned fingerprint.
    pub(crate) signing_key_secret: String,
    /// The repository-local APT keyring path. Empty derives `<package>.gpg`.
    pub(crate) keyring_path: String,
    /// The APT `Origin`/`Label`. Empty derives the package name.
    pub(crate) apt_origin: String,
    /// The packaged-identity directory inside the deb. Empty derives the
    /// source repository name.
    pub(crate) apt_identity_dir: String,
    /// The served feed base URL for prior-pair recovery and the no-rollback
    /// deploy guard.
    pub(crate) apt_feed_url: String,
    /// The retained rollback count. Zero means unset and selects one.
    pub(crate) retention: u32,
    /// The consumer-owned Dockerfile the `docker` publisher builds, relative
    /// to the repository root. Empty selects the `Dockerfile` convention.
    /// Generation-time only: pinned runtimes never consume it.
    pub(crate) dockerfile: String,
    /// The build context the `docker` publisher builds from, relative to the
    /// repository root. Empty selects `.`. Generation-time only.
    pub(crate) context: String,
    /// The OCI platforms the `docker` publisher publishes, as
    /// `os/architecture` pairs. Empty selects both Linux architectures.
    /// Generation-time only.
    pub(crate) platforms: Vec<String>,
    /// The trusted producer workflow a `workflow_run` event must come from
    /// before a rolling lane publishes. Empty renders no `workflow_run`
    /// trigger: the lane keeps its push/dispatch surface exactly.
    pub(crate) producer_workflow: String,
    /// The immutable numeric Actions workflow identity. A producer binding
    /// must carry this alongside its display name and repository path.
    pub(crate) producer_workflow_id: u64,
    /// The immutable repository workflow path (for example
    /// `.github/workflows/ci.yml`).
    pub(crate) producer_workflow_path: String,
    /// The producer conclusion the publish gate requires. Empty means the
    /// only admitted value, `success`; anything else is a usage error.
    pub(crate) producer_conclusion: String,
    /// The dispatch modes the workflows offer (`validate`, `build`,
    /// `rehearse`; publication stays tag-triggered and is never a dispatch
    /// option). Empty keeps the legacy trigger surface byte-identical.
    pub(crate) modes: Vec<String>,
    /// Extra members packaged into each release archive next to the built
    /// binary. Empty keeps the single-binary archive exactly.
    pub(crate) archive_members: Vec<String>,
    /// The archive checksum sidecar algorithm. Empty means `sha256`, the
    /// only algorithm the runtime implements.
    pub(crate) archive_checksum: String,
    /// The `retention-days` release artifacts upload with. Zero keeps the
    /// per-lane literals.
    pub(crate) archive_retention_days: u32,
    /// Credential setup/teardown pairs. Every setup renders with a paired
    /// teardown that also runs under `if: always()`, so cancellation and
    /// timeouts still restore host state.
    pub(crate) credentials: Vec<ReleaseCredential>,
    /// The tag filter the release triggers match on. Empty selects `v*`.
    pub(crate) tag_pattern: String,
    /// The OCI registry host the docker publisher logs in to. Empty keeps
    /// the GHCR automatic-token login; a declared host always travels with
    /// its two credential secret names.
    pub(crate) registry: String,
    /// The secret holding the registry username. A name, never the value.
    pub(crate) registry_username_secret: String,
    /// The secret holding the registry password. A name, never the value.
    pub(crate) registry_password_secret: String,
    /// Named-task jobs the tasks publisher renders. Empty for every other
    /// publisher, whose job graph is fixed.
    pub(crate) jobs: Vec<ReleaseJobSpec>,
    /// One `[[release.image]]` row per published image of a multi-image
    /// docker contract. Empty keeps the scalar contract. Generation-time
    /// only, like the scalar docker build inputs.
    pub(crate) images: Vec<ReleaseImageSpec>,
}

/// One published image of a multi-image docker contract: the published
/// reference, its build inputs, and the sibling images whose tags must
/// exist before it inspects or builds. Empty `dockerfile`/`context`
/// select the scalar conventions; empty `platforms` selects both Linux
/// architectures; `lfs` fetches Git LFS objects in the row's
/// platform-lane checkout.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub(crate) struct ReleaseImageSpec {
    pub(crate) name: String,
    pub(crate) image: String,
    pub(crate) dockerfile: String,
    pub(crate) context: String,
    pub(crate) platforms: Vec<String>,
    pub(crate) needs: Vec<String>,
    pub(crate) lfs: bool,
}

/// One typed named-task release job. Product build, sign, and publication
/// logic stays in the named mise tasks; the generator owns the job graph,
/// event gates, runner routing, and protected execution metadata.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub(crate) struct ReleaseJobSpec {
    pub(crate) id: String,
    pub(crate) name: String,
    pub(crate) tasks: Vec<String>,
    pub(crate) needs: Vec<String>,
    pub(crate) runner: String,
    pub(crate) modes: Vec<String>,
    pub(crate) timeout_minutes: u32,
    pub(crate) environment: String,
    pub(crate) attest_subjects: Vec<String>,
    pub(crate) permissions: BTreeMap<String, String>,
    pub(crate) env: BTreeMap<String, String>,
}

/// One credential the release lane mounts and must unmount: the setup
/// command that materializes it and the teardown command that restores the
/// host. Both are explicit repository inputs; the renderer pairs them and
/// never invents either side.
#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub(crate) struct ReleaseCredential {
    pub(crate) name: String,
    pub(crate) setup: String,
    pub(crate) teardown: String,
}

/// Evidence produced by the read-only repository analysis pass.
///
/// This deliberately records both detected capabilities and the boundary of
/// what static inspection cannot prove. The renderer may consume positive
/// evidence, but it must not turn an unknown release or trust contract into a
/// guessed workflow.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct AnalysisSummary {
    pub(crate) method: String,
    pub(crate) detected: Vec<String>,
    pub(crate) limitations: Vec<String>,
}

/// Generated, editable CI policy. It is intentionally not tied to a repository name.
#[expect(
    clippy::struct_excessive_bools,
    reason = "these independent switches are the stable generated configuration contract"
)]
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProjectConfig {
    pub(crate) repository: String,
    /// D19 generator pin: the generator-repository commit whose
    /// `velnor-workflow` renders and audits this tree. It is the single
    /// literal behind every generated pin (policy runtime `--rev`,
    /// `setup-velnor-workflow` `rev:`, runtime artifact names), read from
    /// `[generator] revision` in the generation config and defaulting to the
    /// running binary's own [`SOURCE_REVISION`]. It never enters
    /// `project.toml`: that runtime contract is parsed by pinned runtimes
    /// with `deny_unknown_fields`.
    pub(crate) workflow_revision: String,
    /// The repository's own profile label, recorded verbatim in the generated
    /// `project.toml`. It describes the surface; it never selects one.
    pub(crate) profile: String,
    pub(crate) analysis: AnalysisSummary,
    pub(crate) verified: bool,
    pub(crate) workflow_files: Vec<String>,
    pub(crate) notes: Vec<String>,
    pub(crate) version_bump_units: Vec<String>,
    pub(crate) default_branch: String,
    /// The provider universe for this repo. Non-empty.
    pub(crate) providers: provider::ProviderSet,
    /// Providers that run on automatic events (PR/push/schedule). Under the
    /// visibility-based runner policy this equals the visibility singleton;
    /// pure event-to-provider routing.
    pub(crate) automatic_providers: provider::ProviderSet,
    // NOTE: no `default_dispatch_providers`. Manual dispatches select the
    // static universe; the runtime contract still carries the key (rendered
    // below from the automatic set) so pinned runtimes keep parsing it.
    /// Per-provider `runs-on` routing. The only place labels live.
    pub(crate) selectors: provider::SelectorMap,
    pub(crate) release_enabled: bool,
    pub(crate) release_reason: String,
    pub(crate) release: Option<ReleaseSpec>,
    pub(crate) renovate_enabled: bool,
    pub(crate) renovate_reason: String,
    pub(crate) renovate: Option<RenovateSpec>,
    pub(crate) docs_enabled: bool,
    pub(crate) docs_reason: String,
    pub(crate) docs: Option<DocsSpec>,
    /// Composable scheduled-check profiles from `[[check_profile]]` rows.
    /// Generation time only: the rendered schedules carry them, and pinned
    /// runtimes would reject them as unknown fields.
    pub(crate) check_profiles: Vec<CheckProfileSpec>,
    pub(crate) maintenance: MaintenanceSpec,
    pub(crate) units: Vec<Unit>,
    pub(crate) workflow_templates: BTreeMap<String, String>,
    pub(crate) adopted_workflow_surface: bool,
    /// Emit `config-variables: null` in the generated actionlint configuration,
    /// disabling its configuration-variables check for surfaces that declare
    /// none.
    pub(crate) actionlint_config_variables_null: bool,
    /// Require the generated CI aggregate check to conclude the workflow.
    pub(crate) ci_required: bool,
    /// Status-check contexts the repository ruleset gates on that `ci-pr.yml`
    /// or `ci-policy.yml` must expose as job display names.
    pub(crate) ruleset_required_status_checks: Vec<String>,
    /// Status-check contexts the repository ruleset gates on that GitHub Apps
    /// report rather than workflows.
    pub(crate) ruleset_external_status_checks: Vec<String>,
    /// Per-owner-block update channel grants from the repo-owned generation
    /// config, or `None` while the repository has not adopted a config.
    pub(crate) package_update_channels: Option<BTreeMap<String, Vec<String>>>,
    /// How Rust unit jobs relate through GitHub Actions `needs:`.
    pub(crate) rust_needs: RustNeeds,
    /// Repository-scoped local-provider concurrency group for PR recovery;
    /// Main aggregates append `github.run_id` to keep unrelated executions
    /// concurrent.
    pub(crate) concurrency_group: Option<String>,
    /// Serialize aggregate stack-group callers on local providers.
    pub(crate) serial_stack_groups: bool,
    /// Repository-local files the generated output owns verbatim, read from
    /// the declared sources at scan time.
    pub(crate) static_files: Vec<StaticFile>,
    /// Reviewer rules from `[[reviewers]]` rows, in declaration order.
    /// Generation time only: they render into `.github/CODEOWNERS`, never
    /// into the runtime contract. Empty renders no file.
    pub(crate) reviewers: Vec<ReviewerRule>,
    /// The repository states its own surface in a generation config: the
    /// checked-in `.github/workflows` are outputs and are never adopted as
    /// inputs.
    pub(crate) declared_surface: bool,
    /// Tool keys the root `mise.lock` pins, read at scan time. Declared
    /// `mise_tools` must equal one of these, and detected `install_args`
    /// resolve their spelling from these; empty when the scan root has no
    /// lock, in which case identity checking is skipped. Never serialized:
    /// the lock itself is the source of truth.
    pub(crate) mise_lock_keys: BTreeSet<String>,
    /// Install dependencies the root `mise.toml` declares, over which
    /// derived `install_args` subsets close. Empty when the scan root has
    /// no mise configuration. Never serialized: the config itself is the
    /// source of truth.
    pub(crate) mise_install_deps: config::MiseInstallDeps,
    /// Generator-only GitHub cache retention from `[cache.github]`. Never
    /// serialized into `project.toml`.
    pub(crate) github_cache: config::CacheGithubSection,
    /// Generator-only Velnor host cache budgets from `[cache.velnor]`. Never
    /// serialized into `project.toml`.
    pub(crate) velnor_host_cache: config::CacheVelnorSection,
    /// The repository's own parsed Rust pin, recorded at stamp time. Scanned
    /// units carry a clone each, but a declared per-unit channel is
    /// indistinguishable from the pin without the file's own fact — so the
    /// renderer reads this to tell the file-driven pin leg from explicit
    /// channel legs. Generation time only: never serialized into
    /// `project.toml`, where pinned runtimes would reject it.
    pub(crate) rust_pin: Option<RustToolchain>,
}

/// A repository-local file the generated output owns verbatim: the repository
/// owns the bytes at `source`, the generator owns the write to `path`.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct StaticFile {
    pub(crate) path: String,
    pub(crate) source: String,
    pub(crate) content: String,
}

/// One CODEOWNERS rule: a file pattern and its owners, in declaration order.
#[derive(Clone, Debug, Eq, PartialEq)]
pub(crate) struct ReviewerRule {
    pub(crate) pattern: String,
    pub(crate) owners: Vec<String>,
}

fn default_workflow_files() -> Vec<String> {
    vec![
        "ci-pr.yml".to_owned(),
        "ci-policy.yml".to_owned(),
        "ci-main.yml".to_owned(),
        "nightly.yml".to_owned(),
        "maintenance.yml".to_owned(),
    ]
}

impl ProjectConfig {
    #[expect(
        clippy::too_many_lines,
        reason = "the generated TOML keeps the complete checked-in runtime contract together"
    )]
    fn toml(&self) -> String {
        let mut output = String::from(GENERATED_HEADER);
        output.push_str("schema = 3\n");
        if !self.repository.is_empty() {
            write_toml_string(&mut output, "repository", &self.repository);
        }
        write_toml_string(&mut output, "profile", &self.profile);
        let _ = writeln!(output, "verified = {}", self.verified);
        write_toml_string(&mut output, "default_branch", &self.default_branch);
        write_toml_array(
            &mut output,
            "providers",
            &self
                .providers
                .iter()
                .map(|provider| provider.as_str().to_owned())
                .collect::<Vec<_>>(),
        );
        write_toml_array(
            &mut output,
            "automatic_providers",
            &self
                .automatic_providers
                .iter()
                .map(|provider| provider.as_str().to_owned())
                .collect::<Vec<_>>(),
        );
        // The dispatch default is the automatic set: dispatches select the
        // static universe. The key stays so pinned runtimes keep parsing the
        // contract they were built against.
        write_toml_array(
            &mut output,
            "default_dispatch_providers",
            &self
                .automatic_providers
                .iter()
                .map(|provider| provider.as_str().to_owned())
                .collect::<Vec<_>>(),
        );
        output.push('\n');
        output.push_str("[analysis]\n");
        write_toml_string(&mut output, "method", &self.analysis.method);
        write_toml_array(&mut output, "detected", &self.analysis.detected);
        write_toml_array(&mut output, "limitations", &self.analysis.limitations);
        output.push('\n');
        output.push_str("[workflow]\n");
        // Selectors are generation-time only: the generated `runs-on` routing
        // carries them; the runtime planner needs only the provider sets.
        let generated_workflows = workflow_file_names(self);
        write_toml_array(&mut output, "files", &generated_workflows);
        if !self.notes.is_empty() {
            write_toml_array(&mut output, "notes", &self.notes);
        }
        if !self.version_bump_units.is_empty() {
            write_toml_array(&mut output, "version_bump_units", &self.version_bump_units);
        }
        output.push('\n');
        output.push_str("[release]\n");
        let _ = writeln!(output, "enabled = {}", self.release_enabled);
        write_toml_string(&mut output, "reason", &self.release_reason);
        if let Some(release) = &self.release {
            write_toml_string(&mut output, "kind", &release.kind);
            if !release.package.is_empty() {
                write_toml_string(&mut output, "package", &release.package);
            }
            write_toml_array(&mut output, "packages", &release.packages);
            if !release.binary.is_empty() {
                write_toml_string(&mut output, "binary", &release.binary);
            }
            write_toml_array(&mut output, "targets", &release.targets);
            if !release.image.is_empty() {
                write_toml_string(&mut output, "image", &release.image);
            }
            if !release.source_repository.is_empty() {
                write_toml_string(&mut output, "source_repository", &release.source_repository);
            }
            if !release.consumer_repository.is_empty() {
                write_toml_string(
                    &mut output,
                    "consumer_repository",
                    &release.consumer_repository,
                );
            }
            if !release.artifact_path.is_empty() {
                write_toml_string(&mut output, "artifact_path", &release.artifact_path);
            }
            if !release.description.is_empty() {
                write_toml_string(&mut output, "description", &release.description);
            }
            // `manifest_schema` is generation-time only. The config-to-spec
            // path carries it to the release renderer; pinned runtimes reject
            // it as an unknown field before Planning can start. The `docker`
            // publisher's `dockerfile`, `context`, and `platforms` stay
            // generation-time only for the same reason: no runtime command
            // consumes them. The `[[release.image]]` rows stay with them:
            // `images` renders into the workflow graph and is never carried
            // to a pinned runtime.
        }
        for unit in &self.units {
            output.push_str("\n[[unit]]\n");
            write_toml_string(&mut output, "id", &unit.id);
            write_toml_string(&mut output, "label", &unit.label);
            write_toml_string(&mut output, "kind", unit.kind.id_prefix());
            write_toml_string(&mut output, "root", &unit.root);
            write_toml_array(&mut output, "watch", &unit.watch);
            write_toml_array(&mut output, "pr_commands", &unit.pr_commands);
            write_toml_array(&mut output, "full_commands", &unit.full_commands);
            if unit.has_phases() {
                write_toml_array(
                    &mut output,
                    "phases",
                    &ValidationPhase::id_list(&unit.phases),
                );
                write_toml_array(&mut output, "check_commands", &unit.check_commands);
            }
            if !unit.depends_on.is_empty() {
                write_toml_array(&mut output, "depends_on", &unit.depends_on);
            }
            // A uniform `complete` read contract closes the unit for the
            // runtime classifier. Emitted only when true: pinned Planning
            // runtimes deny unknown unit fields, so trees without complete
            // contracts must render not one byte of difference.
            if unit.reads_closed {
                let _ = writeln!(output, "reads_closed = true");
            }
            if let Some(version) = &unit.tool_version {
                write_toml_string(&mut output, "tool_version", version);
            }
            write_toml_string(&mut output, "platform", unit.platform.as_str());
            write_toml_string(&mut output, "trust", unit.trust.as_str());
            if unit.workspace_check {
                let _ = writeln!(output, "workspace_check = true");
            }
            output.push_str("[unit.capabilities]\n");
            let capabilities = [
                ("docker", unit.capabilities.docker),
                (
                    "nested_privileged_docker",
                    unit.capabilities.nested_privileged_docker,
                ),
                ("buildx_compose", unit.capabilities.buildx_compose),
                ("testcontainers", unit.capabilities.testcontainers),
                (
                    "services_with_readiness",
                    unit.capabilities.services_with_readiness,
                ),
                ("browser_binaries", unit.capabilities.browser_binaries),
                ("native_macos_arm64", unit.capabilities.native_macos_arm64),
            ];
            for (name, enabled) in capabilities {
                let _ = writeln!(output, "{name} = {enabled}");
            }
            if let Some(cache) = &unit.cache {
                output.push_str("[unit.cache]\n");
                write_toml_array(&mut output, "key_files", &cache.key_files);
                write_toml_array(&mut output, "paths", &cache.paths);
            }
        }
        output
    }
}

fn toml_escape(value: &str) -> String {
    let mut escaped = String::with_capacity(value.len());
    for char in value.chars() {
        match char {
            '\\' => escaped.push_str("\\\\"),
            '"' => escaped.push_str("\\\""),
            '\n' => escaped.push_str("\\n"),
            '\r' => escaped.push_str("\\r"),
            '\t' => escaped.push_str("\\t"),
            other if other.is_control() => {
                let _ = write!(escaped, "\\u{:04X}", other as u32);
            }
            other => escaped.push(other),
        }
    }
    escaped
}

fn write_toml_string(output: &mut String, name: &str, value: &str) {
    let escaped = toml_escape(value);
    let _ = writeln!(output, "{name} = \"{escaped}\"");
}

fn write_toml_array(output: &mut String, name: &str, values: &[String]) {
    let values = values
        .iter()
        .map(|value| format!("\"{}\"", toml_escape(value)))
        .collect::<Vec<_>>()
        .join(", ");
    let _ = writeln!(output, "{name} = [{values}]");
}

/// Scan a local repository without evaluating project-controlled files.
///
/// # Errors
/// Returns filesystem errors with the affected path.
#[cfg_attr(not(test), allow(dead_code))]
pub(crate) fn scan_repository(
    root: &Path,
    providers: Option<provider::ProviderSet>,
) -> Result<ProjectConfig, GeneratorError> {
    scan_repository_with_default_branch(root, providers, "main")
}

#[cfg_attr(not(test), allow(dead_code))]
fn scan_repository_with_default_branch(
    root: &Path,
    providers: Option<provider::ProviderSet>,
    default_branch: &str,
) -> Result<ProjectConfig, GeneratorError> {
    Ok(scan_target(root, providers, default_branch)?.config)
}

/// One scan pass over a repository: the shape, the optional repo-owned
/// generation config, and the generation inputs they pin together.
#[derive(Clone, Debug, PartialEq)]
struct ScannedTarget {
    shape: scan::RepositoryShape,
    config: ProjectConfig,
    generation: Option<config::RepoGenerationConfig>,
    inputs: GenerationInputs,
}

/// Enforce the visibility-based runner policy on the resolved provider
/// selection: the universe and the automatic set must equal the visibility
/// evidence's singleton, every declared selector must belong to that
/// universe, and the selectors must carry the real provider identities —
/// GitHub-owned labels for hosted, exactly the Velnor fleet identity for
/// Velnor. Absent provider sets derive the singleton; anything declared
/// that contradicts it is an explicit error naming the evidence.
fn enforce_visibility_policy(
    config: &mut ProjectConfig,
    generation: Option<&config::RepoGenerationConfig>,
    cli_providers: bool,
    root: &Path,
) -> Result<(), GeneratorError> {
    // The evidence module speaks the crate-root error type; both carry a
    // single message string, so the bridge maps across without losing
    // context.
    let evidence =
        crate::visibility::load(root).map_err(|error| GeneratorError::usage(error.to_string()))?;
    crate::visibility::check_slug_binding(
        &evidence,
        generation.and_then(config::RepoGenerationConfig::repository),
    )
    .map_err(|error| GeneratorError::usage(error.to_string()))?;
    let expected = provider::singleton_for_visibility(evidence.visibility);
    let expected_name = expected
        .iter()
        .map(provider::ProviderId::as_str)
        .collect::<Vec<_>>()
        .join(", ");
    let evidence_note = format!(
        "the repository visibility evidence ({}: {:?} for {}) requires [{expected_name}]",
        crate::visibility::VISIBILITY_EVIDENCE_PATH,
        evidence.visibility.as_str(),
        evidence.repository,
    );
    let declared_source = if generation.is_some_and(|generation| generation.providers().is_some()) {
        Some("[workflow] providers")
    } else if cli_providers {
        Some("--providers")
    } else {
        None
    };
    if let Some(source) = declared_source {
        if config
            .providers
            .contains(&provider::ProviderId::GithubSelfHosted)
        {
            return Err(GeneratorError::usage(format!(
                "unsupported provider `github-self-hosted` in {source}: the visibility-based runner policy admits only `github-hosted` (public repositories) and `velnor` (private repositories); {evidence_note}"
            )));
        }
        if config.providers != expected {
            let declared = config
                .providers
                .iter()
                .map(provider::ProviderId::as_str)
                .collect::<Vec<_>>()
                .join(", ");
            return Err(GeneratorError::usage(format!(
                "contradictory runner selection: {source} selects [{declared}], but {evidence_note} — public repositories run on GitHub-hosted runners only, private repositories on Velnor runners only"
            )));
        }
    } else {
        config.providers.clone_from(&expected);
    }
    let automatic_declared =
        generation.is_some_and(|generation| generation.automatic_providers().is_some());
    if automatic_declared {
        if config.automatic_providers != expected {
            let declared = config
                .automatic_providers
                .iter()
                .map(provider::ProviderId::as_str)
                .collect::<Vec<_>>()
                .join(", ");
            return Err(GeneratorError::usage(format!(
                "contradictory runner selection: [workflow] automatic_providers selects [{declared}], but {evidence_note}"
            )));
        }
    } else {
        config.automatic_providers.clone_from(&expected);
    }
    // Declared selectors must stay inside the visibility universe; the scan
    // seeds defaults for every provider, so only declared tables are judged.
    if let Some(generation) = generation {
        for key in generation.selectors().keys() {
            let provider = provider::ProviderId::parse(key).map_err(|_| {
                GeneratorError::usage(format!(
                    "[workflow.selectors] has unknown provider `{key}`; expected one of: github-hosted, github-self-hosted, velnor"
                ))
            })?;
            if !expected.contains(&provider) {
                return Err(GeneratorError::usage(format!(
                    "contradictory runner selection: [workflow.selectors.{provider}] declares routing for a provider no job can use, but {evidence_note}; remove the selector"
                )));
            }
        }
    }
    validate_visibility_selector_identities(config, &expected, &evidence_note)?;
    enforce_visibility_job_routing(config, evidence.visibility, &expected, &evidence_note)?;
    Ok(())
}

/// Every named lane outside the CI aggregate follows the same visibility
/// singleton: scheduled-check profiles, release verification sets, typed
/// release jobs, and native release targets. macOS lanes are GitHub-hosted
/// by construction, so they contradict private evidence; Velnor lanes
/// contradict public evidence. Undeclared lanes default to `github`, which
/// is itself a contradiction on a private repository — declare the lane.
fn enforce_visibility_job_routing(
    config: &ProjectConfig,
    visibility: crate::visibility::Visibility,
    expected: &provider::ProviderSet,
    evidence_note: &str,
) -> Result<(), GeneratorError> {
    for profile in &config.check_profiles {
        let is_velnor = profile.runner.as_str() == "velnor";
        if is_velnor == visibility.is_public() {
            return Err(GeneratorError::usage(format!(
                "contradictory runner selection: [[check_profile]] `{}` runs on `{}` (macOS counts as GitHub-hosted), but {evidence_note}",
                profile.id, profile.runner
            )));
        }
    }
    let Some(release) = config.release.as_ref() else {
        return Ok(());
    };
    if let Some(verification) = release.verification_providers.as_ref()
        && verification != expected
    {
        let declared = verification
            .iter()
            .map(provider::ProviderId::as_str)
            .collect::<Vec<_>>()
            .join(", ");
        return Err(GeneratorError::usage(format!(
            "contradictory runner selection: [release] verification_providers selects [{declared}], but {evidence_note}"
        )));
    }
    if !visibility.is_public() {
        for target in &release.targets {
            if target.ends_with("-apple-darwin") {
                return Err(GeneratorError::usage(format!(
                    "contradictory runner selection: [release] target `{target}` builds on the fixed macOS hosted image, but {evidence_note}; Velnor serves linux-x64 only"
                )));
            }
        }
    }
    for job in &release.jobs {
        let is_velnor = job.runner.as_str() == "velnor";
        if is_velnor == visibility.is_public() {
            return Err(GeneratorError::usage(format!(
                "contradictory runner selection: [[release.job]] `{}` runs on `{}` (macOS counts as GitHub-hosted), but {evidence_note}",
                job.id, job.runner
            )));
        }
    }
    Ok(())
}

/// The visibility provider's selector must carry the real provider
/// identity: a bare `self-hosted` label proves nothing, and a hosted
/// selector with caller-managed labels would route a hosted-only tree off
/// GitHub-owned runners. The merged selector is judged, so the scan default
/// applies when the repository declares nothing — and the Velnor default is
/// deliberately not the fleet identity, so private repositories must declare
/// their real routing.
fn validate_visibility_selector_identities(
    config: &ProjectConfig,
    expected: &provider::ProviderSet,
    evidence_note: &str,
) -> Result<(), GeneratorError> {
    if expected.contains(&provider::ProviderId::Velnor)
        && let Some(selector) = config.selectors.get(&provider::ProviderId::Velnor)
        && !estate::is_velnor_fleet_identity(&selector.runs_on)
    {
        return Err(GeneratorError::usage(format!(
            "contradictory runner selection: [workflow.selectors.velnor] runs_on [{}] is not the Velnor fleet identity — a bare `self-hosted` label proves nothing; the selector must be exactly [{}], but {evidence_note}",
            selector.runs_on.join(", "),
            estate::VELNOR_FLEET_RUNS_ON.join(", ")
        )));
    }
    if expected.contains(&provider::ProviderId::GithubHosted)
        && let Some(selector) = config.selectors.get(&provider::ProviderId::GithubHosted)
    {
        for label in &selector.runs_on {
            if !provider::is_github_owned_label(label) {
                return Err(GeneratorError::usage(format!(
                    "contradictory runner selection: [workflow.selectors.github-hosted] runs_on carries {label:?}, which is not a GitHub-owned label (ubuntu-*|macos-*|windows-*); hosted selectors must stay GitHub-owned so a hosted-only tree cannot route onto caller-managed runners, but {evidence_note}"
                )));
            }
        }
    }
    Ok(())
}

fn scan_target(
    root: &Path,
    providers: Option<provider::ProviderSet>,
    default_branch: &str,
) -> Result<ScannedTarget, GeneratorError> {
    let cli_providers = providers.is_some();
    let generation = config::discover(root)?;
    let exclude = generation
        .as_ref()
        .map(config::RepoGenerationConfig::scan_exclude)
        .transpose()?
        .unwrap_or(&[]);
    // Precedence: CLI override, repo config, all three providers. No inference.
    let mut scan_providers = provider::ProviderId::ALL.into_iter().collect();
    if let Some(declared) = generation
        .as_ref()
        .and_then(|generation| generation.providers())
    {
        scan_providers = provider::parse_provider_set(declared, "[workflow] providers")?;
    }
    if let Some(override_providers) = providers {
        scan_providers = override_providers;
    }
    provider::require_non_empty(&scan_providers, "[workflow] providers")?;
    let scan_default_branch = generation
        .as_ref()
        .and_then(config::RepoGenerationConfig::default_branch)
        .unwrap_or(default_branch);
    let apple = scan::rust::AppleNativePolicy::from_declared(
        generation
            .as_ref()
            .and_then(|generation| generation.native_apple().cargo_profile.as_deref()),
        generation
            .as_ref()
            .and_then(|generation| generation.native_apple().deployment_floor.as_deref()),
    )?;
    let shape = scan::scan_shape(root, &scan_providers, scan_default_branch, exclude, &apple)?;
    let mut config = ProjectConfig::from(shape.clone());
    if let Some(generation) = &generation {
        apply_generation_config(&mut config, generation, root)?;
    }
    // The visibility policy pins the provider selection before anything
    // downstream resolves placement: every later stage sees the singleton.
    enforce_visibility_policy(&mut config, generation.as_ref(), cli_providers, root)?;
    // Prerequisites compile into the selection graph and prepare commands, and
    // placement is rejected before any byte renders, so every later stage —
    // mbxify, templates, validation — sees the resolved surface.
    platform::resolve(&mut config)?;
    // Generation config can replace scanned Rust commands after the first pass
    // (for example `workspace_check = true` rewrites the workspace gate back to
    // raw `cargo check`). Re-mbxify once all overrides are applied so every Rust
    // provider, including production topology, uses the same Mr. Boxington path.
    enable_mr_boxington_commands(&mut config);
    provider::require_subset(
        &config.automatic_providers,
        &config.providers,
        "[workflow] automatic_providers",
        "[workflow] providers",
    )?;
    // A repo-owned config can add Rust units the scan did not produce. They
    // compile with the repository's own pinned toolchain like every scanned
    // Rust unit, so the parsed pin is stamped onto any Rust unit that lacks
    // one; a repository with no pin leaves them unstamped for generation to
    // refuse. The `is_none` guard also preserves a declared per-unit channel:
    // stamping never overwrites one. The parsed pin is recorded as the
    // file's own fact so the renderer can tell the file-driven pin leg from
    // explicit channel legs.
    let rust_pin = scan::rust::parse_rust_toolchain_from_dir(root)?;
    if let Some(toolchain) = &rust_pin {
        for unit in &mut config.units {
            if unit.kind == UnitKind::Rust && unit.toolchain.is_none() {
                unit.toolchain = Some(toolchain.clone());
            }
        }
    }
    config.rust_pin = rust_pin;
    let mut config = load_workflow_templates(root, config, generation.as_ref())?;
    // The root lock's tool keys pin every mise id the surface may install:
    // `mise --locked` requires install args to equal the lock keys, so both
    // validation and rendering resolve against these instead of mandating a
    // spelling. Only the root lock is consulted; see
    // `config::mise_lock_keys_for_root` for the per-unit-lock gap.
    let mise_lock_keys = config::mise_lock_keys_for_root(root)?;
    config.mise_lock_keys.clone_from(&mise_lock_keys);
    // The root config's install edges close every derived subset: a subset
    // that omits a configured dependency fails at install time on the
    // runner, so both validation and rendering resolve against these.
    let mise_install_deps = config::mise_install_deps_for_root(root)?;
    config.mise_install_deps.clone_from(&mise_install_deps);
    validate_actionlint_pin_coherence(root)?;
    // The repo-owned config is validated against the resolved surface before
    // it can influence anything: a declared unit the scan did not find, or a
    // channel grant for an owner block the render does not declare, is a hard
    // error, never a silent no-op.
    if let Some(generation) = &generation {
        config.package_update_channels = generation.package_update_channels();
        let unit_ids = config
            .units
            .iter()
            .map(|unit| unit.id.clone())
            .collect::<Vec<_>>();
        let blocks = package_update_owner_blocks(&config);
        let blocks = blocks.iter().map(String::as_str).collect::<Vec<_>>();
        generation.validate(&unit_ids, &blocks, &mise_lock_keys)?;
    }
    // A unit that needs nextest while the lock pins neither spelling would
    // render `install_args` the runner's own lock check rejects; refuse it at
    // generation time instead of shipping a failing job.
    crate::s2::primitives::validate_nextest_tools_are_locked(&config.units, &mise_lock_keys)?;
    // A unit that runs the joined BoltFFI pack while the lock does not pin
    // its tool id would fail at pack time instead; refuse it at generation
    // time with the exact missing key.
    crate::s2::primitives::validate_boltffi_tools_are_locked(&config.units, &mise_lock_keys)?;
    // A unit that runs XcodeGen while the lock does not pin its tool id
    // would fail at install time on the runner instead; refuse it at
    // generation time with the exact missing key.
    crate::s2::primitives::validate_xcodegen_tools_are_locked(&config.units, &mise_lock_keys)?;
    // A subset that omits a configured install dependency fails at install
    // time on the runner instead; refuse it at generation time with the
    // exact missing edge.
    crate::s2::primitives::validate_mise_install_deps_are_closed(
        &config.units,
        &mise_lock_keys,
        &mise_install_deps,
    )?;
    // Every surface that renders a self-hosted lane must name its labels,
    // whether the rest of the contract is scanned or declared.
    validate_provider_selectors(&config)?;
    validate_unit_capabilities(&config)?;
    validate_unit_phases(&config)?;
    let inputs = GenerationInputs::current(generation.as_ref(), &shape)?;
    Ok(ScannedTarget {
        shape,
        config,
        generation,
        inputs,
    })
}

pub(crate) fn enable_mr_boxington_commands(config: &mut ProjectConfig) {
    for unit in &mut config.units {
        if unit.kind == UnitKind::Rust && unit.uses_mbx() {
            unit.pr_commands = unit
                .pr_commands
                .iter()
                .map(|command| mbxify_cargo_command(command))
                .collect();
            unit.full_commands = unit
                .full_commands
                .iter()
                .map(|command| mbxify_cargo_command(command))
                .collect();
            unit.check_commands = unit
                .check_commands
                .iter()
                .map(|command| mbxify_cargo_command(command))
                .collect();
        }
        unit.watch.sort();
        unit.watch.dedup();
    }
    refresh_mr_boxington_note(config);
    refresh_swift_executor_note(config);
}

/// A Swift unit the scan cannot prove Apple-bound renders on Linux
/// providers, where no Swift toolchain is provisioned by the generator.
/// Name those units in the contract notes so an Apple-bound package (Xcode
/// schemes, `XCFramework` binary targets, Apple-only SDKs) the scan missed
/// gets its `platform` declaration instead of a toolchain failure three jobs
/// into CI.
fn refresh_swift_executor_note(config: &mut ProjectConfig) {
    const PREFIX: &str = "Swift units render on Linux providers: ";
    config.notes.retain(|note| !note.starts_with(PREFIX));
    let defaulted: Vec<String> = config
        .units
        .iter()
        .filter(|unit| {
            unit.kind == UnitKind::Swift && unit.platform != provider::Platform::MacosArm64
        })
        .map(|unit| unit.id.clone())
        .collect();
    if defaulted.is_empty() {
        return;
    }
    config.notes.push(format!(
        "{PREFIX}{} (no Apple platform detected; if Apple-bound, declare `platform = \"macos-arm64\"` on a [[units]] row, otherwise ensure a Swift toolchain provisions on the Linux selector).",
        defaulted.join(", "),
    ));
}

fn refresh_mr_boxington_note(config: &mut ProjectConfig) {
    const PREFIX: &str = "Rust verification uses Mr. Boxington ";
    config.notes.retain(|note| !note.starts_with(PREFIX));
    if !config.units.iter().any(|unit| unit.kind == UnitKind::Rust) {
        return;
    }
    let providers = config
        .providers
        .iter()
        .map(provider::ProviderId::as_str)
        .collect::<Vec<_>>()
        .join(", ");
    config.notes.push(format!(
        "Rust verification uses Mr. Boxington {MR_BOXINGTON_VERSION} on providers [{providers}]. GitHub-hosted jobs use its GitHub cache backend with bounded snapshot keys (a key names the toolchain/image/linker compatibility class and the hashed source state, so a new source state saves a new snapshot and retention keeps generations bounded). Local-provider jobs use an explicit local-backend setup step against the image/runner-provided local store."
    ));
}

fn mbxify_cargo_command(command: &str) -> String {
    if command.contains("velnor-workflow test-crates") {
        return if command.contains(MR_BOXINGTON_ENABLED_ENV) {
            command.to_owned()
        } else {
            format!("{MR_BOXINGTON_ENABLED_ENV}=1 {command}")
        };
    }
    mbxify_cargo_invocations(command).0
}

fn is_mr_boxington_cargo_subcommand(token: &str) -> bool {
    MR_BOXINGTON_CARGO_SUBCOMMANDS.contains(&token)
}

fn next_shell_token(input: &str, start: usize) -> Option<(usize, usize)> {
    let start = start
        + input[start..]
            .bytes()
            .take_while(u8::is_ascii_whitespace)
            .count();
    let first = *input.as_bytes().get(start)?;
    if matches!(first, b'\'' | b'"') {
        let mut index = start + 1;
        while index < input.len() {
            if input.as_bytes()[index] == first {
                return Some((start, index + 1));
            }
            index += 1;
        }
        return None;
    }
    let end = start
        + input[start..]
            .bytes()
            .take_while(|byte| !byte.is_ascii_whitespace())
            .count();
    Some((start, end))
}

fn is_word_boundary_before(input: &str, index: usize) -> bool {
    input
        .as_bytes()
        .get(index.wrapping_sub(1))
        .is_none_or(|byte| !byte.is_ascii_alphanumeric() && *byte != b'_' && *byte != b'-')
}

fn is_cargo_token(input: &str, index: usize) -> bool {
    input
        .get(index..index + "cargo".len())
        .is_some_and(|token| token == "cargo")
        && is_word_boundary_before(input, index)
        && input
            .as_bytes()
            .get(index + "cargo".len())
            .is_some_and(u8::is_ascii_whitespace)
}

fn is_mbx_token(input: &str, index: usize) -> bool {
    input
        .get(index..index + "mbx".len())
        .is_some_and(|token| token == "mbx")
        && is_word_boundary_before(input, index)
        && input
            .as_bytes()
            .get(index + "mbx".len())
            .is_some_and(u8::is_ascii_whitespace)
}

fn is_shell_command_separator(token: &str) -> bool {
    matches!(token, "&&" | "||" | "|" | ";" | "&")
}

fn strip_mbx_no_deps(input: &str) -> String {
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    let mut mbx_pending_subcommand = false;
    let mut mbx_check_or_clippy = false;
    while let Some((start, end)) = next_shell_token(input, cursor) {
        if input[cursor..start].contains('\n') {
            mbx_pending_subcommand = false;
            mbx_check_or_clippy = false;
        }
        let token = &input[start..end];
        if mbx_check_or_clippy && token == "--no-deps" {
            // Mr. Boxington's check and clippy wrappers intentionally do not
            // expose Cargo's `--no-deps` option.
            cursor = end;
        } else {
            output.push_str(&input[cursor..end]);
            cursor = end;
        }

        if is_shell_command_separator(token) {
            mbx_pending_subcommand = false;
            mbx_check_or_clippy = false;
        } else if mbx_check_or_clippy {
            // Keep the state until the shell command ends so flags can be
            // removed regardless of their position in the invocation.
        } else if mbx_pending_subcommand {
            if matches!(token, "check" | "clippy") {
                mbx_pending_subcommand = false;
                mbx_check_or_clippy = true;
            } else if !token.starts_with('+') || token.len() == 1 {
                mbx_pending_subcommand = false;
            }
        } else if token == "mbx" {
            mbx_pending_subcommand = true;
        }
    }
    output.push_str(&input[cursor..]);
    output
}

fn mbxify_rustup_cargo_invocations(input: &str) -> (String, bool) {
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    let mut changed = false;
    while let Some(relative_start) = input[cursor..].find("rustup run ") {
        let start = cursor + relative_start;
        if !is_word_boundary_before(input, start) {
            cursor = start + "rustup".len();
            continue;
        }
        let toolchain_start = start + "rustup run ".len();
        let Some((toolchain_start, toolchain_end)) = next_shell_token(input, toolchain_start)
        else {
            cursor = toolchain_start;
            continue;
        };
        let Some((cargo_start, cargo_end)) = next_shell_token(input, toolchain_end) else {
            cursor = toolchain_end;
            continue;
        };
        if !is_cargo_token(input, cargo_start) {
            cursor = cargo_end;
            continue;
        }
        let Some((subcommand_start, subcommand_end)) = next_shell_token(input, cargo_end) else {
            cursor = cargo_end;
            continue;
        };
        let subcommand = &input[subcommand_start..subcommand_end];
        if !is_mr_boxington_cargo_subcommand(subcommand) {
            cursor = subcommand_end;
            continue;
        }
        output.push_str(&input[cursor..start]);
        output.push_str("mbx +");
        output.push_str(&input[toolchain_start..toolchain_end]);
        cursor = cargo_end;
        changed = true;
    }
    output.push_str(&input[cursor..]);
    (output, changed)
}

fn mbxify_cargo_invocations(input: &str) -> (String, bool) {
    let (input, rustup_changed) = mbxify_rustup_cargo_invocations(input);
    let mut output = String::with_capacity(input.len());
    let mut cursor = 0;
    let mut changed = rustup_changed;
    while let Some(relative_start) = input[cursor..].find("cargo") {
        let start = cursor + relative_start;
        if !is_cargo_token(&input, start) {
            output.push_str(&input[cursor..start + "cargo".len()]);
            cursor = start + "cargo".len();
            continue;
        }
        let cargo_end = start + "cargo".len();
        let Some((subcommand_start, subcommand_end)) = next_shell_token(&input, cargo_end) else {
            output.push_str(&input[cursor..]);
            return (output, changed);
        };
        let subcommand = &input[subcommand_start..subcommand_end];
        output.push_str(&input[cursor..start]);
        if is_mr_boxington_cargo_subcommand(subcommand) {
            output.push_str("mbx");
            changed = true;
        } else {
            output.push_str("cargo");
        }
        cursor = cargo_end;
    }
    output.push_str(&input[cursor..]);
    let normalized = strip_mbx_no_deps(&output);
    let changed = changed || normalized != output;
    (normalized, changed)
}

/// The GitHub-backend Mr. Boxington step a static template job gains when it
/// runs Cargo through mbx without declaring the action itself: the store
/// budget export, then the pinned action.
fn static_mr_boxington_step() -> String {
    let mut step = mr_boxington_store_budget_step();
    let _ = write!(
        step,
        "      - name: Set up Mr. Boxington\n        uses: {}\n        with:\n          backend: github\n          github-cache-mode: objects\n          version: {MR_BOXINGTON_VERSION}\n          cache-key: velnor-static-mbx-__VELNOR_SNAPSHOT_COMPATIBILITY__-${{{{ runner.os }}}}-${{{{ runner.arch }}}}-${{{{ github.workflow }}}}-${{{{ github.job }}}}-${{{{ hashFiles('Cargo.lock', 'rust-toolchain.toml', 'rust-toolchain', 'mise.toml', 'mise.lock', '**/Cargo.toml') }}}}-__VELNOR_SNAPSHOT_STATE__\n          restore-keys: |\n            velnor-static-mbx-__VELNOR_SNAPSHOT_COMPATIBILITY__-${{{{ runner.os }}}}-${{{{ runner.arch }}}}-${{{{ github.workflow }}}}-${{{{ github.job }}}}-${{{{ hashFiles('Cargo.lock', 'rust-toolchain.toml', 'rust-toolchain', 'mise.toml', 'mise.lock', '**/Cargo.toml') }}}}-\n            velnor-static-mbx-__VELNOR_SNAPSHOT_COMPATIBILITY__-${{{{ runner.os }}}}-${{{{ runner.arch }}}}-${{{{ github.workflow }}}}-${{{{ github.job }}}}-\n          save-on-workflow-dispatch: true\n",
        ActionPin::MrBoxington.reference()
    );
    step
}

fn static_workflow_job_ranges(lines: &[String]) -> Vec<(usize, usize)> {
    let Some(jobs_start) = lines.iter().position(|line| {
        line.trim_end_matches(['\n', '\r']) == "jobs:"
            && line.chars().take_while(char::is_ascii_whitespace).count() == 0
    }) else {
        return Vec::new();
    };
    let job_starts = lines
        .iter()
        .enumerate()
        .skip(jobs_start + 1)
        .take_while(|(_, line)| {
            let trimmed = line.trim();
            trimmed.is_empty()
                || line
                    .chars()
                    .next()
                    .is_some_and(|character| character.is_ascii_whitespace())
        })
        .filter_map(|(index, line)| {
            let trimmed = line.trim();
            let indentation = line.len() - line.trim_start().len();
            (indentation == 2 && trimmed.ends_with(':') && !trimmed.starts_with('-'))
                .then_some(index)
        })
        .collect::<Vec<_>>();
    job_starts
        .iter()
        .enumerate()
        .map(|(index, &start)| {
            let end = job_starts.get(index + 1).copied().unwrap_or(lines.len());
            (start, end)
        })
        .collect()
}

fn line_has_mbx_cargo_invocation(line: &str) -> bool {
    let mut cursor = 0;
    while let Some(relative_start) = line[cursor..].find("mbx") {
        let start = cursor + relative_start;
        if is_mbx_token(line, start) {
            let mbx_end = start + "mbx".len();
            let Some((token_start, token_end)) = next_shell_token(line, mbx_end) else {
                return false;
            };
            let token = &line[token_start..token_end];
            if let Some(toolchain) = token.strip_prefix('+') {
                if !toolchain.is_empty()
                    && next_shell_token(line, token_end).is_some_and(|(start, end)| {
                        is_mr_boxington_cargo_subcommand(&line[start..end])
                    })
                {
                    return true;
                }
            } else if is_mr_boxington_cargo_subcommand(token) {
                return true;
            }
        }
        cursor = start + "mbx".len();
    }
    false
}

fn static_workflow_step_start(line: &str) -> bool {
    line.len() - line.trim_start().len() == 6 && line.trim_start().starts_with("- ")
}

fn ensure_static_mr_boxington_steps(lines: &mut Vec<String>) {
    let ranges = static_workflow_job_ranges(lines);
    let mut insertions = Vec::new();
    for (job_start, job_end) in ranges {
        if !lines[job_start..job_end]
            .iter()
            .any(|line| line.contains("jdx/mr-boxington-action@"))
            && lines[job_start..job_end]
                .iter()
                .any(|line| line_has_mbx_cargo_invocation(line))
        {
            let Some(steps_start) = (job_start..job_end).find(|&index| {
                let line = &lines[index];
                line.len() - line.trim_start().len() == 4 && line.trim() == "steps:"
            }) else {
                continue;
            };
            let step_starts = (steps_start + 1..job_end)
                .filter(|&index| static_workflow_step_start(&lines[index]))
                .collect::<Vec<_>>();
            let insert_at = step_starts
                .iter()
                .enumerate()
                .find_map(|(index, &step_start)| {
                    let step_end = step_starts.get(index + 1).copied().unwrap_or(job_end);
                    lines[step_start..step_end]
                        .iter()
                        .any(|line| line.contains("actions/checkout@"))
                        .then_some(step_end)
                })
                .or_else(|| step_starts.first().copied())
                .unwrap_or(steps_start + 1);
            insertions.push((insert_at, static_mr_boxington_step()));
        }
    }
    for (index, step) in insertions.into_iter().rev() {
        lines.insert(index, step);
    }
}

fn refresh_static_mr_boxington_commands(template: &str) -> String {
    let mut lines = template
        .split_inclusive('\n')
        .map(str::to_owned)
        .collect::<Vec<_>>();
    for line in &mut lines {
        line.clone_from(&mbxify_cargo_invocations(line).0);
    }
    ensure_static_mr_boxington_steps(&mut lines);
    lines.concat()
}

fn load_workflow_templates(
    root: &Path,
    config: ProjectConfig,
    generation: Option<&config::RepoGenerationConfig>,
) -> Result<ProjectConfig, GeneratorError> {
    if let Some(declared) = generation.and_then(|generation| generation.templates_dir()) {
        return Err(GeneratorError::usage(format!(
            "[workflow] templates = \"{declared}\" is not supported; imported workflow bodies are not a generation input"
        )));
    }
    let directory = root.join(WORKFLOW_TEMPLATE_DIR);
    if directory.is_dir() {
        return Err(GeneratorError::usage(format!(
            "{} is not a generation input; remove the directory and regenerate from repository evidence plus typed config",
            directory.display()
        )));
    }
    Ok(config)
}

/// Apply the generation config a repository declares for itself. Every field
/// is optional: an absent one keeps the resolved scan default, which is what
/// lets a repository adopt the config one section at a time.
///
/// # Errors
/// Returns errors for a declared source file that is missing or unreadable.
fn validate_config_text(value: &str, field: &str) -> Result<(), GeneratorError> {
    if value.is_empty() || value.chars().any(char::is_control) {
        return Err(GeneratorError::usage(format!(
            "{field} must be non-empty and contain no control characters"
        )));
    }
    Ok(())
}

pub(crate) fn parse_rust_needs(value: &str) -> Result<RustNeeds, GeneratorError> {
    match value {
        "parallel" => Ok(RustNeeds::Parallel),
        "dependency-closure" => Ok(RustNeeds::DependencyClosure),
        _ => Err(GeneratorError::usage(format!(
            "[workflow] rust_needs must be one of: parallel, dependency-closure; found `{value}`"
        ))),
    }
}

/// Provider selection and placement: `[workflow]` provider universe,
/// automatic providers, per-provider selectors, dispatch defaults,
/// concurrency, and rust needs.
fn apply_provider_generation_config(
    config: &mut ProjectConfig,
    generation: &config::RepoGenerationConfig,
) -> Result<(), GeneratorError> {
    if let Some(providers) = generation.providers() {
        config.providers = provider::parse_provider_set(providers, "[workflow] providers")?;
        provider::require_non_empty(&config.providers, "[workflow] providers")?;
    }
    if let Some(automatic) = generation.automatic_providers() {
        config.automatic_providers =
            provider::parse_provider_set(automatic, "[workflow] automatic_providers")?;
    } else if generation.providers().is_some() {
        // The universe moved; the automatic set follows it unless declared.
        config.automatic_providers.clone_from(&config.providers);
    }
    provider::require_subset(
        &config.automatic_providers,
        &config.providers,
        "[workflow] automatic_providers",
        "[workflow] providers",
    )?;
    let selectors = provider::parse_selectors(generation.selectors())?;
    for (provider, selector) in selectors {
        config.selectors.insert(provider, selector);
    }
    provider::require_selectors_for(&config.selectors, &config.providers)?;
    provider::validate_selector_disjointness(&config.selectors)?;
    if let Some(rust_needs) = generation.rust_needs() {
        config.rust_needs = parse_rust_needs(rust_needs)?;
    }
    if let Some(group) = generation.concurrency_group() {
        validate_config_text(group, "[workflow] concurrency_group")?;
        config.concurrency_group = Some(group.to_owned());
    }
    if let Some(serial) = generation.serial_stack_groups() {
        config.serial_stack_groups = serial;
    }
    Ok(())
}

fn apply_generation_config(
    config: &mut ProjectConfig,
    generation: &config::RepoGenerationConfig,
    root: &Path,
) -> Result<(), GeneratorError> {
    if let Some(repository) = generation.repository() {
        repository.clone_into(&mut config.repository);
    }
    if let Some(revision) = generation.revision() {
        if !is_full_revision(revision) {
            return Err(GeneratorError::usage(format!(
                "[generator] revision must be a full 40-character commit SHA, got {revision:?}"
            )));
        }
        revision.clone_into(&mut config.workflow_revision);
    }
    apply_provider_generation_config(config, generation)?;
    if let Some(profile) = generation.profile() {
        profile.clone_into(&mut config.profile);
    }
    if let Some(verified) = generation.verified() {
        config.verified = verified;
    }
    if let Some(files) = generation.files() {
        config.workflow_files = files.to_vec();
    }
    if let Some(units) = generation.version_bump_units() {
        config.version_bump_units = units.to_vec();
    }
    if let Some(branch) = generation.default_branch() {
        validate_default_branch(branch)?;
        branch.clone_into(&mut config.default_branch);
    }
    if let Some(ci_required) = generation.ci_required() {
        config.ci_required = ci_required;
    }
    if !generation.ruleset_required_status_checks().is_empty() {
        config.ruleset_required_status_checks =
            generation.ruleset_required_status_checks().to_vec();
    }
    if !generation.ruleset_external_status_checks().is_empty() {
        config.ruleset_external_status_checks =
            generation.ruleset_external_status_checks().to_vec();
    }
    if let Some(null) = generation.actionlint_config_variables_null() {
        config.actionlint_config_variables_null = null;
    }
    apply_release(config, generation.release(), root)?;
    apply_renovate(config, generation.renovate(), root)?;
    apply_docs(config, generation.docs())?;
    apply_check_profiles(config, generation.check_profiles(), root)?;
    apply_maintenance(config, generation.maintenance())?;
    apply_unit_rows(config, generation.units(), root)?;
    materialize_capability_commands(config, root)?;
    read_static_files(config, generation.static_files(), root)?;
    apply_reviewer_rows(config, generation.reviewers());
    config.github_cache = generation.cache_github().clone();
    config.velnor_host_cache = generation.cache_velnor().clone();
    refresh_mr_boxington_note(config);
    refresh_swift_executor_note(config);
    config.declared_surface = true;
    Ok(())
}

fn discover_renovate_config(root: &Path, explicit: Option<&str>) -> Result<String, GeneratorError> {
    const CANDIDATES: &[&str] = &[
        "renovate.json",
        "renovate.json5",
        ".github/renovate.json",
        ".github/renovate.json5",
    ];
    if let Some(path) = explicit {
        let full = root.join(path);
        if !full.is_file() {
            return Err(GeneratorError::usage(format!(
                "[renovate] config path `{path}` does not exist in the repository"
            )));
        }
        return Ok(path.to_owned());
    }
    for candidate in CANDIDATES {
        if root.join(candidate).is_file() {
            return Ok((*candidate).to_owned());
        }
    }
    Err(GeneratorError::usage(
        "[renovate] enabled = true requires a Renovate config file; add renovate.json or declare `[renovate] config`",
    ))
}

fn apply_renovate(
    config: &mut ProjectConfig,
    renovate: &config::RenovateSection,
    root: &Path,
) -> Result<(), GeneratorError> {
    if let Some(enabled) = renovate.enabled() {
        config.renovate_enabled = enabled;
    }
    if let Some(reason) = renovate.reason() {
        reason.clone_into(&mut config.renovate_reason);
    }
    if renovate.enabled() != Some(true) {
        return Ok(());
    }
    let config_path = discover_renovate_config(root, renovate.config())?;
    if !config
        .analysis
        .detected
        .iter()
        .any(|tag| tag == "renovate-configuration")
    {
        config
            .analysis
            .detected
            .push("renovate-configuration".to_owned());
    }
    config.analysis.limitations.retain(|limitation| {
        !limitation.starts_with("Renovate credentials, runner placement, and write permissions")
    });
    let token = renovate.token().unwrap_or("GH_RENOVATE_TOKEN").to_owned();
    config::validate_renovate_token_name(&token)?;
    let schedule = renovate.schedule().unwrap_or("0 6 * * *").to_owned();
    config::validate_renovate_cron(&schedule)?;
    let mut schedules = Vec::new();
    for extra in renovate.schedules() {
        config::validate_renovate_cron(extra)?;
        if extra != &schedule && !schedules.contains(extra) {
            schedules.push(extra.clone());
        }
    }
    let mut repositories = Vec::new();
    for repository in renovate.repositories() {
        config::validate_renovate_repository_target(repository)?;
        if !repositories.contains(repository) {
            repositories.push(repository.clone());
        }
    }
    let host_rules_secret = match renovate.host_rules_secret() {
        Some(secret) => {
            config::validate_renovate_host_rules_secret(secret)?;
            Some(secret.to_owned())
        }
        None => None,
    };
    let author = match renovate.author() {
        Some(author) => {
            config::validate_renovate_git_author(author)?;
            Some(author.to_owned())
        }
        None => None,
    };
    let signoff = renovate.signoff().unwrap_or(false);
    if signoff && author.is_none() {
        return Err(GeneratorError::usage(
            "[renovate] signoff = true requires `author`: the Signed-off-by trailer names the author Renovate commits as",
        ));
    }
    let mut allowed_commands = Vec::new();
    for command in renovate.allowed_commands() {
        config::validate_renovate_allowed_command(command)?;
        if !allowed_commands.contains(command) {
            allowed_commands.push(command.clone());
        }
    }
    config.renovate = Some(RenovateSpec {
        enabled: true,
        reason: config.renovate_reason.clone(),
        schedule,
        schedules,
        token,
        config_path,
        validate: renovate.validate().unwrap_or(true),
        cache: renovate.cache().unwrap_or(true),
        repositories,
        host_rules_secret,
        author,
        signoff,
        allowed_commands,
    });
    Ok(())
}

/// The documentation-site contract a repository declares. `enabled` and
/// `reason` are the recorded decision; the rest is the contract the
/// `docs-site` primitive renders from. Like Renovate, the spec exists only
/// when enabled: disabled repositories render no `docs.yml`.
fn apply_docs(
    config: &mut ProjectConfig,
    docs: &config::DocsSection,
) -> Result<(), GeneratorError> {
    if let Some(enabled) = docs.enabled() {
        config.docs_enabled = enabled;
    }
    if let Some(reason) = docs.reason() {
        reason.clone_into(&mut config.docs_reason);
    }
    if docs.enabled() != Some(true) {
        return Ok(());
    }
    let site_url = docs.site_url().unwrap_or_default().to_owned();
    config::validate_docs_site_url(&site_url)?;
    let site_dir = docs.site_dir().unwrap_or_default().to_owned();
    config::validate_docs_path(&site_dir, "site_dir")?;
    let sitemap_path = docs.sitemap_path().unwrap_or("sitemap.xml").to_owned();
    config::validate_docs_path(&sitemap_path, "sitemap_path")?;
    for (field, commands) in [
        ("build_commands", docs.build_commands()),
        ("source_link_commands", docs.source_link_commands()),
        ("site_link_commands", docs.site_link_commands()),
        ("spell_commands", docs.spell_commands()),
        ("verify_commands", docs.verify_commands()),
        ("external_link_commands", docs.external_link_commands()),
    ] {
        for command in commands {
            config::validate_docs_command(command, field)?;
        }
    }
    if docs.build_commands().is_empty() {
        return Err(GeneratorError::usage(
            "[docs] enabled = true requires `build_commands`, the consumer-owned site build",
        ));
    }
    let schedule = match docs.schedule() {
        Some(schedule) => {
            config::validate_docs_cron(schedule)?;
            Some(schedule.to_owned())
        }
        None => None,
    };
    let docs_paths = match docs.docs_paths() {
        Some(paths) if !paths.is_empty() => paths.to_vec(),
        _ => default_docs_paths(),
    };
    config.docs = Some(DocsSpec {
        reason: config.docs_reason.clone(),
        site_url,
        site_dir,
        sitemap_path,
        schedule,
        build_commands: docs.build_commands().to_vec(),
        source_link_commands: docs.source_link_commands().to_vec(),
        site_link_commands: docs.site_link_commands().to_vec(),
        spell_commands: docs.spell_commands().to_vec(),
        verify_commands: docs.verify_commands().to_vec(),
        external_link_commands: docs.external_link_commands().to_vec(),
        docs_paths,
    });
    Ok(())
}

/// The generic reuse-digest path filters: Markdown sources plus the
/// conventional docs inputs. A repository that keeps its prose elsewhere
/// declares `[docs] docs_paths` instead.
fn default_docs_paths() -> Vec<String> {
    vec![
        "**/*.md".to_owned(),
        "mkdocs.yml".to_owned(),
        "docs/**".to_owned(),
    ]
}

/// The scheduled-check profiles a repository declares. Mapping is lenient —
/// the strict shape rules run in [`config::RepoGenerationConfig::validate`]
/// after every override is applied — but a task reference must name a task
/// the repository's `mise.toml` declares, like every unit `mise run` command.
fn apply_check_profiles(
    config: &mut ProjectConfig,
    rows: &[config::CheckProfileSection],
    root: &Path,
) -> Result<(), GeneratorError> {
    if rows.is_empty() {
        return Ok(());
    }
    let mise_tasks = parse_mise_task_names(root)?;
    let mut profiles = Vec::new();
    for row in rows {
        let id = row.id().unwrap_or_default();
        for task in row.tasks().unwrap_or_default() {
            if !mise_tasks.iter().any(|name| name == task) {
                return Err(GeneratorError::usage(format!(
                    "[[check_profile]] {id} names mise task `{task}`, which mise.toml does not declare"
                )));
            }
        }
        profiles.push(CheckProfileSpec {
            id: id.to_owned(),
            name: row.name().unwrap_or(id).to_owned(),
            schedule: row.schedule().unwrap_or_default().to_owned(),
            runner: row.runner().unwrap_or("github").to_owned(),
            tools: row.tools().unwrap_or_default().to_vec(),
            tasks: row.tasks().unwrap_or_default().to_vec(),
            needs: row.needs().unwrap_or_default().to_vec(),
            timeout_minutes: row
                .timeout_minutes()
                .and_then(|timeout| u32::try_from(timeout).ok())
                .unwrap_or(primitives::check_profiles::DEFAULT_CHECK_PROFILE_TIMEOUT_MINUTES),
            artifacts: row.artifacts().unwrap_or_default().to_vec(),
            advisory: row.status().is_some_and(|status| status == "advisory"),
            env: row.env().clone(),
            full_history: row.full_history(),
        });
    }
    config.check_profiles = profiles;
    Ok(())
}

fn apply_maintenance(
    config: &mut ProjectConfig,
    maintenance: &config::MaintenanceSection,
) -> Result<(), GeneratorError> {
    let mut spec = MaintenanceSpec::default();
    if let Some(schedule) = maintenance.schedule() {
        config::validate_maintenance_cron(schedule)?;
        schedule.clone_into(&mut spec.schedule);
    }
    if let Some(producers) = maintenance.producers() {
        if producers.is_empty() {
            return Err(GeneratorError::usage(
                "[maintenance] producers must name at least one producer workflow",
            ));
        }
        let mut declared = Vec::new();
        for producer in producers {
            config::validate_maintenance_producer(producer)?;
            if !declared.contains(producer) {
                declared.push(producer.clone());
            }
        }
        spec.producers = declared;
    }
    if let Some(max_deletes) = maintenance.max_deletes() {
        config::validate_maintenance_max_deletes(max_deletes)?;
        spec.max_deletes = max_deletes;
    }
    config.maintenance = spec;
    Ok(())
}

/// The release contract a repository declares. `enabled` and `reason` are the
/// recorded decision; the rest is the contract the publisher renders from.
#[allow(clippy::too_many_lines)]
fn apply_release(
    config: &mut ProjectConfig,
    release: &config::ReleaseSection,
    root: &Path,
) -> Result<(), GeneratorError> {
    if let Some(enabled) = release.enabled() {
        config.release_enabled = enabled;
    }
    if let Some(reason) = release.reason() {
        reason.clone_into(&mut config.release_reason);
    }
    let declared = release.kind().is_some()
        || release.verification_providers().is_some()
        || !release.packages().is_empty()
        || release.package().is_some()
        || release.binary().is_some()
        || !release.targets().is_empty()
        || release.image().is_some()
        || release.source_repository().is_some()
        || release.consumer_repository().is_some()
        || release.artifact_path().is_some()
        || release.description().is_some()
        || release.manifest_schema().is_some()
        || !release.apt_arches().is_empty()
        || release.signer_fingerprint().is_some()
        || release.passphrase_secret().is_some()
        || release.signing_key_secret().is_some()
        || release.keyring_path().is_some()
        || release.apt_origin().is_some()
        || release.apt_identity_dir().is_some()
        || release.apt_feed_url().is_some()
        || release.retention().is_some()
        || release.dockerfile().is_some()
        || release.context().is_some()
        || !release.platforms().is_empty()
        || release.producer_workflow().is_some()
        || release.producer_workflow_id().is_some()
        || release.producer_workflow_path().is_some()
        || release.producer_conclusion().is_some()
        || !release.modes().is_empty()
        || !release.archive_members().is_empty()
        || release.archive_checksum().is_some()
        || release.archive_retention_days().is_some()
        || !release.credentials().is_empty()
        || release.tag_pattern().is_some()
        || release.registry().is_some()
        || release.registry_username_secret().is_some()
        || release.registry_password_secret().is_some()
        || !release.jobs().is_empty()
        || !release.images().is_empty();
    if !declared {
        return Ok(());
    }
    let mut spec = config.release.clone().unwrap_or_default();
    if let Some(kind) = release.kind() {
        kind.clone_into(&mut spec.kind);
    }
    if let Some(providers) = release.verification_providers() {
        spec.verification_providers = Some(provider::parse_provider_set(
            providers,
            "[release] verification_providers",
        )?);
    }
    if let Some(package) = release.package() {
        package.clone_into(&mut spec.package);
    }
    if !release.packages().is_empty() {
        spec.packages = release.packages().to_vec();
    }
    if let Some(binary) = release.binary() {
        binary.clone_into(&mut spec.binary);
    }
    if !release.targets().is_empty() {
        spec.targets = release.targets().to_vec();
    }
    if let Some(image) = release.image() {
        image.clone_into(&mut spec.image);
    }
    if let Some(package) = release.image_package() {
        package.clone_into(&mut spec.image_package);
    }
    if let Some(source) = release.source_repository() {
        source.clone_into(&mut spec.source_repository);
    }
    if let Some(consumer) = release.consumer_repository() {
        consumer.clone_into(&mut spec.consumer_repository);
    }
    if let Some(artifact) = release.artifact_path() {
        artifact.clone_into(&mut spec.artifact_path);
    }
    if let Some(description) = release.description() {
        description.clone_into(&mut spec.description);
    }
    if let Some(schema) = release.manifest_schema() {
        schema.clone_into(&mut spec.manifest_schema);
    }
    if !release.apt_arches().is_empty() {
        spec.apt_arches = release.apt_arches().to_vec();
    }
    if let Some(signer) = release.signer_fingerprint() {
        signer.clone_into(&mut spec.signer_fingerprint);
    }
    if let Some(secret) = release.passphrase_secret() {
        secret.clone_into(&mut spec.passphrase_secret);
    }
    if let Some(secret) = release.signing_key_secret() {
        secret.clone_into(&mut spec.signing_key_secret);
    }
    if let Some(keyring) = release.keyring_path() {
        keyring.clone_into(&mut spec.keyring_path);
    }
    if let Some(origin) = release.apt_origin() {
        origin.clone_into(&mut spec.apt_origin);
    }
    if let Some(identity) = release.apt_identity_dir() {
        identity.clone_into(&mut spec.apt_identity_dir);
    }
    if let Some(feed) = release.apt_feed_url() {
        feed.clone_into(&mut spec.apt_feed_url);
    }
    if let Some(retention) = release.retention() {
        spec.retention = u32::try_from(retention).map_err(|_| {
            GeneratorError::usage(format!(
                "[release] retention must be a non-negative count, found `{retention}`"
            ))
        })?;
    }
    if let Some(dockerfile) = release.dockerfile() {
        dockerfile.clone_into(&mut spec.dockerfile);
    }
    if let Some(context) = release.context() {
        context.clone_into(&mut spec.context);
    }
    if !release.platforms().is_empty() {
        spec.platforms = release.platforms().to_vec();
    }
    if let Some(producer) = release.producer_workflow() {
        producer.clone_into(&mut spec.producer_workflow);
    }
    if let Some(workflow_id) = release.producer_workflow_id() {
        spec.producer_workflow_id = workflow_id;
    }
    if let Some(workflow_path) = release.producer_workflow_path() {
        workflow_path.clone_into(&mut spec.producer_workflow_path);
    }
    if let Some(conclusion) = release.producer_conclusion() {
        conclusion.clone_into(&mut spec.producer_conclusion);
    }
    if !release.modes().is_empty() {
        spec.modes = release.modes().to_vec();
    }
    if !release.archive_members().is_empty() {
        spec.archive_members = release.archive_members().to_vec();
    }
    if let Some(checksum) = release.archive_checksum() {
        checksum.clone_into(&mut spec.archive_checksum);
    }
    if let Some(retention) = release.archive_retention_days() {
        spec.archive_retention_days = u32::try_from(retention.clamp(0, 90)).unwrap_or(0);
    }
    if !release.credentials().is_empty() {
        spec.credentials = release
            .credentials()
            .iter()
            .map(|credential| ReleaseCredential {
                name: credential.name().unwrap_or_default().to_owned(),
                setup: credential.setup().unwrap_or_default().to_owned(),
                teardown: credential.teardown().unwrap_or_default().to_owned(),
            })
            .collect();
    }
    if let Some(pattern) = release.tag_pattern() {
        pattern.clone_into(&mut spec.tag_pattern);
    }
    if let Some(registry) = release.registry() {
        registry.clone_into(&mut spec.registry);
    }
    if let Some(secret) = release.registry_username_secret() {
        secret.clone_into(&mut spec.registry_username_secret);
    }
    if let Some(secret) = release.registry_password_secret() {
        secret.clone_into(&mut spec.registry_password_secret);
    }
    if !release.jobs().is_empty() {
        let mise_tasks = parse_mise_task_names(root)?;
        let mut jobs = Vec::new();
        for row in release.jobs() {
            let id = row.id().unwrap_or_default();
            for task in row.tasks().unwrap_or_default() {
                if !mise_tasks.iter().any(|name| name == task) {
                    return Err(GeneratorError::usage(format!(
                        "[[release.job]] {id} names mise task {task}, which mise.toml does not declare"
                    )));
                }
            }
            jobs.push(ReleaseJobSpec {
                id: id.to_owned(),
                name: row.name().unwrap_or(id).to_owned(),
                tasks: row.tasks().unwrap_or_default().to_vec(),
                needs: row.needs().unwrap_or_default().to_vec(),
                runner: row.runner().unwrap_or("github").to_owned(),
                modes: row.modes().unwrap_or_default().to_vec(),
                timeout_minutes: row
                    .timeout_minutes()
                    .and_then(|timeout| u32::try_from(timeout).ok())
                    .unwrap_or(primitives::check_profiles::DEFAULT_CHECK_PROFILE_TIMEOUT_MINUTES),
                environment: row.environment().unwrap_or_default().to_owned(),
                attest_subjects: row.attest_subjects().unwrap_or_default().to_vec(),
                permissions: row.permissions().clone(),
                env: row.env().clone(),
            });
        }
        spec.jobs = jobs;
    }
    if !release.images().is_empty() {
        spec.images = release
            .images()
            .iter()
            .map(|row| ReleaseImageSpec {
                name: row.name().unwrap_or_default().to_owned(),
                image: row.image().unwrap_or_default().to_owned(),
                dockerfile: row.dockerfile().unwrap_or_default().to_owned(),
                context: row.context().unwrap_or_default().to_owned(),
                platforms: row.platforms().to_vec(),
                needs: row.needs().unwrap_or_default().to_vec(),
                lfs: row.lfs(),
            })
            .collect();
    }
    // A declared apt contract is validated now, not at render time: malformed
    // values fail generation loudly instead of rendering a broken feed.
    if spec.kind == "apt" && primitives::release::release_contract_complete(&spec) {
        let validation = primitives::release::apt_release_spec(&spec);
        crate::apt::AptContract::resolve(&validation)
            .map_err(|error| GeneratorError::usage(error.to_string()))?;
    }
    config.release = Some(spec);
    Ok(())
}

/// Apply the `[[unit]]` rows a repository declares: a row whose `id` the scan
/// produced overrides only the fields it names, any other id adds a unit at
/// the end of the scan order.
///
/// # Errors
/// Returns a usage error for a platform, product, prerequisite, or env value
/// the row declares but the generator does not implement.
fn apply_unit_rows(
    config: &mut ProjectConfig,
    rows: &[config::UnitSection],
    root: &Path,
) -> Result<(), GeneratorError> {
    for row in rows {
        apply_unit_row(config, row, root)?;
    }
    Ok(())
}

#[allow(clippy::too_many_lines)]
fn apply_unit_row(
    config: &mut ProjectConfig,
    row: &config::UnitSection,
    root: &Path,
) -> Result<(), GeneratorError> {
    let Some(id) = row.id() else {
        return Ok(());
    };
    let existing = config.units.iter_mut().find(|unit| unit.id == id);
    let Some(unit) = existing else {
        let Some(kind) = row.kind().and_then(UnitKind::from_prefix) else {
            if !row.docker_contexts().is_empty() {
                return Err(GeneratorError::usage(format!(
                    "[[units.docker_contexts]] {id} requires `kind = \"docker\"` when adding a unit"
                )));
            }
            return Ok(());
        };
        if !row.docker_contexts().is_empty() && kind != UnitKind::Docker {
            return Err(GeneratorError::usage(format!(
                "[[units.docker_contexts]] {id} applies to a non-Docker unit"
            )));
        }
        let products = row.named_products(id)?;
        let prerequisites = row.declared_prerequisites(id)?;
        let docker_contexts = row.named_docker_contexts(id, root)?;
        let env = row.validated_env(id)?.unwrap_or_default();
        // A declared channel is a bare channel string: it carries no
        // components, targets, or profile of its own. A non-pin leg
        // provisions it explicitly with a minimal profile, so pin-only
        // components can never leak onto a channel that lacks them.
        let toolchain = row.validated_toolchain(id)?.map(|channel| RustToolchain {
            channel,
            components: Vec::new(),
            targets: Vec::new(),
            profile: None,
        });
        if toolchain.is_some() && kind != UnitKind::Rust {
            return Err(GeneratorError::usage(format!(
                "[[units]] {id} declares kind `{}` with a Rust toolchain; `toolchain` applies to Rust units only",
                kind.id_prefix(),
            )));
        }
        config.units.push(Unit {
            id: id.to_owned(),
            label: row.label().unwrap_or_default().to_owned(),
            kind,
            root: row.root().unwrap_or_default().to_owned(),
            pinned_lockfile: row.pinned_lockfile().unwrap_or(false),
            watch: row.watch().unwrap_or_default().to_vec(),
            pr_commands: {
                let mut commands = if row.workspace_check() {
                    vec!["cargo check --workspace --all-targets --locked".to_owned()]
                } else {
                    row.pr_commands().unwrap_or_default().to_vec()
                };
                for task in row.ci_tasks() {
                    commands.push(format!("mise run {task}"));
                }
                commands
            },
            full_commands: {
                let mut commands = if row.workspace_check() {
                    vec!["cargo check --workspace --all-targets --locked".to_owned()]
                } else {
                    row.full_commands().unwrap_or_default().to_vec()
                };
                for task in row.ci_tasks() {
                    commands.push(format!("mise run {task}"));
                }
                commands
            },
            // Declared units carry no scan tags; they verify through the
            // single legacy step.
            phases: Vec::new(),
            check_commands: Vec::new(),
            depends_on: row.depends_on().unwrap_or_default().to_vec(),
            cache: row.cache().map(|cache| CacheSpec {
                key_files: cache.key_files().unwrap_or_default().to_vec(),
                paths: cache.paths().unwrap_or_default().to_vec(),
                purpose: CachePurpose::Generic,
                mbx_output_cache_justification: None,
                mutable_mount_seed: cache.mutable_mount_seed(),
            }),
            tool_version: row.tool_version().map(str::to_owned),
            mise_tools: row.mise_tools().unwrap_or_default().to_vec(),
            toolchain,
            xcode: None,
            services: Vec::new(),
            trust: row
                .trust()
                .and_then(|trust| provider::TrustReq::parse(trust).ok())
                .unwrap_or_default(),
            platform: row
                .platform()
                .and_then(|platform| provider::Platform::parse(platform).ok())
                .unwrap_or(provider::Platform::LinuxX64),
            capabilities: provider::Capabilities::default(),
            workspace_check: row.workspace_check(),
            reads_closed: false,
            full_history: row.full_history(),
            products,
            prerequisites,
            docker_contexts,
            env,
            mbx: row.mbx(),
            prepared_tools: Vec::new(),
        });
        return Ok(());
    };
    if let Some(label) = row.label() {
        label.clone_into(&mut unit.label);
    }
    if let Some(kind) = row.kind().and_then(UnitKind::from_prefix) {
        unit.kind = kind;
    }
    // After the kind arm, so a row that flips the kind judges membership
    // against the final kind. The declared channel replaces the whole pin:
    // like an added row, it carries no components, targets, or profile.
    if let Some(channel) = row.validated_toolchain(id)? {
        if unit.kind != UnitKind::Rust {
            return Err(GeneratorError::usage(format!(
                "[[units]] {id} overrides a {} unit with a Rust toolchain; `toolchain` applies to Rust units only",
                unit.kind.label(),
            )));
        }
        unit.toolchain = Some(RustToolchain {
            channel,
            components: Vec::new(),
            targets: Vec::new(),
            profile: None,
        });
    }
    if let Some(root) = row.root() {
        root.clone_into(&mut unit.root);
    }
    if let Some(watch) = row.watch() {
        unit.watch = watch.to_vec();
    }
    if row.workspace_check() {
        unit.workspace_check = true;
        unit.pr_commands = vec!["cargo check --workspace --all-targets --locked".to_owned()];
        unit.full_commands.clone_from(&unit.pr_commands);
        unit.clear_phases();
    }
    // One-way latch, like `workspace_check` above: an override row opts a
    // scanned unit into full history, but nothing opts one back out, so a
    // silent shallow fallback can never make a diff-aware gate vacuous.
    if row.full_history() {
        unit.full_history = true;
    }
    for task in row.ci_tasks() {
        let command = format!("mise run {task}");
        if !unit.pr_commands.contains(&command) {
            unit.pr_commands.push(command.clone());
            unit.full_commands.push(command);
            // Custom tasks carry no phase tag; the unit keeps every command
            // in order and verifies through the single legacy step.
            unit.clear_phases();
        }
    }
    if let Some(dependencies) = row.depends_on() {
        unit.depends_on = dependencies.to_vec();
    }
    if let Some(cache) = row.cache() {
        unit.cache = Some(CacheSpec {
            key_files: cache.key_files().unwrap_or_default().to_vec(),
            paths: cache.paths().unwrap_or_default().to_vec(),
            purpose: CachePurpose::Generic,
            mbx_output_cache_justification: None,
            mutable_mount_seed: cache.mutable_mount_seed(),
        });
    }
    if let Some(pinned) = row.pinned_lockfile() {
        unit.pinned_lockfile = pinned;
    }
    if let Some(version) = row.tool_version() {
        unit.tool_version = Some(version.to_owned());
    }
    if let Some(tools) = row.mise_tools() {
        unit.mise_tools = tools.to_vec();
    }
    if let Some(trust) = row
        .trust()
        .and_then(|trust| provider::TrustReq::parse(trust).ok())
    {
        unit.trust = trust;
    }
    if let Some(platform) = row
        .platform()
        .and_then(|platform| provider::Platform::parse(platform).ok())
    {
        unit.platform = platform;
    }
    if !row.products().is_empty() {
        unit.products = row.named_products(id)?;
    }
    if !row.prerequisites().is_empty() {
        unit.prerequisites = row.declared_prerequisites(id)?;
    }
    if !row.docker_contexts().is_empty() {
        if unit.kind != UnitKind::Docker {
            return Err(GeneratorError::usage(format!(
                "[[units.docker_contexts]] {id} applies to a non-Docker unit"
            )));
        }
        unit.docker_contexts = row.named_docker_contexts(id, root)?;
    }
    if let Some(env) = row.validated_env(id)? {
        unit.env = env;
    }
    if let Some(mbx) = row.mbx() {
        unit.mbx = Some(mbx);
    }
    Ok(())
}

/// Image builds authenticate the Dockerfile's mise provisioning layer: the
/// `github_token` build secret carries the checks step's `GITHUB_TOKEN` into
/// the layer (the same secret id the release lane passes), so shared-runner
/// unauthenticated GitHub API quota exhaustion cannot fail `mise install`.
/// Every provider runs the same commands, so every provider's Docker checks
/// step exports the token.
const DOCKER_BUILD_GITHUB_TOKEN_SECRET: &str = "--secret id=github_token,env=GITHUB_TOKEN";

fn docker_pull_request_target(command: &str) -> String {
    if command.contains("--target ci") {
        command.to_owned()
    } else {
        command
            .replace(
                "docker buildx build ",
                "docker buildx build --load --target ci ",
            )
            .replace("docker build ", "docker buildx build --load --target ci ")
    }
}

fn docker_seed_pull_request_command(command: &str, unit_id: &str) -> String {
    let seed = format!(
        "--build-context {}='{}/seed'",
        primitives::MUTABLE_MOUNT_SEED_CONTEXT,
        primitives::MUTABLE_MOUNT_HOST_DIR
    );
    let cache_from = format!("--cache-from type=gha,scope={unit_id},mode=max");
    let cache_to = format!("--cache-to type=gha,scope={unit_id},mode=max");
    let mut cmd = docker_pull_request_target(command);
    if !cmd.contains(&seed) {
        cmd.push(' ');
        cmd.push_str(&seed);
    }
    if !cmd.contains("--cache-from type=gha") {
        cmd.push(' ');
        cmd.push_str(&cache_from);
    }
    if !cmd.contains("--cache-to type=gha") {
        cmd.push(' ');
        cmd.push_str(&cache_to);
    }
    if !cmd.contains(DOCKER_BUILD_GITHUB_TOKEN_SECRET) {
        cmd.push(' ');
        cmd.push_str(DOCKER_BUILD_GITHUB_TOKEN_SECRET);
    }
    cmd
}

/// The hosted full build runs the same image build as the pull-request lane,
/// minus the `ci` target: buildx with the unit's GHA layer-cache scope, so a
/// main run reuses (and refreshes) the generation pull requests read instead
/// of cold-rebuilding the image on every merge.
fn docker_seed_full_command(command: &str, unit_id: &str) -> String {
    let seed = format!(
        "--build-context {}='{}/seed'",
        primitives::MUTABLE_MOUNT_SEED_CONTEXT,
        primitives::MUTABLE_MOUNT_HOST_DIR
    );
    let cache_from = format!("--cache-from type=gha,scope={unit_id},mode=max");
    let cache_to = format!("--cache-to type=gha,scope={unit_id},mode=max");
    let mut cmd = command.replace("docker build ", "docker buildx build --load ");
    if !cmd.contains(&seed) {
        cmd.push(' ');
        cmd.push_str(&seed);
    }
    if !cmd.contains("--cache-from type=gha") {
        cmd.push(' ');
        cmd.push_str(&cache_from);
    }
    if !cmd.contains("--cache-to type=gha") {
        cmd.push(' ');
        cmd.push_str(&cache_to);
    }
    if !cmd.contains(DOCKER_BUILD_GITHUB_TOKEN_SECRET) {
        cmd.push(' ');
        cmd.push_str(DOCKER_BUILD_GITHUB_TOKEN_SECRET);
    }
    cmd
}

fn append_docker_contexts(command: &str, contexts: &[DockerContext]) -> Result<String, String> {
    if contexts.is_empty() {
        return Ok(command.to_owned());
    }

    let mut rendered = String::with_capacity(command.len());
    let mut segment_start = 0;
    let mut found = false;
    loop {
        let segment_end = shell_segment_end(command, segment_start);
        let segment = &command[segment_start..segment_end];
        if let Some((offset, prefix_len)) = find_docker_build(segment) {
            let build = &segment[offset..];
            let mut flags = String::new();
            for context in contexts {
                if has_named_docker_context(build, &context.name) {
                    return Err(format!(
                        "Docker command already declares context `{}`; declare it only through `[[units.docker_contexts]]`",
                        context.name
                    ));
                }
                let _ = write!(
                    flags,
                    "--build-context {}={} ",
                    context.name,
                    shell_quote(&context.path)
                );
            }
            let insertion_end = offset + prefix_len;
            rendered.push_str(&segment[..insertion_end]);
            rendered.push_str(&flags);
            rendered.push_str(&segment[insertion_end..]);
            found = true;
        } else {
            rendered.push_str(segment);
        }
        if segment_end == command.len() {
            break;
        }
        rendered.push_str(&command[segment_end..=segment_end]);
        segment_start = segment_end + 1;
    }
    if found {
        Ok(rendered)
    } else {
        Ok(command.to_owned())
    }
}

fn shell_segment_end(command: &str, start: usize) -> usize {
    let bytes = command.as_bytes();
    let mut quote = None;
    let mut escaped = false;
    let mut index = start;
    while index < bytes.len() {
        let byte = bytes[index];
        if let Some(active_quote) = quote {
            if active_quote == b'"' && escaped {
                escaped = false;
            } else if active_quote == b'"' && byte == b'\\' {
                escaped = true;
            } else if byte == active_quote {
                quote = None;
            }
        } else {
            match byte {
                b'\'' | b'"' => quote = Some(byte),
                b'\\' => {
                    index = index.saturating_add(1);
                }
                b';' | b'&' | b'|' | b'\n' => return index,
                _ => {}
            }
        }
        index += 1;
    }
    bytes.len()
}

fn find_docker_build(command: &str) -> Option<(usize, usize)> {
    let bytes = command.as_bytes();
    let mut quote = None;
    let mut escaped = false;
    let mut index = 0;
    while index < bytes.len() {
        let byte = bytes[index];
        if let Some(active_quote) = quote {
            if active_quote == b'"' && escaped {
                escaped = false;
            } else if active_quote == b'"' && byte == b'\\' {
                escaped = true;
            } else if byte == active_quote {
                quote = None;
            }
            index += 1;
            continue;
        }
        if byte == b'\'' || byte == b'"' {
            quote = Some(byte);
            index += 1;
            continue;
        }
        if byte == b'\\' {
            index = index.saturating_add(2);
            continue;
        }
        let token_boundary = index == 0
            || !matches!(
                bytes[index - 1],
                b'a'..=b'z' | b'A'..=b'Z' | b'0'..=b'9' | b'_' | b'-'
            );
        if token_boundary {
            if command[index..].starts_with("docker buildx build ") {
                return Some((index, "docker buildx build ".len()));
            }
            if command[index..].starts_with("docker build ") {
                return Some((index, "docker build ".len()));
            }
        }
        index += 1;
    }
    None
}

fn has_named_docker_context(command: &str, name: &str) -> bool {
    let mut search_start = 0;
    while let Some(relative) = command[search_start..].find("--build-context") {
        let start = search_start + relative + "--build-context".len();
        let rest = command[start..].trim_start();
        if let Some(rest) = rest.strip_prefix(name)
            && rest.trim_start().starts_with('=')
        {
            return true;
        }
        search_start = start;
    }
    false
}

fn append_docker_contexts_to_commands(
    commands: &mut [String],
    contexts: &[DockerContext],
) -> Result<bool, String> {
    let mut rendered = false;
    for command in commands {
        let updated = append_docker_contexts(command, contexts)?;
        rendered |= updated != *command;
        *command = updated;
    }
    Ok(rendered)
}

/// Fill unit commands from typed capabilities. Generation config cannot supply
/// shell command arrays; this is the only writer of the runtime command lists.
fn materialize_capability_commands(
    config: &mut ProjectConfig,
    root: &Path,
) -> Result<(), GeneratorError> {
    let mise_tasks = parse_mise_task_names(root)?;
    for unit in &mut config.units {
        if unit.kind == UnitKind::Docker
            && unit
                .cache
                .as_ref()
                .is_some_and(|cache| cache.mutable_mount_seed)
        {
            // Every provider runs the same commands: the seed lifecycle is one
            // contract materialized into the unit's only command lists. The
            // rewrite carries no phase tags; Docker units carry none, and
            // this keeps that invariant if one ever does.
            unit.clear_phases();
            for command in &mut unit.pr_commands {
                *command = docker_seed_pull_request_command(command, &unit.id);
            }
            let dockerfile = if unit.root == "." {
                "Dockerfile".to_owned()
            } else {
                format!("{}/Dockerfile", unit.root)
            };
            let context = if unit.root == "." {
                ".".to_owned()
            } else {
                unit.root.clone()
            };
            let file = shell_quote(&dockerfile);
            let ctx = shell_quote(&context);
            let scope = &unit.id;
            let seed = format!(
                "--build-context {}='{}/seed'",
                primitives::MUTABLE_MOUNT_SEED_CONTEXT,
                primitives::MUTABLE_MOUNT_HOST_DIR
            );
            let already_seeded = unit
                .full_commands
                .iter()
                .any(|command| command.contains(&seed));
            if !already_seeded {
                if unit.full_commands.is_empty() {
                    unit.full_commands = vec![format!(
                        "docker buildx build --load --file {file} --tag local-ci:dockerfile {ctx}"
                    )];
                }
                for command in &mut unit.full_commands {
                    if command.contains("docker") {
                        *command = docker_seed_full_command(command, scope);
                    }
                }
                let mut export = format!(
                    "docker buildx build --target {} --output type=local,dest={}/export {seed} --file {file} {ctx}",
                    primitives::MUTABLE_MOUNT_EXPORT_TARGET,
                    primitives::MUTABLE_MOUNT_HOST_DIR
                );
                export.push(' ');
                export.push_str(DOCKER_BUILD_GITHUB_TOKEN_SECRET);
                unit.full_commands.push(export);
            }
            let _ = (scope, file, ctx);
        }
        if !unit.docker_contexts.is_empty() {
            let contexts = unit.docker_contexts.clone();
            let mut rendered = append_docker_contexts_to_commands(&mut unit.pr_commands, &contexts)
                .map_err(|error| GeneratorError::usage(format!("unit `{}` {error}", unit.id)))?;
            rendered |= append_docker_contexts_to_commands(&mut unit.full_commands, &contexts)
                .map_err(|error| GeneratorError::usage(format!("unit `{}` {error}", unit.id)))?;
            if !rendered {
                return Err(GeneratorError::usage(format!(
                    "unit `{}` declares Docker contexts but has no Docker build command to receive them",
                    unit.id
                )));
            }
        }
        for command in unit.pr_commands.iter().chain(unit.full_commands.iter()) {
            if let Some(task) = command.strip_prefix("mise run ")
                && !mise_tasks.iter().any(|name| name == task)
            {
                return Err(GeneratorError::usage(format!(
                    "unit `{}` names mise task `{task}`, which mise.toml does not declare",
                    unit.id
                )));
            }
        }
    }
    Ok(())
}

fn parse_mise_task_names(root: &Path) -> Result<Vec<String>, GeneratorError> {
    let path = root.join("mise.toml");
    if !path.is_file() {
        return Ok(Vec::new());
    }
    let contents = fs::read_to_string(&path)
        .map_err(|error| GeneratorError::io("read mise.toml", &path, &error))?;
    let document = toml::from_str::<toml::Value>(&contents).map_err(|error| {
        GeneratorError::usage(format!("parse mise.toml {}: {error}", path.display()))
    })?;
    let Some(tasks) = document.get("tasks") else {
        return Ok(Vec::new());
    };
    let tasks = tasks.as_table().ok_or_else(|| {
        GeneratorError::usage(format!(
            "parse mise.toml {}: `tasks` must be a table",
            path.display()
        ))
    })?;
    let mut names = tasks.keys().cloned().collect::<Vec<_>>();
    names.sort();
    names.dedup();
    Ok(names)
}

/// Read the repository-local files the generated output owns verbatim. The
/// repository owns the bytes at `source`; the generator owns the write to
/// `file`, which stays inside `.github/`.
///
/// # Errors
/// Returns errors for a declared source that is missing, unreadable, or not
/// UTF-8.
/// Carry validated `[[reviewers]]` rows onto the config in declaration
/// order. Validation runs before apply, so a row missing its pattern is
/// unreachable; it is skipped rather than rendered half-formed.
fn apply_reviewer_rows(config: &mut ProjectConfig, rows: &[config::ReviewerSection]) {
    for row in rows {
        let Some(pattern) = row.pattern() else {
            continue;
        };
        config.reviewers.push(ReviewerRule {
            pattern: pattern.to_owned(),
            owners: row.owners().to_vec(),
        });
    }
}

fn read_static_files(
    config: &mut ProjectConfig,
    rows: &[config::StaticFileSection],
    root: &Path,
) -> Result<(), GeneratorError> {
    for row in rows {
        let (Some(file), Some(source)) = (row.file(), row.source()) else {
            continue;
        };
        let path = root.join(source);
        let content = fs::read_to_string(&path).map_err(|error| {
            GeneratorError::io("read declared static file source", &path, &error)
        })?;
        config.static_files.push(StaticFile {
            path: file.to_owned(),
            source: source.to_owned(),
            content,
        });
    }
    Ok(())
}

/// The owner blocks the surface's `package-update.yml` really declares, in
/// template order, so the declared channel grants are validated against the
/// file the repository renders and not against a generator-side copy.
fn package_update_owner_blocks(config: &ProjectConfig) -> Vec<String> {
    config
        .workflow_templates
        .get(PACKAGE_UPDATE_WORKFLOW)
        .map(|template| {
            estate::apt_package_update_owner_blocks(template)
                .into_iter()
                .map(str::to_owned)
                .collect()
        })
        .unwrap_or_default()
}

/// Every provider in the universe needs its `runs-on` routing, and the two
/// local providers need disjoint dedicated selectors. Selectors are a
/// declared input, never a generator default.
fn validate_provider_selectors(config: &ProjectConfig) -> Result<(), GeneratorError> {
    if config.units.is_empty() && config.docs.is_none() {
        return Ok(());
    }
    provider::require_selectors_for(&config.selectors, &config.providers)?;
    provider::validate_selector_disjointness(&config.selectors)?;
    Ok(())
}

/// An in-scope unit that needs a capability its provider lacks is a hard
/// error naming unit + provider + capability. Generation evaluates this on
/// trusted events (the widest eligibility); the runtime planner re-checks
/// per event.
fn validate_unit_capabilities(config: &ProjectConfig) -> Result<(), GeneratorError> {
    for unit in &config.units {
        for provider in &config.providers {
            if provider::eligibility(unit.platform, unit.trust, *provider, true).is_ok() {
                provider::check_capabilities(&unit.id, unit.capabilities, *provider)?;
            }
        }
    }
    Ok(())
}

/// A phased unit's tags are positional over its command vectors: every
/// vector the runtime may select must carry exactly one tag per command.
/// Anything else is a generator bug or a hand-built config the scan would
/// never produce; refuse it instead of shipping misaligned `--phase` steps.
/// Runs at the end of the scan and again after unit-contract primitives
/// (which mutate commands post-scan) so no `--phase` step can misalign.
pub(crate) fn validate_unit_phases(config: &ProjectConfig) -> Result<(), GeneratorError> {
    for unit in &config.units {
        if !unit.has_phases() {
            if !unit.check_commands.is_empty() {
                return Err(GeneratorError::usage(format!(
                    "unit `{}` carries prerequisite check commands without validation phases",
                    unit.id
                )));
            }
            continue;
        }
        if unit.pr_commands.len() != unit.phases.len()
            || unit.full_commands.len() != unit.phases.len()
        {
            return Err(GeneratorError::usage(format!(
                "unit `{}` carries {} validation phases for {} PR and {} full commands; phases must tag every command",
                unit.id,
                unit.phases.len(),
                unit.pr_commands.len(),
                unit.full_commands.len()
            )));
        }
        if unit.check_commands.is_empty() {
            return Err(GeneratorError::usage(format!(
                "unit `{}` carries validation phases without prerequisite check commands",
                unit.id
            )));
        }
    }
    Ok(())
}

#[cfg_attr(not(test), allow(dead_code))]
fn strip_workflow_generator_header(content: &str) -> &str {
    if let Some(body) = content.strip_prefix(GENERATED_HEADER) {
        return body;
    }
    let Some((first, body)) = content.split_once('\n') else {
        return content;
    };
    if first.starts_with("# Generated by ") {
        body
    } else {
        content
    }
}

pub(crate) fn parent_path(path: &str) -> String {
    path.rsplit_once('/')
        .map_or_else(|| ".".to_owned(), |(parent, _)| parent.to_owned())
}

fn identifier_suffix(value: &str) -> String {
    value
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() {
                character.to_ascii_lowercase()
            } else {
                '-'
            }
        })
        .collect::<String>()
        .trim_matches('-')
        .to_owned()
}

pub(crate) fn shell_quote(value: &str) -> String {
    format!("'{}'", value.replace('\'', "'\\''"))
}

fn shell_change_dir(root: &str) -> String {
    if root == "." {
        String::new()
    } else {
        format!("cd -- {} && ", shell_quote(root))
    }
}

pub(crate) fn unit_job_id(provider: provider::ProviderId, unit_id: &str) -> String {
    provider::unit_job_id(provider, unit_id)
}

pub(crate) fn unit_group(kind: UnitKind) -> &'static str {
    match kind {
        UnitKind::Rust => "Rust",
        UnitKind::Bun => "Bun / Packages",
        UnitKind::Node => "Node / Packages",
        UnitKind::Docker => "Docker / Images",
        UnitKind::Docs => "Documentation",
        UnitKind::OpenTofu => "OpenTofu",
        UnitKind::Homebrew => "Homebrew",
        UnitKind::Swift => "Swift / Packages",
        UnitKind::Gradle => "Gradle / Projects",
    }
}

/// The first `unit_group` segment: `Bun / Packages` → `Bun`. Comparison job
/// names use this so they never nest extra slashes.
pub(crate) fn provider_kind_label(kind: UnitKind) -> &'static str {
    unit_group(kind)
        .split(" / ")
        .next()
        .unwrap_or_else(|| unit_group(kind))
}

/// `{provider} / {Kind} / {unit_id}` — provider is always the first token,
/// verbatim (grep-able invariant).
pub(crate) fn comparison_job_name(provider: provider::ProviderId, unit: &Unit) -> String {
    format!(
        "{} / {} / {}",
        provider.as_str(),
        provider_kind_label(unit.kind),
        unit.id
    )
}

/// Quoted `Control / {label}` display name for aggregate and side-effect jobs.
pub(crate) fn control_job_name(label: &str) -> String {
    yaml_scalar(&format!("Control / {label}"))
}

pub(crate) fn unit_display_label(unit: &Unit) -> &str {
    unit.label
        .strip_prefix("Rust crate (")
        .and_then(|value| value.strip_suffix(')'))
        .unwrap_or(&unit.label)
}

pub(crate) fn sidebar_group_name(unit: &Unit) -> String {
    format!(
        "{} · {}",
        unit.kind.label().replace(" / ", " · "),
        unit_display_label(unit)
    )
}

/// Caller display name: `{Kind} · {provider-id} — {unit_id}`. The provider
/// ID appears verbatim (grep-able invariant). GitHub renders reusable checks
/// as `<caller> / <callee>`; the callee provider name is derived separately
/// from `inputs.provider`.
pub(crate) fn unit_job_display_name(unit: &Unit, provider: provider::ProviderId) -> String {
    provider::unit_job_display_name(&sidebar_group_name(unit), provider, &unit.id)
}

/// Aggregate caller that invokes a kind reusable with `provider: control`.
pub(crate) fn prepare_cargo_caller_job_id() -> &'static str {
    "prepare-cargo"
}

pub(crate) fn nested_unit_workflow_file(unit: &Unit) -> String {
    kind_unit_workflow_file(unit.kind)
}

/// One reusable workflow per unit kind. GitHub allows 50 unique reusable
/// workflow files per caller; a monorepo with one file per unit exceeds that.
pub(crate) fn kind_unit_workflow_file(kind: UnitKind) -> String {
    format!("ci-unit-{}.yml", kind.id_prefix())
}

fn workflow_file_names(config: &ProjectConfig) -> Vec<String> {
    let mut files = config.workflow_files.clone();
    if !config.adopted_workflow_surface {
        files.extend(config.units.iter().map(nested_unit_workflow_file));
    }
    files.sort();
    files.dedup();
    files
}

fn render_static_template(template: &str, revision: &str) -> String {
    render_static_template_with_header(template, GENERATED_HEADER, revision)
}

fn render_static_template_with_header(template: &str, header: &str, revision: &str) -> String {
    let template = template.replace("__VELNOR_WORKFLOW_SOURCE_REV__", revision);
    let template = refresh_static_mr_boxington_commands(&template);
    format!(
        "{header}{}",
        refresh_velnor_action_pins(&refresh_velnor_source_pins(&template, revision))
    )
}

/// The header a rendered static template carries: the fleet caller keeps the
/// render-consumer header its pinned fleet release hash-pins, and every
/// other file carries the generator header.
fn static_template_header(workflow_file: &str) -> &'static str {
    if workflow_file == FLEET_CALLER_WORKFLOW {
        FLEET_CALLER_HEADER
    } else {
        GENERATED_HEADER
    }
}

/// The static-template placeholder for the pinned-toolchain steps a lane
/// provisions without saving the cache, and the placeholder for the steps a
/// trusted default-branch push also saves under. Both are filled from the one
/// shared renderer every other rendering path uses, so a static workflow body
/// can never hand-write its own toolchain contract.
const PINNED_TOOLCHAIN_STEPS_PLACEHOLDER: &str = "__VELNOR_PINNED_TOOLCHAIN_STEPS__";
const TRUSTED_PINNED_TOOLCHAIN_STEPS_PLACEHOLDER: &str =
    "__VELNOR_TRUSTED_PINNED_TOOLCHAIN_STEPS__";

/// The snapshot-identity placeholders a static template renders into Mr.
/// Boxington keys: the compatibility token the generator digests from the
/// repository's facts, and the freshness expression the generator derives from
/// the scanned source closure. A template that names neither keeps the
/// frozen-snapshot defect this generator refuses.
const SNAPSHOT_COMPATIBILITY_PLACEHOLDER: &str = "__VELNOR_SNAPSHOT_COMPATIBILITY__";
const SNAPSHOT_STATE_PLACEHOLDER: &str = "__VELNOR_SNAPSHOT_STATE__";
const AUTOMATIC_PROVIDERS_DEFAULT_PLACEHOLDER: &str = "__VELNOR_AUTOMATIC_PROVIDERS_DEFAULT__";

/// The repository's own Rust pin. The scan stamps every Rust unit with the
/// parsed pin, but a declared per-unit channel (an MSRV leg) is not the
/// pin — so this reads the file's own recorded fact first and falls back to
/// the first Rust unit's pin only for hand-built configs that never parsed a
/// pin file. `None` for a config that carries no Rust units or no recorded
/// pin, and every consumer of the fact fails closed on the latter.
pub(crate) fn config_rust_toolchain(config: &ProjectConfig) -> Option<RustToolchain> {
    if let Some(pin) = &config.rust_pin {
        return Some(pin.clone());
    }
    config
        .units
        .iter()
        .find_map(|unit| {
            (unit.kind == UnitKind::Rust)
                .then_some(unit.toolchain.as_ref())
                .flatten()
        })
        .cloned()
}

/// The `__VELNOR_…__` markers a rendered template still carries. A marker a
/// body misspells survives rendering untouched, and `--check` stays green
/// because both sides regenerate from the same typo — so the renderer itself
/// must refuse it. The marker ends at the closing `__`, or at the end of the
/// line when the closing delimiter is missing.
fn unresolved_velnor_markers(rendered: &str) -> Vec<String> {
    let mut markers = Vec::new();
    let mut rest = rendered;
    while let Some(start) = rest.find("__VELNOR_") {
        let tail = &rest[start..];
        let end = tail
            .split_once('\n')
            .map_or(tail.len(), |(line, _)| line.len())
            .min(tail[2..].find("__").map_or(tail.len(), |offset| offset + 4));
        let marker = tail[..end].to_owned();
        if !markers.contains(&marker) {
            markers.push(marker);
        }
        rest = &rest[start + end..];
    }
    markers
}

/// Fill the pinned-toolchain placeholders a static template declares with the
/// steps the shared renderer emits for the repository's own pin. Templates
/// without a placeholder render unchanged, so only a body that declares the
/// toolchain contract can demand a pin — and it fails closed when the
/// repository records none.
///
/// # Errors
/// Returns a usage error when the repository records no Rust pin despite a
/// template demanding one, or when any `__VELNOR_` marker survives rendering.
pub(crate) fn render_pinned_toolchain_fill(
    config: &ProjectConfig,
    template: &str,
) -> Result<String, GeneratorError> {
    let rendered = if template.contains(PINNED_TOOLCHAIN_STEPS_PLACEHOLDER)
        || template.contains(TRUSTED_PINNED_TOOLCHAIN_STEPS_PLACEHOLDER)
    {
        let Some(toolchain) = config_rust_toolchain(config) else {
            return Err(GeneratorError::usage(
                "a static workflow template declares the pinned Rust toolchain contract, but the \
                 repository pins no Rust toolchain; add rust-toolchain.toml with a [toolchain] \
                 channel (plus any components and targets) so every workflow provisions exactly \
                 that toolchain",
            ));
        };
        let mut pinned = String::new();
        primitives::render_pinned_toolchain_steps(
            &mut pinned,
            ActionPin::CacheRestore.reference(),
            ActionPin::CacheSave.reference(),
            &toolchain,
            None,
        );
        // Preview builds run only from trusted pushes to the default branch, so
        // that — and nothing broader — is what may save the toolchain cache.
        let mut trusted = String::new();
        primitives::render_pinned_toolchain_steps(
            &mut trusted,
            ActionPin::CacheRestore.reference(),
            ActionPin::CacheSave.reference(),
            &toolchain,
            Some(&format!(
                "{} && steps.rustup-toolchain.outputs.cache-hit != 'true'",
                primitives::default_branch_push_cache_save_expression(&config.default_branch)
            )),
        );
        template
            .replace(
                TRUSTED_PINNED_TOOLCHAIN_STEPS_PLACEHOLDER,
                trusted.trim_end_matches('\n'),
            )
            .replace(
                PINNED_TOOLCHAIN_STEPS_PLACEHOLDER,
                pinned.trim_end_matches('\n'),
            )
    } else {
        template.to_owned()
    };
    let markers = unresolved_velnor_markers(&rendered);
    if markers.is_empty() {
        return Ok(rendered);
    }
    Err(GeneratorError::usage(format!(
        "the rendered workflow still contains unresolved template markers ({}); a misspelled \
         placeholder would ship its literal text into a committed workflow and stay invisible \
         to regeneration checks, so generation refuses it",
        markers.join(", ")
    )))
}

/// Every Rust unit renders the pinned-toolchain contract on its hosted lane; a
/// unit without a recorded pin would silently render steps that provision
/// whatever rustup resolves. The scan refuses an unpinned Rust repository, so
/// generation is the last point at which a hand-built config can be caught.
/// Every generated pin (policy runtime `--rev`, `setup-velnor-workflow`
/// `rev:`, runtime artifact names) is rendered from
/// `ProjectConfig::workflow_revision`; a tree rendered from anything but a
/// full commit SHA could never be regenerated by the policy validator.
fn validate_workflow_revision(config: &ProjectConfig) -> Result<(), GeneratorError> {
    if is_full_revision(&config.workflow_revision) {
        return Ok(());
    }
    Err(GeneratorError::usage(format!(
        "the generator revision {:?} is not a full commit SHA; declare `[generator] revision` in \
         the generation config or build velnor-workflow from a git checkout",
        config.workflow_revision
    )))
}

fn validate_rust_units_are_pinned(config: &ProjectConfig) -> Result<(), GeneratorError> {
    if config
        .units
        .iter()
        .any(|unit| unit.kind == UnitKind::Rust && unit.toolchain.is_none())
    {
        return Err(GeneratorError::usage(
            "a Rust unit records no toolchain pin; add rust-toolchain.toml with a [toolchain] \
             channel (plus any components and targets) so every workflow provisions exactly \
             that toolchain",
        ));
    }
    Ok(())
}

/// A Rust kind spanning more than one channel provisions each leg through
/// rustup — but local providers skip toolchain provisioning entirely (the
/// image owns the toolchain), so a matrix leg there would silently verify
/// under the image's toolchain instead of its declared channel. Refuse the
/// combination at generation time instead of shipping a leg that proves
/// nothing.
fn validate_toolchain_matrix_providers(config: &ProjectConfig) -> Result<(), GeneratorError> {
    let mut channels = BTreeSet::new();
    for unit in &config.units {
        if unit.kind == UnitKind::Rust
            && let Some(toolchain) = &unit.toolchain
        {
            channels.insert(toolchain.channel.clone());
        }
    }
    if channels.len() < 2 {
        return Ok(());
    }
    if config.providers.iter().any(|provider| provider.is_local()) {
        let channels = channels.into_iter().collect::<Vec<_>>().join(", ");
        return Err(GeneratorError::usage(format!(
            "Rust units span more than one toolchain channel ({channels}), but a local provider \
             cannot provision per-leg toolchains; remove the local provider or collapse the \
             units onto one channel"
        )));
    }
    Ok(())
}

/// The release matrices build for the targets the contract names, so the
/// repository's pin must declare every one of them: the file-driven install
/// provisions the pin's targets, and a target the pin omits would surface as
/// a broken build lane instead of a refused contract.
fn validate_release_targets_are_pinned(config: &ProjectConfig) -> Result<(), GeneratorError> {
    let Some(release) = &config.release else {
        return Ok(());
    };
    if release.targets.is_empty() {
        return Ok(());
    }
    let Some(toolchain) = config_rust_toolchain(config) else {
        return Err(GeneratorError::usage(format!(
            "the release contract builds for {} but the repository pins no Rust toolchain; add \
             rust-toolchain.toml with a [toolchain] channel declaring those targets",
            release.targets.join(", ")
        )));
    };
    let missing = release
        .targets
        .iter()
        .filter(|target| !toolchain.targets.iter().any(|pinned| pinned == *target))
        .map(String::as_str)
        .collect::<Vec<_>>()
        .join(", ");
    if !missing.is_empty() {
        return Err(GeneratorError::usage(format!(
            "the release contract builds for {} but the pinned Rust toolchain does not declare \
             {}; add the missing targets to rust-toolchain.toml so every build lane provisions \
             them",
            release.targets.join(", "),
            missing
        )));
    }
    Ok(())
}

/// # Errors
/// Returns a usage error when the template declares the pinned-toolchain
/// contract and the repository records no Rust pin.
pub(crate) fn render_static_template_for_config(
    config: &ProjectConfig,
    workflow_file: &str,
    template: &str,
) -> Result<String, GeneratorError> {
    // A surface that selects its runners declares one token per provider
    // instead of spelling labels; surfaces without them render unchanged.
    let mut template = template.to_owned();
    for provider in &config.providers {
        let token = format!("__VELNOR_RUNS_ON_{}__", provider.as_str().to_uppercase());
        if let Some(selector) = config.selectors.get(provider) {
            template = template.replace(&token, &selector_runs_on_yaml(selector));
        }
    }
    if let Some(selector) = config.selectors.get(&provider::ProviderId::Velnor) {
        template = template.replace(
            crate::s2::estate::LEGACY_VELNOR_RUNNER_SELECTOR,
            &selector_runs_on_expression(selector),
        );
    }
    let template = if workflow_file == PACKAGE_UPDATER_WORKFLOW {
        estate::render_apt_package_updater_template(
            &template,
            &config.default_branch,
            &config.selectors,
            &config.providers,
        )
    } else if workflow_file == PACKAGE_UPDATE_WORKFLOW {
        estate::render_apt_package_update_template(config, &template)
    } else {
        template
    };
    let automatic_default = config
        .automatic_providers
        .iter()
        .map(provider::ProviderId::as_str)
        .collect::<Vec<_>>()
        .join(",");
    let template = template.replace(
        AUTOMATIC_PROVIDERS_DEFAULT_PLACEHOLDER,
        &format!("'{automatic_default}'"),
    );
    // Snapshot identity is filled after the static-template pass, so a
    // canonical step the pass inserts carries the markers too; the pinned
    // toolchain fill runs last and refuses any marker that survives.
    let rendered = render_static_template_with_header(
        &template,
        static_template_header(workflow_file),
        &config.workflow_revision,
    );
    let (compatibility, state) = primitives::config_snapshot_identity(config);
    let rendered = rendered
        .replace(SNAPSHOT_COMPATIBILITY_PLACEHOLDER, &compatibility)
        .replace(SNAPSHOT_STATE_PLACEHOLDER, &state);
    let rendered = render_pinned_toolchain_fill(config, &rendered)?;
    validate_static_template_cache_transports(&rendered)?;
    validate_guest_seed_lifecycle(&rendered, &config.default_branch)?;
    Ok(rendered)
}

/// Reject a static workflow body that points Mr. Boxington's local backend at
/// a job no persistent store can serve. `backend: local` reuses whatever store
/// the runner's filesystem already holds; on a disposable hosted runner it
/// holds nothing, so every job starts cold while the declaration claims
/// persistence. A local backend is only accepted for a job whose `runs-on`
/// selects the repository's persistent (self-hosted or runner-group) pool, and
/// a GitHub object-cache backend is only accepted with the cache key that
/// makes its snapshots reusable — a keyless snapshot import would restore
/// nothing and save under a per-run key no later run can find.
///
/// # Errors
/// Returns a usage error naming the offending job when a hosted job declares
/// the local backend, or when a GitHub-backend step carries no cache mode,
/// key, or restore keys.
fn validate_static_template_cache_transports(rendered: &str) -> Result<(), GeneratorError> {
    for (job, block) in static_workflow_job_blocks(rendered) {
        let runs_on = block
            .lines()
            .find(|line| line.trim_start().starts_with("runs-on:"))
            .map(|line| {
                line.trim_start()
                    .strip_prefix("runs-on:")
                    .unwrap_or_default()
            })
            .unwrap_or_default()
            .trim()
            .to_owned();
        // The runner-group selector is the persistent pool by construction:
        // the generation config declares it for the self-hosted lane. A bare
        // `self-hosted` label says the same thing without a group.
        let persistent =
            runs_on.contains("self-hosted") || runs_on.contains("fromJSON('{\"group\"");
        let uses_mr_boxington = block.contains("jdx/mr-boxington-action@");
        if uses_mr_boxington && block.contains("backend: local") && !persistent {
            return Err(GeneratorError::usage(format!(
                "static workflow job `{job}` points Mr. Boxington's `backend: local` at \
                 `runs-on: {runs_on}`; a disposable hosted runner keeps no local store, so the \
                 job would rebuild cold under a declaration of persistence. Restore compiler \
                 state through the GitHub object cache (`backend: github` with \
                 `github-cache-mode: objects` and a compatibility-identity `cache-key`), or run \
                 the job on the persistent runner pool the local store lives on"
            )));
        }
        if uses_mr_boxington
            && block.contains("backend: github")
            && ["github-cache-mode:", "cache-key:", "restore-keys:"]
                .into_iter()
                .any(|required| !block.contains(required))
        {
            return Err(GeneratorError::usage(format!(
                "static workflow job `{job}` points Mr. Boxington's `backend: github` at the \
                 object cache without `github-cache-mode`, `cache-key`, and `restore-keys`; \
                 without a compatibility-identity key the job imports nothing and saves under a \
                 per-run key no later run can restore"
            )));
        }
        if uses_mr_boxington && block.contains("backend: github") {
            let cache_key = block
                .lines()
                .find_map(|line| {
                    line.trim_start()
                        .strip_prefix("cache-key:")
                        .map(str::trim)
                        .map(str::to_owned)
                })
                .unwrap_or_default();
            if !primitives::snapshot::is_snapshot_key(&cache_key) {
                return Err(GeneratorError::usage(format!(
                    "static workflow job `{job}` restores Mr. Boxington objects under \
                     `cache-key: {cache_key}`, which names compatibility only: GitHub cache \
                     entries are immutable, so an exact hit on that key refuses every later save \
                     and the snapshot freezes at its first write. Render a snapshot key — \
                     compatibility digest, runtime segments, dependency inputs, and a freshness \
                     segment — with the `__VELNOR_SNAPSHOT_COMPATIBILITY__` and \
                     `__VELNOR_SNAPSHOT_STATE__` placeholders"
                )));
            }
            let restore_keys = block
                .lines()
                .skip_while(|line| !line.trim_start().starts_with("restore-keys:"))
                .skip(1)
                .take_while(|line| {
                    line.trim_start().starts_with('-') || line.starts_with("            ")
                })
                .filter_map(|line| {
                    line.trim_start()
                        .strip_prefix("- ")
                        .map(str::to_owned)
                        .or(Some(line.trim_start().to_owned()))
                })
                .collect::<Vec<_>>();
            for restore_key in restore_keys {
                let complete = restore_key == cache_key;
                let carries_state = restore_key.matches("hashFiles(").count() > 1;
                if complete || carries_state {
                    return Err(GeneratorError::usage(format!(
                        "static workflow job `{job}` lists `restore-keys: {restore_key}` as a \
                         complete generation: the cache service returns the most recently created \
                         entry matching a restore key, so an exact old generation on the list \
                         shadows newer compatible fallbacks and re-freezes the snapshot. List \
                         prefixes only"
                    )));
                }
            }
        }
    }
    Ok(())
}

/// The name of the step that exports the hosted Mr. Boxington store budget.
const MR_BOXINGTON_STORE_BUDGET_STEP: &str = "Bound the Mr. Boxington store";

/// Every job that runs Mr. Boxington against the GitHub backend exports the
/// hosted store budget ahead of the action, and no local-backend job does.
///
/// The hosted store is job-scoped and mbx sizes it at its 5 GiB floor, so a
/// sweep between two Cargo commands evicts action results the post-step
/// export still needs; the budget is therefore a property of "runs mbx on a
/// hosted runner", checked over every rendered workflow instead of being
/// remembered per job. A local-backend job runs on a Velnor host whose
/// persistent store is budgeted by `config/fleet/velnor-host.env`; exporting
/// the hosted ceiling there would shrink the shared store.
///
/// # Errors
/// Returns a usage error naming the workflow and job that breaks the rule.
pub(crate) fn validate_hosted_mr_boxington_store_budget(
    files: &BTreeMap<PathBuf, String>,
) -> Result<(), GeneratorError> {
    let export = format!("{MR_BOXINGTON_STORE_BUDGET_ENV}={MR_BOXINGTON_HOSTED_STORE_BUDGET}");
    for (path, rendered) in rendered_workflow_files(files) {
        for (job, block) in static_workflow_job_blocks(rendered) {
            if !block.contains("jdx/mr-boxington-action@") {
                continue;
            }
            let steps = named_workflow_steps(&block);
            let budget = steps.iter().position(|(name, body)| {
                name == MR_BOXINGTON_STORE_BUDGET_STEP && body.contains(&export)
            });
            let action = steps
                .iter()
                .position(|(_, body)| body.contains("jdx/mr-boxington-action@"));
            if block.contains("backend: github") {
                match (budget, action) {
                    (Some(budget), Some(action)) if budget < action => {}
                    _ => {
                        return Err(GeneratorError::usage(format!(
                            "{path}: job `{job}` runs Mr. Boxington against the GitHub backend \
                             without exporting `{export}` to `$GITHUB_ENV` ahead of the action; \
                             mbx sizes a hosted store at its 5 GiB floor, so a mid-job sweep \
                             evicts the action results the post-step export needs. Render the \
                             `{MR_BOXINGTON_STORE_BUDGET_STEP}` step before `Set up Mr. Boxington`"
                        )));
                    }
                }
            } else if budget.is_some() {
                return Err(GeneratorError::usage(format!(
                    "{path}: job `{job}` exports the hosted Mr. Boxington store budget `{export}` \
                     around a local-backend store; the Velnor host budgets its persistent store \
                     in config/fleet/velnor-host.env, and the hosted ceiling would shrink it"
                )));
            }
        }
    }
    Ok(())
}

/// Every job that runs `velnor-workflow policy` checks out full history.
///
/// The validator's `pin-reachable` rule walks from the audited head to the
/// declared pin; a shallow checkout holds neither the pin nor the ancestry,
/// so the rule fails on any job whose only checkout is `fetch-depth: 1`.
/// Full history is a property of running the validator, checked here over
/// every rendered workflow rather than remembered by each job's checkout. A
/// shallow supplemental checkout may coexist — today only the owner policy
/// job's sparse base-tree setup-action checkout — but the audited checkout
/// itself must be full.
///
/// # Errors
/// Returns a usage error naming the workflow and job whose checkout is
/// shallow.
pub(crate) fn validate_policy_jobs_check_out_full_history(
    files: &BTreeMap<PathBuf, String>,
) -> Result<(), GeneratorError> {
    for (path, rendered) in rendered_workflow_files(files) {
        for (job, block) in static_workflow_job_blocks(rendered) {
            let steps = named_workflow_steps(&block);
            if !steps
                .iter()
                .any(|(_, body)| step_runs_workflow_policy(body))
            {
                continue;
            }
            let full_history = steps.iter().any(|(_, body)| {
                body.contains("actions/checkout@")
                    && body.lines().any(|line| line.trim() == "fetch-depth: 0")
            });
            if !full_history {
                return Err(GeneratorError::usage(format!(
                    "{path}: job `{job}` runs `velnor-workflow policy` without a full-history \
                     checkout; the pin-reachable rule walks from the audited head to the declared \
                     pin, so the job's actions/checkout step must set `fetch-depth: 0`"
                )));
            }
        }
    }
    Ok(())
}

/// Every `cargo install` of `velnor-workflow` owns its destination.
///
/// `cargo install` refuses to overwrite a binary another install left in the
/// same root (`binary velnor-workflow already exists in destination`), and a
/// hosted job legitimately provisions two revisions — the pinned validator
/// and the event runtime — so every install must carry `--root`, the root
/// must not be the shared `~/.cargo/bin`, an install whose revision is a
/// shell variable must root itself under that variable (the same step text
/// runs once per revision), and two installs in one job may share a root only
/// when they install the identical revision. Composite actions run inside the
/// caller's job, so their steps are checked as one block. Checked here over
/// every rendered workflow and action rather than remembered per step.
///
/// # Errors
/// Returns a usage error naming the file, job, and install that breaks the
/// rule.
pub(crate) fn validate_workflow_runtime_install_roots(
    files: &BTreeMap<PathBuf, String>,
) -> Result<(), GeneratorError> {
    for (path, rendered) in rendered_workflow_and_action_files(files) {
        let blocks = if path.starts_with(".github/actions/") {
            vec![("composite action".to_owned(), rendered.clone())]
        } else {
            static_workflow_job_blocks(rendered)
        };
        for (job, block) in blocks {
            if let Some(line) = block.lines().find(|line| {
                !line.trim_start().starts_with('#') && names_shared_cargo_bin_runtime(line)
            }) {
                return Err(GeneratorError::usage(format!(
                    "{path}: {job} places the velnor-workflow runtime in the shared cargo bin \
                     directory: `{}`; the runtime is addressed by revision under its own root \
                     and never copied into `~/.cargo/bin`",
                    line.trim()
                )));
            }
            let mut roots: BTreeMap<String, String> = BTreeMap::new();
            for install in workflow_runtime_installs(&block) {
                let Some(root) = install.root.as_deref() else {
                    return Err(GeneratorError::usage(format!(
                        "{path}: {job} installs velnor-workflow without `--root`; cargo refuses \
                         a destination another install already filled, and a job may provision \
                         two revisions, so every install owns a revision-specific root: `{}`",
                        install.command
                    )));
                };
                if root_is_shared_cargo_bin(root) {
                    return Err(GeneratorError::usage(format!(
                        "{path}: {job} installs velnor-workflow into the shared cargo bin \
                         directory `{root}`; the runtime never lives in `~/.cargo/bin` — it is \
                         restored from the cargo-bin toolchain cache and shared by every install \
                         in the job: `{}`",
                        install.command
                    )));
                }
                if let Some(revision) = install.revision.as_deref()
                    && revision.contains('$')
                    && !root.contains(revision)
                {
                    return Err(GeneratorError::usage(format!(
                        "{path}: {job} installs velnor-workflow at the variable revision \
                         `{revision}` into `{root}`, a root that does not embed it; the same \
                         step runs once per revision, so the root must be addressed by the \
                         revision: `{}`",
                        install.command
                    )));
                }
                let revision = install.revision.clone().unwrap_or_default();
                if let Some(previous) = roots.insert(root.to_owned(), revision.clone())
                    && previous != revision
                {
                    return Err(GeneratorError::usage(format!(
                        "{path}: {job} installs velnor-workflow at revisions {previous} and \
                         {revision} into one root `{root}`; cargo refuses the second install, so \
                         distinct revisions need distinct roots"
                    )));
                }
            }
        }
    }
    Ok(())
}

/// The step name of the aggregate required check's verdict script.
const REQUIRED_CHECK_STEP: &str = "Validate generated stack results";
/// The step name of the in-workflow required check's verdict script.
const REQUIRED_UNIT_CHECK_STEP: &str = "Validate generated unit results";
/// Prefix of the required check's admission environment variables.
const PROVIDER_ADMITTED_ENV_PREFIX: &str = "PROVIDER_ADMITTED_";

/// The required check, every job it validates, and every callee lane job
/// agree on one admission predicate per lane class.
///
/// The check expects `success` from a selected job whose class the predicate
/// admits and `skipped` otherwise, so any surface that evaluates a different
/// predicate — a callee job gated on an event the caller admits, a caller
/// gated on one the check does not read, a callee lane the check knows no
/// class for — makes a green run impossible by construction: a
/// lane-restricted `workflow_dispatch` once skipped every callee job while
/// the check demanded `success` from their callers. All three surfaces render
/// the predicate from `WorkflowIr::lane_admission_expression`; this checks the
/// rendered tree for drift between them instead of trusting the renderers.
///
/// # Errors
/// Returns a usage error naming the workflow, job, and predicate that drift.
#[allow(
    clippy::too_many_lines,
    reason = "d2a shape: one complete drift validator"
)]
pub(crate) fn validate_provider_admission_single_source(
    files: &BTreeMap<PathBuf, String>,
) -> Result<(), GeneratorError> {
    for (path, rendered) in rendered_workflow_files(files) {
        let blocks = static_workflow_job_blocks(rendered);
        let Some((gate_job, gate)) = blocks.iter().find(|(_, block)| {
            named_workflow_steps(block)
                .iter()
                .any(|(name, _)| name == REQUIRED_CHECK_STEP || name == REQUIRED_UNIT_CHECK_STEP)
        }) else {
            continue;
        };
        let admissions = required_check_admissions(gate);
        for (job, admitted) in required_check_verdicts(gate) {
            let Some(expression) = admissions.get(&admitted) else {
                return Err(GeneratorError::usage(format!(
                    "{path}: `{gate_job}` reads `${admitted}` for job `{job}` but declares no \
                     `{admitted}` in its env; every admission class the verdicts use is \
                     evaluated once in the check's environment"
                )));
            };
            let Some((_, block)) = blocks.iter().find(|(id, _)| id == &job) else {
                return Err(GeneratorError::usage(format!(
                    "{path}: `{gate_job}` validates job `{job}`, which the workflow does not \
                     render"
                )));
            };
            let clause = format!("({expression})");
            let gate_line = job_level_if(block).unwrap_or_default();
            if !gate_line.contains(&clause) {
                return Err(GeneratorError::usage(format!(
                    "{path}: job `{job}` is gated on `{gate_line}` while `{gate_job}` expects it \
                     to run exactly when `{admitted}` = `{expression}` holds; the job's `if:` \
                     must carry the same admission predicate the check evaluates"
                )));
            }
            let Some(callee) = block
                .lines()
                .find_map(|line| line.trim().strip_prefix("uses: ./.github/workflows/"))
            else {
                continue;
            };
            let Some(provider) = block
                .lines()
                .find_map(|line| line.trim().strip_prefix("provider: "))
            else {
                return Err(GeneratorError::usage(format!(
                    "{path}: caller `{job}` invokes `{callee}` without a `provider:` input, so no \
                     callee job can be matched to its admission"
                )));
            };
            let callee_path = PathBuf::from(".github/workflows").join(callee);
            let Some(callee_rendered) = files.get(&callee_path) else {
                return Err(GeneratorError::usage(format!(
                    "{path}: caller `{job}` invokes `{callee}`, which the tree does not render"
                )));
            };
            let provider_selector = format!("inputs.provider == '{provider}'");
            // The `control` provider warms every local provider's stores: its
            // callee jobs carry their own provider's admission, so any
            // evaluated admission is accepted for them.
            let expected_provider = admission_provider_of(provider);
            let provider_admissions = match expected_provider {
                None => admissions
                    .values()
                    .map(|expression| format!("({expression})"))
                    .collect::<Vec<_>>(),
                Some(expected) => admissions
                    .iter()
                    .filter(|(name, _)| admission_env_provider(name) == Some(expected))
                    .map(|(_, expression)| format!("({expression})"))
                    .collect::<Vec<_>>(),
            };
            let mut carries_caller_predicate = false;
            let mut callee_jobs = 0_usize;
            let mut carried: Vec<String> = Vec::new();
            for (callee_job, callee_block) in static_workflow_job_blocks(callee_rendered) {
                let callee_if = job_level_if(&callee_block).unwrap_or_default();
                if !callee_if.contains(&provider_selector) {
                    continue;
                }
                callee_jobs += 1;
                if callee_if.contains(&clause) {
                    carries_caller_predicate = true;
                } else if !provider_admissions
                    .iter()
                    .any(|candidate| callee_if.contains(candidate))
                {
                    return Err(GeneratorError::usage(format!(
                        "{callee}: job `{callee_job}` (provider `{provider}`) is gated on `{callee_if}`, \
                         a predicate `{path}` `{gate_job}` evaluates for no admission class of \
                         that provider; the callee job's `if:` must carry the provider admission the \
                         check reads"
                    )));
                }
                if expected_provider.is_none() {
                    for candidate in &provider_admissions {
                        if callee_if.contains(candidate) && !carried.contains(candidate) {
                            carried.push(candidate.clone());
                        }
                    }
                }
            }
            if callee_jobs == 0 {
                return Err(GeneratorError::usage(format!(
                    "{callee}: no job is gated on `{provider_selector}`, yet `{path}` caller `{job}` \
                     invokes it with `provider: {provider}`"
                )));
            }
            if !carries_caller_predicate && expected_provider.is_none() {
                // Distributed enforcement: the `control` caller evaluates the
                // union of its local providers' admissions, so the union is
                // carried exactly when every evaluated local admission is
                // carried by some control-gated callee job. A missing member
                // would silently skip warming on dispatches selecting only it.
                let required = admissions
                    .iter()
                    .filter(|(name, _)| {
                        admission_env_provider(name).is_some_and(provider::ProviderId::is_local)
                    })
                    .map(|(_, expression)| format!("({expression})"))
                    .collect::<Vec<_>>();
                if !required.is_empty() && required.iter().all(|member| carried.contains(member)) {
                    carries_caller_predicate = true;
                }
            }
            if !carries_caller_predicate {
                return Err(GeneratorError::usage(format!(
                    "{callee}: no `{provider}` provider job carries the admission `{expression}` that \
                     `{path}` caller `{job}` and `{gate_job}` evaluate for it"
                )));
            }
        }
    }
    Ok(())
}

/// The `PROVIDER_ADMITTED_*` environment of a required-check block, as
/// `(name, expression)` pairs with the `${{ }}` wrapper removed.
fn required_check_admissions(gate: &str) -> BTreeMap<String, String> {
    gate.lines()
        .filter_map(|line| {
            let (name, value) = line.trim().split_once(": ")?;
            if !name.starts_with(PROVIDER_ADMITTED_ENV_PREFIX) {
                return None;
            }
            let expression = value
                .trim()
                .strip_prefix("${{ ")
                .and_then(|value| value.strip_suffix(" }}"))?;
            Some((name.to_owned(), expression.to_owned()))
        })
        .collect()
}

/// The `(job id, admission env name)` pairs of a required-check block: each
/// selected-branch `result_for_job` lookup followed by the admission test
/// its verdict reads.
fn required_check_verdicts(gate: &str) -> Vec<(String, String)> {
    let lines: Vec<&str> = gate.lines().map(str::trim).collect();
    let mut verdicts = Vec::new();
    for (index, line) in lines.iter().enumerate() {
        let Some(job) = line
            .strip_prefix("result=\"$(result_for_job ")
            .and_then(|rest| rest.strip_suffix(")\""))
        else {
            continue;
        };
        let Some(admitted) = lines
            .get(index + 1)
            .and_then(|next| next.strip_prefix("if [[ \"$"))
            .and_then(|rest| rest.strip_suffix("\" == true ]]; then"))
        else {
            continue;
        };
        if admitted.starts_with(PROVIDER_ADMITTED_ENV_PREFIX) {
            verdicts.push((job.to_owned(), admitted.to_owned()));
        }
    }
    verdicts
}

/// The job-level `if:` expression of a rendered job block, `${{ }}` removed.
fn job_level_if(block: &str) -> Option<String> {
    block
        .lines()
        .find_map(|line| line.strip_prefix("    if: "))
        .map(|value| {
            value
                .trim()
                .strip_prefix("${{ ")
                .and_then(|value| value.strip_suffix(" }}"))
                .unwrap_or(value.trim())
                .to_owned()
        })
}

/// The provider an admission environment variable evaluates.
fn admission_env_provider(name: &str) -> Option<provider::ProviderId> {
    use primitives::ProviderAdmission;
    use provider::ProviderId;
    [
        ProviderAdmission::Provider(ProviderId::GithubHosted),
        ProviderAdmission::Provider(ProviderId::GithubSelfHosted),
        ProviderAdmission::Provider(ProviderId::Velnor),
        ProviderAdmission::ProviderTrusted(ProviderId::GithubHosted),
        ProviderAdmission::ProviderTrusted(ProviderId::GithubSelfHosted),
        ProviderAdmission::ProviderTrusted(ProviderId::Velnor),
    ]
    .into_iter()
    .find(|admission| admission.env_name() == name)
    .and_then(ProviderAdmission::provider)
}

/// The provider whose admission a caller's `provider:` input evaluates. The
/// `control` provider warms every local provider's stores and is admitted
/// with each of them, so it matches no single provider.
fn admission_provider_of(provider: &str) -> Option<provider::ProviderId> {
    provider::ProviderId::parse(provider).ok()
}

/// One rendered `cargo install … velnor-workflow` invocation.
struct WorkflowRuntimeInstall {
    /// The logical command line, continuation lines joined.
    command: String,
    /// The `--root` argument, when present.
    root: Option<String>,
    /// The `--rev` argument, when present.
    revision: Option<String>,
}

/// Every `cargo install` of the `velnor-workflow` crate in a rendered block,
/// with `\`-continued lines joined so multi-line invocations read as one and
/// `--root` expanded through the block's own `name="value"` shell assignments
/// and `NAME: value` step env entries, so a root spelled `"$root"` is judged
/// by the path it names.
fn workflow_runtime_installs(block: &str) -> Vec<WorkflowRuntimeInstall> {
    let mut installs = Vec::new();
    let mut variables: BTreeMap<String, String> = BTreeMap::new();
    let mut logical = String::new();
    for line in block.lines() {
        let trimmed = line.trim();
        if let Some(head) = trimmed.strip_suffix('\\') {
            logical.push_str(head);
            logical.push(' ');
            continue;
        }
        logical.push_str(trimmed);
        let command = std::mem::take(&mut logical);
        if let Some((name, value)) = shell_or_env_assignment(&command) {
            variables.insert(name, expand_block_variables(&value, &variables));
        }
        if command.starts_with('#') || !command.contains("cargo install") {
            continue;
        }
        let tokens: Vec<&str> = command.split_whitespace().collect();
        let installs_runtime = tokens.iter().enumerate().any(|(index, token)| {
            *token == "velnor-workflow" && tokens.get(index.wrapping_sub(1)) != Some(&"--bin")
        });
        if !installs_runtime {
            continue;
        }
        let argument = |flag: &str| {
            tokens
                .iter()
                .position(|token| *token == flag)
                .and_then(|index| tokens.get(index + 1))
                .map(|value| value.trim_matches(|c| c == '"' || c == '\'').to_owned())
        };
        installs.push(WorkflowRuntimeInstall {
            root: argument("--root").map(|root| expand_block_variables(&root, &variables)),
            revision: argument("--rev")
                .map(|revision| expand_block_variables(&revision, &variables)),
            command,
        });
    }
    installs
}

/// A `name="value"` shell assignment or an `NAME: value` step env entry, with
/// the value's surrounding quotes removed.
fn shell_or_env_assignment(line: &str) -> Option<(String, String)> {
    let is_identifier = |name: &str| {
        !name.is_empty() && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
    };
    let unquote = |value: &str| {
        value
            .trim()
            .trim_matches(|c| c == '"' || c == '\'')
            .to_owned()
    };
    if let Some((name, value)) = line.split_once('=')
        && is_identifier(name)
        && !value.starts_with('=')
    {
        return Some((name.to_owned(), unquote(value)));
    }
    if let Some((name, value)) = line.split_once(": ")
        && is_identifier(name)
        && name
            .chars()
            .all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_')
    {
        return Some((name.to_owned(), unquote(value)));
    }
    None
}

/// Replace `$name` and `${name}` with the block's known assignments.
fn expand_block_variables(value: &str, variables: &BTreeMap<String, String>) -> String {
    let mut expanded = value.to_owned();
    for (name, replacement) in variables.iter().rev() {
        expanded = expanded
            .replace(&format!("${{{name}}}"), replacement)
            .replace(&format!("${name}"), replacement);
    }
    expanded
}

/// Whether a script line names the runtime binary `velnor-workflow` itself
/// (not `velnor-workflow-policy`, the Velnor lane's distinctly named
/// host-persistent copy) inside the shared cargo bin directory.
fn names_shared_cargo_bin_runtime(line: &str) -> bool {
    [
        ".cargo/bin/velnor-workflow",
        ".cargo}/bin/velnor-workflow",
        "CARGO_HOME/bin/velnor-workflow",
        "CARGO_HOME}/bin/velnor-workflow",
    ]
    .iter()
    .any(|needle| {
        line.match_indices(needle).any(|(index, _)| {
            !line[index + needle.len()..]
                .chars()
                .next()
                .is_some_and(|next| next == '-' || next.is_ascii_alphanumeric())
        })
    })
}

/// Whether an install root is the cargo home's shared `bin` directory in any
/// of the spellings a rendered script may use.
fn root_is_shared_cargo_bin(root: &str) -> bool {
    let root = root.trim_end_matches('/');
    let last = root.rsplit('/').next().unwrap_or(root);
    let parent = root.rsplit_once('/').map_or("", |(parent, _)| {
        parent.rsplit('/').next().unwrap_or(parent)
    });
    let is_cargo_home = |segment: &str| {
        matches!(
            segment,
            ".cargo" | ".cargo}" | "$CARGO_HOME" | "${CARGO_HOME}" | "CARGO_HOME" | "CARGO_HOME}"
        ) || segment.ends_with("$HOME/.cargo}")
    };
    is_cargo_home(last) || (last == "bin" && is_cargo_home(parent))
}

/// The rendered workflows plus the composite actions they call, as
/// `(display path, content)` pairs.
fn rendered_workflow_and_action_files(
    files: &BTreeMap<PathBuf, String>,
) -> impl Iterator<Item = (String, &String)> {
    files
        .iter()
        .filter(|(path, _)| {
            (path.starts_with(".github/workflows")
                && path.extension().is_some_and(|extension| extension == "yml"))
                || (path.starts_with(".github/actions")
                    && path.file_name().is_some_and(|name| name == "action.yml"))
        })
        .map(|(path, content)| (path.display().to_string(), content))
}

/// Whether a step body invokes the policy validator (`velnor-workflow
/// policy`) in a `run:` script, as opposed to naming it in a comment.
fn step_runs_workflow_policy(body: &str) -> bool {
    body.lines().any(|line| {
        let trimmed = line.trim_start();
        !trimmed.starts_with('#') && trimmed.contains("velnor-workflow policy")
    })
}

/// The rendered `.github/workflows/*.yml` files of a generated tree, as
/// `(display path, content)` pairs.
fn rendered_workflow_files(
    files: &BTreeMap<PathBuf, String>,
) -> impl Iterator<Item = (String, &String)> {
    files
        .iter()
        .filter(|(path, _)| {
            path.starts_with(".github/workflows")
                && path.extension().is_some_and(|extension| extension == "yml")
        })
        .map(|(path, content)| (path.display().to_string(), content))
}

/// The job blocks of a rendered static workflow, as `(job key, body)` pairs.
/// Structural, not a YAML parse: the generator only needs which step lines
/// belong to which job, and a body too malformed to expose that is caught by
/// the `__VELNOR_` marker and pin checks around it.
fn static_workflow_job_blocks(rendered: &str) -> Vec<(String, String)> {
    let mut blocks = Vec::new();
    let mut current: Option<(String, Vec<&str>)> = None;
    for line in rendered.lines() {
        if line.trim().is_empty() {
            // Blank lines inside `run: |` scripts are body content. Ending
            // the block here would blind every consumer to the jobs' tails —
            // a stray blank once silently disabled drift detection.
            if let Some((_, body)) = current.as_mut() {
                body.push(line);
            }
            continue;
        }
        let indent = line.len() - line.trim_start().len();
        if indent == 0 {
            // A top-level key ends any job block; only `jobs:` bodies hold
            // jobs, and job keys sit at exactly one indent level below it.
            if let Some(job) = current.take() {
                blocks.push(job);
            }
            continue;
        }
        if indent == 2 {
            let trimmed = line.trim_end();
            if trimmed.ends_with(':') && !trimmed.starts_with('-') {
                if let Some(job) = current.take() {
                    blocks.push(job);
                }
                current = Some((trimmed.trim().trim_end_matches(':').to_owned(), Vec::new()));
                continue;
            }
        }
        if let Some((_, body)) = current.as_mut() {
            body.push(line);
        }
    }
    if let Some(job) = current.take() {
        blocks.push(job);
    }
    blocks
        .into_iter()
        .map(|(job, body)| (job, body.join("\n")))
        .collect()
}

/// Guest-payload jobs restore a recipe-identity seed, verify it against the
/// rebuilt guest agent, and save only on a trusted exact miss. A restore
/// without a matching save would rebuild kernel and rootfs on every run.
pub(crate) fn validate_guest_seed_lifecycle(
    rendered: &str,
    default_branch: &str,
) -> Result<(), GeneratorError> {
    for (job, block) in static_workflow_job_blocks(rendered) {
        let steps = named_workflow_steps(&block);
        if !steps.iter().any(|(name, _)| name == "Restore guest seed") {
            continue;
        }
        validate_guest_seed_job(&job, &steps, default_branch)?;
    }
    Ok(())
}

fn named_workflow_steps(block: &str) -> Vec<(String, String)> {
    let mut steps = Vec::new();
    let mut current: Option<(String, Vec<&str>)> = None;
    for line in block.lines() {
        let trimmed = line.trim_start();
        if let Some(name) = trimmed.strip_prefix("- name:") {
            if let Some((name, body)) = current.take() {
                steps.push((name, body.join("\n")));
            }
            current = Some((name.trim().to_owned(), vec![line]));
            continue;
        }
        if let Some((_, body)) = current.as_mut() {
            body.push(line);
        }
    }
    if let Some((name, body)) = current {
        steps.push((name, body.join("\n")));
    }
    steps
}

fn validate_guest_seed_job(
    job: &str,
    steps: &[(String, String)],
    default_branch: &str,
) -> Result<(), GeneratorError> {
    let required = [
        "Restore guest seed",
        "Build guest agent",
        "Reuse verified guest seed",
        "Download pinned kernel tarball",
        "Build guest vmlinux",
        "Collect verified guest seed",
        "Save guest seed",
    ];
    let mut indexes = Vec::with_capacity(required.len());
    for name in required {
        let Some(index) = steps.iter().position(|(step, _)| step.contains(name)) else {
            return Err(GeneratorError::usage(format!(
                "static workflow job `{job}` restores a guest seed but is missing `{name}`; \
                 a restore without collect+save would rebuild kernel and rootfs on every run"
            )));
        };
        indexes.push(index);
    }
    if indexes.windows(2).any(|pair| pair[0] >= pair[1]) {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` restores a guest seed out of order; required sequence is \
             restore, build agent, reuse, download kernel, build image, collect, save"
        )));
    }

    let restore = &steps[indexes[0]].1;
    let reuse = &steps[indexes[2]].1;
    let kernel = &steps[indexes[3]].1;
    let image = &steps[indexes[4]].1;
    let collect = &steps[indexes[5]].1;
    let save = &steps[indexes[6]].1;
    let restore_key = validate_guest_seed_restore_key(job, restore)?;
    validate_guest_seed_reuse_gates(job, reuse, kernel, image)?;
    validate_guest_seed_trusted_save(job, collect, save, &restore_key, default_branch)
}

fn validate_guest_seed_restore_key(job: &str, restore: &str) -> Result<String, GeneratorError> {
    let restore_key = step_scalar(restore, "key").ok_or_else(|| {
        GeneratorError::usage(format!(
            "static workflow job `{job}` restores a guest seed without a recipe-identity key"
        ))
    })?;
    if restore_key.contains("github.sha") || !restore_key.contains("hashFiles(") {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` keys the guest seed with `{restore_key}`; the identity \
             is the guest recipe/source closure, never github.sha"
        )));
    }
    if !step_restore_keys(restore).is_empty() {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` restores a guest seed with restore-keys; guest-seed \
             restores must be exact-only so a new recipe cannot reuse an older same-arch seed"
        )));
    }
    Ok(restore_key)
}

fn validate_guest_seed_reuse_gates(
    job: &str,
    reuse: &str,
    kernel: &str,
    image: &str,
) -> Result<(), GeneratorError> {
    if !reuse.contains("id: guest-seed-reuse") {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` reuses a guest seed without `id: guest-seed-reuse`"
        )));
    }
    let reuse_gate = "steps.guest-seed-reuse.outputs.restored != 'true'";
    if !kernel.contains(reuse_gate) {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` downloads the kernel tarball without gating on guest-seed \
             reuse failure"
        )));
    }
    if !image.contains(reuse_gate) {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` builds guest vmlinux without gating on guest-seed reuse \
             failure"
        )));
    }
    if !reuse.contains("sha256sum --check") || reuse.matches("restored=false").count() < 2 {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` must fail open to a rebuild when a restored guest seed \
             fails checksum or agent comparison"
        )));
    }
    if !kernel.contains("microvm/pins.json") || !kernel.contains("curl --fail") {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` must download the pinned kernel tarball from \
             microvm/pins.json with curl --fail"
        )));
    }
    if !image.contains("--bin") || !(image.contains("cargo run") || image.contains("mbx run")) {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` must build the guest image with cargo/mbx run --bin"
        )));
    }
    Ok(())
}

fn validate_guest_seed_trusted_save(
    job: &str,
    collect: &str,
    save: &str,
    restore_key: &str,
    default_branch: &str,
) -> Result<(), GeneratorError> {
    let trusted_miss = format!(
        "if: github.event_name == 'push' && github.ref == 'refs/heads/{default_branch}' && \
         steps.guest-seed.outputs.cache-hit != 'true'"
    );
    // Collect and save share the trusted exact-miss gate. The branch is the
    // configured default branch, never an arbitrary refs/heads/* value.
    for (name, body) in [
        ("Collect verified guest seed", collect),
        ("Save guest seed", save),
    ] {
        if !body.lines().any(|line| line.trim() == trusted_miss) {
            return Err(GeneratorError::usage(format!(
                "static workflow job `{job}` step `{name}` must save only on a trusted \
                 default-branch push and an exact restore miss (`{trusted_miss}`)"
            )));
        }
    }
    if !collect.contains("cp dist/microvm/vmlinux") {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` must copy dist/microvm/vmlinux into the guest seed"
        )));
    }
    if !save.contains("actions/cache/save") {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` collects a guest seed but never calls actions/cache/save"
        )));
    }
    let save_key = step_scalar(save, "key").ok_or_else(|| {
        GeneratorError::usage(format!(
            "static workflow job `{job}` saves a guest seed without the restore key"
        ))
    })?;
    if save_key != restore_key {
        return Err(GeneratorError::usage(format!(
            "static workflow job `{job}` saves the guest seed under `{save_key}` but restored \
             `{restore_key}`"
        )));
    }
    Ok(())
}

fn step_scalar(step: &str, key: &str) -> Option<String> {
    let prefix = format!("{key}:");
    for line in step.lines() {
        let trimmed = line.trim_start();
        if let Some(rest) = trimmed.strip_prefix(&prefix) {
            let rest = rest.trim();
            if rest != "|" && !rest.is_empty() {
                return Some(rest.to_owned());
            }
        }
    }
    None
}

fn step_restore_keys(step: &str) -> Vec<String> {
    let mut keys = Vec::new();
    let mut in_restore = false;
    let mut restore_indent = 0;
    for line in step.lines() {
        let indent = line.len() - line.trim_start().len();
        let trimmed = line.trim_start();
        if trimmed.starts_with("restore-keys:") {
            in_restore = true;
            restore_indent = indent;
            let rest = trimmed.trim_start_matches("restore-keys:").trim();
            if rest != "|" && !rest.is_empty() {
                keys.push(rest.trim_start_matches("- ").to_owned());
            }
            continue;
        }
        if in_restore {
            if indent <= restore_indent || trimmed.starts_with("- name:") {
                break;
            }
            if trimmed.is_empty() {
                continue;
            }
            keys.push(trimmed.trim_start_matches("- ").to_owned());
        }
    }
    keys
}

/// The repository marker the regeneration gate matches on.
pub(crate) fn regen_repository_marker() -> &'static str {
    "tailrocks/velnor"
}

fn refresh_velnor_source_pins(template: &str, revision: &str) -> String {
    let mut rendered = String::with_capacity(template.len());
    let mut previous_line_was_velnor_repository = false;

    for segment in template.split_inclusive('\n') {
        let line = segment.strip_suffix('\n').unwrap_or(segment);
        let replacement = if previous_line_was_velnor_repository {
            replace_full_sha_after_key(line, "ref:", revision)
        } else {
            replace_full_sha_after_key(line, "VELNOR_SOURCE_SHA:", revision)
        };
        if let Some(replacement) = replacement {
            rendered.push_str(&replacement);
            if segment.ends_with('\n') {
                rendered.push('\n');
            }
        } else {
            rendered.push_str(segment);
        }
        previous_line_was_velnor_repository =
            line.trim() == format!("repository: {}", crate::s2::regen_repository_marker());
    }

    rendered
}

fn replace_full_sha_after_key(line: &str, key: &str, revision: &str) -> Option<String> {
    let trimmed = line.trim_start();
    let indentation = line.len() - trimmed.len();
    let rest = trimmed.strip_prefix(key)?;
    if !rest.chars().next().is_some_and(char::is_whitespace) {
        return None;
    }
    let value_offset = rest.find(|character: char| !character.is_whitespace())?;
    let value = rest[value_offset..].split_whitespace().next()?;
    if value.len() != 40 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return None;
    }

    let value_start = indentation + key.len() + value_offset;
    let value_end = value_start + value.len();
    let mut replacement = String::with_capacity(line.len());
    replacement.push_str(&line[..value_start]);
    replacement.push_str(revision);
    replacement.push_str(&line[value_end..]);
    Some(replacement)
}

fn refresh_velnor_action_pins(template: &str) -> String {
    let action = "jdx/mr-boxington-action";
    let marker = format!("{action}@");
    let replacement = ActionPin::MrBoxington.reference();
    let mut rendered = String::with_capacity(template.len());
    let mut mr_boxington_step_indent = None;

    for segment in template.split_inclusive('\n') {
        let line = segment.strip_suffix('\n').unwrap_or(segment);
        let trimmed = line.trim_start();
        let indentation = line.len() - trimmed.len();
        if mr_boxington_step_indent
            .is_some_and(|step_indent| !trimmed.is_empty() && indentation <= step_indent)
        {
            mr_boxington_step_indent = None;
        }

        if mr_boxington_step_indent.is_some_and(|step_indent| {
            indentation > step_indent && trimmed.starts_with("max-size:")
        }) {
            if segment.ends_with('\n') {
                rendered.push('\n');
            }
            continue;
        }

        if let Some(marker_start) = line.find(&marker) {
            let value_start = marker_start + marker.len();
            let value = line[value_start..]
                .split_whitespace()
                .next()
                .unwrap_or_default();
            if value.len() == 40 && value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
                rendered.push_str(&line[..marker_start]);
                rendered.push_str(replacement);
                if segment.ends_with('\n') {
                    rendered.push('\n');
                }
                mr_boxington_step_indent = Some(indentation);
                continue;
            }
        }

        rendered.push_str(segment);
    }

    rendered
}

/// One rendering of the policy job: the base-owned `ci-policy.yml`
/// entrypoint (`Policy`, `pull_request_target` + `workflow_dispatch`) and the
/// same job inside the trusted aggregates (`ci-main.yml`, `nightly.yml`),
/// where a push to the default branch proves the validator the branch now
/// carries passes on its own tree.
pub(crate) struct PolicyJobSpec<'a> {
    pub(crate) name: &'a str,
    /// The validator pin: the `velnor-workflow` commit whose `policy`
    /// subcommand audits the tree. The generated tree declares the same
    /// value as `[generator] revision`; the validator's `entrypoint-pin`
    /// rule requires the two to agree.
    pub(crate) revision: &'a str,
    pub(crate) runner: &'a str,
    /// The repository the generated tree belongs to: the setup action runs
    /// from the owner's own checkout, or from the published pin for
    /// consumers.
    pub(crate) repository: &'a str,
    /// Mr. Boxington backend: `github` on hosted runners, `local` on Velnor
    /// runners. The Velnor lane resolves no live ruleset; like every lane,
    /// it never passes `--pin-build`, so an unprovisioned pin fails closed.
    pub(crate) cache_backend: &'a str,
    pub(crate) trusted_gate: Option<&'a str>,
    /// The branch whose rulesets are the required status-check contexts.
    pub(crate) default_branch: &'a str,
    /// Declared `[policy]` contexts passed to `--ruleset-contexts` when the
    /// rulesets API answers 403 on private repositories.
    pub(crate) declared_ruleset_contexts: &'a str,
}

/// Shell fragment reading the audited tree's declared generator pin into
/// `$pin` (fails closed when the tree declares none): `[generator]
/// revision` first, the entrypoint literal second. Callers treat the pin as
/// a locator hint; `velnor-workflow policy` parses the tree authoritatively
/// and fails closed on any disagreement.
fn audited_pin_script() -> &'static str {
    r#"          pin="$(sed -n -E 's/^[[:space:]]*revision[[:space:]]*=[[:space:]]*"([0-9a-f]{40})".*/\1/p' .github-gen/velnor-workflow.toml | head -n 1)"
          test "$pin" != '' || pin="$(sed -n -E 's/^.*VELNOR_WORKFLOW_POLICY_REVISION:[[:space:]]*([0-9a-f]{40}).*/\1/p' .github/workflows/ci-policy.yml | head -n 1)"
          test "$pin" != '' || { echo "::error::audited tree declares no generator pin" >&2; exit 1; }
"#
}

/// Consumer policy steps acquiring the audited tree's declared generator as
/// a release product. Consumer pins always name released generators, so a
/// second setup call with the runtime-read pin suffices; when the pin equals
/// the base validator the steps skip and the validator renders directly.
fn policy_renderer_steps(repository: &str, revision: &str) -> String {
    let setup_uses = if !repository.is_empty() && repository == workflow_setup_action_repository() {
        VELNOR_WORKFLOW_POLICY_SETUP_ACTION.to_owned()
    } else {
        workflow_setup_action_uses(repository, revision)
    };
    format!(
        r#"      - name: Read declared generator pin
        id: pin
        working-directory: policy-checkout
        run: |
          set -euo pipefail
{pin_script}          echo "value=$pin" >> "$GITHUB_OUTPUT"
      - name: Set up declared generator product
        id: renderer
        if: steps.pin.outputs.value != '{revision}'
        uses: {setup_uses}
        with:
          rev: ${{{{ steps.pin.outputs.value }}}}
          checkout-path: ${{{{ github.workspace }}}}/policy-checkout
      - name: Resolve declared generator product
        if: steps.pin.outputs.value != '{revision}'
        run: |
          set -euo pipefail
          binary="$HOME/.cache/velnor/workflow-runtime/${{{{ steps.renderer.outputs.closure }}}}/bin/velnor-workflow"
          test -x "$binary"
          echo "{VELNOR_WORKFLOW_PINNED_BINARY_ENV}=$binary" >> "$GITHUB_ENV"
"#,
        pin_script = audited_pin_script(),
    )
}

/// The policy job body. It is deliberately a `steps` job, not a
/// reusable-workflow call: a same-repository reusable call pinned to another
/// revision stops GitHub from dispatching any job of the caller on push,
/// schedule, and `workflow_dispatch` events (the run stays `pending` with
/// zero jobs until the next push cancels it).
///
/// The job checks out the base repository's full history (so pin ancestry
/// is decidable), fetches and checks out the audited head, acquires the
/// pinned validator as an immutable prebuilt product, resolves the live
/// ruleset contexts, and runs `velnor-workflow policy` with explicit
/// `--head-sha` / `--base-sha`. The owner lane additionally checks out the
/// base tree's setup-action directory sparsely under `policy-setup-action/`
/// first, so the local `./…` setup step resolves. The validator regenerates the
/// tree with the generator the tree declares and evaluates its own semantic
/// rules; see `policy.rs`.
///
/// Nothing here compiles or executes candidate code: hosted lanes acquire the
/// declared active renderer through `setup-velnor-workflow`; the Velnor lane
/// provisions its host-persistent slot.
pub(crate) fn policy_job(spec: &PolicyJobSpec<'_>) -> String {
    let PolicyJobSpec {
        name,
        revision,
        runner,
        repository,
        cache_backend,
        trusted_gate,
        default_branch,
        declared_ruleset_contexts,
    } = *spec;
    let trusted_gate = trusted_gate.unwrap_or_default();
    let hosted = cache_backend == "github";
    let owner = !repository.is_empty() && repository == workflow_setup_action_repository();
    let ruleset_step = if hosted {
        format!(
            "      - name: Resolve required status checks\n        env:\n          GH_TOKEN: ${{{{ github.token }}}}\n          DEFAULT_BRANCH: {default_branch}\n          DECLARED_RULESET_CONTEXTS: {declared_ruleset_contexts}\n        run: |\n          set -euo pipefail\n          stderr=\"$(mktemp)\"\n          trap 'rm -f \"$stderr\"' EXIT\n          if contexts=\"$(gh api \"repos/$GITHUB_REPOSITORY/rulesets?includes_parents=true\" 2>\"$stderr\" \\\n            | jq -r '.[] | select(.target == \"branch\" and .enforcement == \"active\") | .id' \\\n            | while read -r id; do gh api \"repos/$GITHUB_REPOSITORY/rulesets/$id\"; done \\\n            | jq -r --arg branch \"refs/heads/$DEFAULT_BRANCH\" 'select(.conditions.ref_name.include | any(. == \"~DEFAULT_BRANCH\" or . == \"~ALL\" or . == $branch)) | .rules[] | select(.type == \"required_status_checks\") | .parameters.required_status_checks[].context' \\\n            | sort -u | paste -sd, -)\"; then\n            :\n          elif grep -qE '(HTTP 403|Upgrade to GitHub Team)' \"$stderr\"; then\n            echo \"::warning::rulesets API returned 403; falling back to declared contexts [$DECLARED_RULESET_CONTEXTS]\"\n            contexts=\"$DECLARED_RULESET_CONTEXTS\"\n          else\n            cat \"$stderr\" >&2\n            exit 1\n          fi\n          echo \"RULESET_CONTEXTS=$contexts\" >> \"$GITHUB_ENV\"\n"
        )
    } else {
        String::new()
    };
    let policy_arguments = if hosted {
        "            --ruleset-contexts \"$RULESET_CONTEXTS\"\n"
    } else {
        ""
    };
    let validator = if hosted {
        let setup_uses = if owner {
            VELNOR_WORKFLOW_POLICY_SETUP_ACTION.to_owned()
        } else {
            workflow_setup_action_uses(repository, revision)
        };
        format!(
            "      - name: Set up Velnor workflow runtime\n        uses: {setup_uses}\n        with:\n          rev: {revision}\n          checkout-path: ${{{{ github.workspace }}}}/policy-checkout\n"
        )
    } else {
        workflow_pinned_policy_runtime_local(revision, "${{ github.workspace }}/policy-checkout")
    };
    // The owner runs the setup action from its own checkout (`./…`), but the
    // policy job checks the repository out only under `policy-checkout/`, so
    // without a second checkout the setup step's `uses:` cannot resolve and
    // the job dies at setup. The sparse checkout provisions exactly the
    // composite action directory from the BASE tree under the sibling
    // `policy-setup-action/`: never the PR head, and never resolved out of
    // `policy-checkout/`, either of which would execute fork-controlled
    // action code under pull_request_target. It must not land at the
    // workspace root: a root checkout wipes `policy-checkout/` under
    // `clean: true` and the Acquire step then has no working directory.
    // Consumers pin the published action and the Velnor lane provisions its
    // slot, so neither needs this checkout.
    let setup_checkout = if hosted && owner {
        format!(
            "      - name: Check out base setup action\n        uses: {}\n        with:\n          ref: ${{{{ github.event.pull_request.base.sha || github.sha }}}}\n          path: policy-setup-action\n          sparse-checkout: .github/actions/setup-velnor-workflow\n          fetch-depth: 1\n          persist-credentials: false\n",
            ActionPin::Checkout.reference()
        )
    } else {
        String::new()
    };
    let renderer = if hosted {
        policy_renderer_steps(repository, revision)
    } else {
        String::new()
    };
    format!(
        "  policy:\n    name: {name}\n{trusted_gate}    runs-on: {runner}\n    timeout-minutes: 20\n    # Trust invariant: this job runs the base branch's Stage-0 validator\n    # product against the audited tree under pull_request_target. It holds\n    # `contents: read` only, references no secrets, persists no credentials,\n    # and never compiles. The declared active renderer is acquired as an\n    # immutable published product and used for every render and policy check.\n    # Candidate PR artifacts are qualified in their own workflow and are\n    # never executed or discovered by this trusted policy job.\n    permissions:\n      contents: read\n    steps:\n      - name: Checkout repository history\n        uses: {}\n        with:\n          path: policy-checkout\n          fetch-depth: 0\n          persist-credentials: false\n      - name: Check out audited head\n        working-directory: policy-checkout\n        env:\n          HEAD_SHA: ${{{{ github.event.pull_request.head.sha || github.sha }}}}\n          HEAD_REPOSITORY: ${{{{ github.event.pull_request.head.repo.full_name || github.repository }}}}\n        run: |\n          set -euo pipefail\n          if ! git cat-file -e \"$HEAD_SHA^{{commit}}\" 2>/dev/null; then\n            git fetch --no-tags \"$GITHUB_SERVER_URL/$HEAD_REPOSITORY\" \"$HEAD_SHA\"\n          fi\n          git checkout --quiet --detach \"$HEAD_SHA\"\n{setup_checkout}{validator}{renderer}{ruleset_step}      - name: Enforce workflow policy\n        env:\n          WORKFLOW_ROOT: ${{{{ github.workspace }}}}/policy-checkout\n          HEAD_SHA: ${{{{ github.event.pull_request.head.sha || github.sha }}}}\n          BASE_SHA: ${{{{ github.event.pull_request.base.sha || github.sha }}}}\n          {VELNOR_POLICY_REVISION_ENV}: {revision}\n        run: |\n          set -euo pipefail\n          velnor-workflow policy \\\n            --workflow-root \"$WORKFLOW_ROOT\" \\\n            --head-sha \"$HEAD_SHA\" \\\n            --base-sha \"$BASE_SHA\" \\\n{policy_arguments}\n{actionlint_setup}      - name: Lint caller workflows\n        working-directory: policy-checkout\n        env:\n          MISE_NO_CONFIG: \"1\"\n        run: mise exec actionlint@{ACTIONLINT_VERSION} -- actionlint\n",
        ActionPin::Checkout.reference(),
        actionlint_setup = actionlint_setup_step(cache_backend),
    )
}

/// The step that provisions the pinned actionlint for the policy job. The
/// hosted lane installs it through `jdx/mise-action` (no `mise.toml` sits in
/// the workspace; the checkout lives under `policy-checkout`, so
/// `install_args` names the exact tool); the Velnor lane uses the host's mise
/// directly because `mise-action` is not admitted there. Both lanes run the
/// binary through `mise exec actionlint@<version>` with `MISE_NO_CONFIG=1`:
/// the pin on the command line selects the tool, but mise would still load
/// the fork tree's `mise.toml` `[env]` (including `_.path` prepends) for the
/// lint's working directory — the env var, not the explicit version, is what
/// neutralizes fork-controlled config. (`mise exec` has no `--no-config`
/// flag; the env form is the only confinement.)
fn actionlint_setup_step(cache_backend: &str) -> String {
    if cache_backend == "github" {
        format!(
            "      - name: Set up actionlint\n        uses: {}\n        with:\n          install_args: actionlint@{ACTIONLINT_VERSION}\n          cache: false\n",
            ActionPin::Mise.reference()
        )
    } else {
        format!(
            "      - name: Set up actionlint\n        run: mise --yes install actionlint@{ACTIONLINT_VERSION}\n"
        )
    }
}

/// Refuse a root `mise.lock` that pins actionlint at a version other than the
/// one the policy job installs: two pins for one tool with no coherence check
/// is the P0-5 bug class, and the local `mise run actionlint` task must lint
/// with the same release the policy job enforces.
fn validate_actionlint_pin_coherence(root: &Path) -> Result<(), GeneratorError> {
    let Some(version) = config::mise_lock_actionlint_version(root)? else {
        return Ok(());
    };
    if version == ACTIONLINT_VERSION {
        return Ok(());
    }
    Err(GeneratorError::usage(format!(
        "mise.lock pins actionlint {version} but the generated policy job installs actionlint {ACTIONLINT_VERSION}; align the lock (`mise use actionlint@{ACTIONLINT_VERSION}`) or bump `ACTIONLINT_VERSION` in the generator"
    )))
}

/// The control-plane `runs-on:` value: every control-plane job renders
/// through here. The provider derives from the universe (hosted when
/// present, otherwise the canonical-first local provider); a missing
/// selector is a caller bug that fails here instead of rendering an empty
/// `runs-on` or a hardcoded fallback label.
pub(crate) fn control_plane_runner(config: &ProjectConfig) -> Result<String, GeneratorError> {
    provider::runs_on_for(
        &config.selectors,
        provider::control_plane_provider(&config.providers),
    )
    .map(runs_on_labels_yaml)
}

/// The canonical trusted-event predicate every local control-plane job
/// conjoins onto its functional `if:` condition. One literal, shared by the
/// IR and every standalone control-plane workflow, so the gate shape cannot
/// drift between lanes.
pub(crate) const TRUSTED_EVENT_EXPRESSION: &str = "!(github.event_name == 'pull_request' && (github.event.pull_request.head.repo.fork || github.event.pull_request.user.type == 'Bot'))";

/// The control-plane admission gate for standalone workflow files: local
/// control planes conjoin the trusted-event predicate, hosted ones keep the
/// functional condition as is.
pub(crate) struct ControlPlaneGate {
    local: bool,
}

pub(crate) fn control_plane_gate(config: &ProjectConfig) -> ControlPlaneGate {
    ControlPlaneGate {
        local: provider::control_plane_provider(&config.providers).is_local(),
    }
}

impl ControlPlaneGate {
    /// Whether the control plane runs on local runners and gates jobs.
    pub(crate) fn is_local(&self) -> bool {
        self.local
    }

    /// Conjoin a job's functional `if:` condition with the trusted-event
    /// predicate on a local control plane. The functional side stays inside
    /// its own parentheses so the gate matcher verifies the shape without
    /// parsing expressions. Hosted control planes keep the condition as is.
    pub(crate) fn as_job_condition(&self, condition: &str) -> String {
        if self.local {
            format!("({condition}) && ({TRUSTED_EVENT_EXPRESSION})")
        } else {
            condition.to_owned()
        }
    }
}

#[cfg_attr(not(test), allow(dead_code))]
pub(crate) fn control_plane_trusted_gate(default_branch: &str) -> String {
    format!(
        "    if: ${{{{ github.event_name == 'pull_request_target' || (github.ref == 'refs/heads/{default_branch}' && (github.event_name == 'push' || github.event_name == 'schedule' || github.event_name == 'workflow_dispatch')) }}}}\n"
    )
}

pub(crate) fn render_policy_entrypoint(config: &ProjectConfig) -> Result<String, GeneratorError> {
    let runner = control_plane_runner(config)?;
    let local = provider::control_plane_provider(&config.providers).is_local();
    let gate = local.then(|| control_plane_trusted_gate(&config.default_branch));
    let declared_ruleset_contexts = declared_ruleset_contexts_literal(config);
    let policy_job = policy_job(&PolicyJobSpec {
        name: "Policy",
        revision: &config.workflow_revision,
        runner: &runner,
        repository: &config.repository,
        cache_backend: if local { "local" } else { "github" },
        trusted_gate: gate.as_deref(),
        default_branch: &config.default_branch,
        declared_ruleset_contexts: &declared_ruleset_contexts,
    });
    let concurrency = policy_concurrency_block(config);
    // `workflow_dispatch` lets a maintainer prove the validator the base
    // branch carries passes on the base tree itself (head = base = the
    // dispatched commit), which is how a bootstrap is confirmed after merge.
    Ok(format!(
        "{GENERATED_HEADER}name: Velnor workflow policy\n\non:\n  pull_request_target:\n    types: [opened, synchronize, reopened]\n  workflow_dispatch:\n\n{concurrency}permissions:\n  contents: read\n\njobs:\n{policy_job}"
    ))
}

fn policy_concurrency_block(config: &ProjectConfig) -> String {
    let group = concurrency_group_expression(config).map_or_else(
        || {
            "policy-${{ github.repository }}-${{ github.event.pull_request.number || github.ref }}"
                .to_owned()
        },
        |group| format!("{group}-policy"),
    );
    format!("concurrency:\n  group: {group}\n  cancel-in-progress: true\n\n")
}

fn concurrency_group_expression(config: &ProjectConfig) -> Option<String> {
    if config.providers.iter().any(|provider| provider.is_local()) {
        config.concurrency_group.clone()
    } else {
        None
    }
}

/// The aggregate caller job for one kind reusable: `ci-unit-rust.yml` →
/// `group-rust`.
pub(crate) fn stack_group_job_id(kind: UnitKind) -> String {
    format!("group-{}", kind.id_prefix())
}

pub(crate) fn unit_group_job_id(unit: &Unit) -> String {
    format!("group-unit-{}", identifier_suffix(&unit.id))
}

/// Whether `provider` can statically execute `unit`: platform and
/// capabilities. Trust is dynamic (event-dependent), so it never removes a
/// caller here — the admission gate and the planner exclusion carry it.
pub(crate) fn provider_supports_unit(provider: provider::ProviderId, unit: &Unit) -> bool {
    let caps = provider::provider_caps(provider);
    caps.platforms.contains(&unit.platform) && unit.capabilities.missing_in(caps.caps).is_empty()
}

/// Fail generation when a unit is statically eligible on no provider of the
/// universe: it could never run, so declaring it is a configuration error.
/// Platform/trust exclusions for individual providers are declared by the
/// planner per event, not here.
fn validate_unit_provider_coverage(config: &ProjectConfig) -> Result<(), GeneratorError> {
    for unit in &config.units {
        if config
            .providers
            .iter()
            .any(|provider| provider_supports_unit(*provider, unit))
        {
            continue;
        }
        return Err(GeneratorError::usage(format!(
            "unit `{}` ({}) is eligible on no provider of [{}]; the runner universe follows the repository visibility evidence and cannot be widened, so remove the unit or move it to a platform the provider supports",
            unit.id,
            unit.kind.label(),
            config
                .providers
                .iter()
                .map(provider::ProviderId::as_str)
                .collect::<Vec<_>>()
                .join(", ")
        )));
    }
    Ok(())
}

const CI_PR_WORKFLOW: &str = ".github/workflows/ci-pr.yml";
const CI_POLICY_WORKFLOW: &str = ".github/workflows/ci-policy.yml";

pub(crate) fn workflow_job_display_names(
    source: &str,
    yaml: &str,
) -> Result<BTreeSet<String>, GeneratorError> {
    let doc: Value = serde_yaml::from_str(yaml).map_err(|error| {
        GeneratorError::usage(format!("parse {source} for ruleset validation: {error}"))
    })?;
    let Some(jobs) = doc.get("jobs").and_then(Value::as_mapping) else {
        return Err(GeneratorError::usage(format!(
            "{source} is missing a top-level `jobs` mapping"
        )));
    };
    let mut names = BTreeSet::new();
    for job in jobs.values() {
        if let Some(name) = job.get("name").and_then(Value::as_str) {
            names.insert(name.to_owned());
        }
    }
    Ok(names)
}

fn ruleset_required_status_check_contexts(config: &ProjectConfig) -> Vec<String> {
    if !config.ruleset_required_status_checks.is_empty() {
        return config.ruleset_required_status_checks.clone();
    }
    if config.ci_required {
        return vec![crate::s2::reuse::REQUIRED_CHECK.to_owned()];
    }
    Vec::new()
}

/// Comma-separated ruleset contexts from `[policy]` for hosted policy jobs
/// when the GitHub rulesets API is unavailable (private repos without Team).
pub(crate) fn declared_ruleset_contexts_literal(config: &ProjectConfig) -> String {
    let mut contexts: BTreeSet<String> = ruleset_required_status_check_contexts(config)
        .into_iter()
        .collect();
    contexts.extend(config.ruleset_external_status_checks.iter().cloned());
    contexts.insert("Policy".to_owned());
    contexts.into_iter().collect::<Vec<_>>().join(",")
}

/// Fail closed when a repository ruleset context is absent from the union
/// of `ci-pr.yml` and `ci-policy.yml` job display names.
fn validate_ruleset_required_status_checks(
    config: &ProjectConfig,
    files: &BTreeMap<PathBuf, String>,
) -> Result<(), GeneratorError> {
    let required = ruleset_required_status_check_contexts(config);
    if required.is_empty() {
        return Ok(());
    }
    let pr_path = PathBuf::from(CI_PR_WORKFLOW);
    let Some(pr_yaml) = files.get(&pr_path) else {
        // Adopted or release-only surfaces omit the PR aggregate by design.
        return Ok(());
    };
    let mut names = workflow_job_display_names(CI_PR_WORKFLOW, pr_yaml)?;
    if let Some(policy_yaml) = files.get(&PathBuf::from(CI_POLICY_WORKFLOW)) {
        names.extend(workflow_job_display_names(CI_POLICY_WORKFLOW, policy_yaml)?);
    }
    for context in required {
        if !names.contains(&context) {
            return Err(GeneratorError::usage(format!(
                "ruleset required status check `{context}` is absent from {CI_PR_WORKFLOW} and {CI_POLICY_WORKFLOW} job names; found [{}]",
                names.iter().map(String::as_str).collect::<Vec<_>>().join(", ")
            )));
        }
    }
    Ok(())
}

pub(crate) fn rust_dependency_needs(
    provider: provider::ProviderId,
    unit: &Unit,
    rust_needs: RustNeeds,
    units: &[Unit],
) -> Vec<String> {
    // Dependency ordering exploits host-persistent shared stores: a dependent
    // reuses its dependency's warm artifacts. Ephemeral hosted runners share
    // nothing, so ordering there only serializes — local providers only.
    if !provider.is_local()
        || rust_needs != RustNeeds::DependencyClosure
        || unit.kind != UnitKind::Rust
    {
        return Vec::new();
    }
    unit.depends_on
        .iter()
        .filter_map(|dependency| {
            units
                .iter()
                .find(|candidate| candidate.id == *dependency)
                .and_then(|dependency_unit| {
                    if dependency_unit.kind == UnitKind::Rust
                        && provider_supports_unit(provider, dependency_unit)
                    {
                        Some(unit_job_id(provider, dependency))
                    } else {
                        None
                    }
                })
        })
        .collect()
}

/// The caller-level `needs` edges for verified product transport: one
/// producer caller job per prerequisite edge whose product can ride an
/// artifact on `provider`. Hosted only — local providers share the
/// workspace, so their consumers rebuild or reuse in place. An edge whose
/// producer cannot run here, or whose product declares no outputs, yields
/// no edge because no artifact contract exists. A declared transport edge is
/// mandatory: its consumer never rebuilds around a skipped or failed producer.
pub(crate) fn product_dependency_needs(
    provider: provider::ProviderId,
    unit: &Unit,
    units: &[Unit],
) -> Vec<String> {
    if !matches!(provider, provider::ProviderId::GithubHosted) {
        return Vec::new();
    }
    let mut needs = Vec::new();
    for prerequisite in &unit.prerequisites {
        let Some(producer) = units
            .iter()
            .find(|candidate| candidate.id == prerequisite.producer)
        else {
            continue;
        };
        let requires_producer_success = producer.products.iter().any(|product| {
            product.name == prerequisite.product
                && crate::s2::primitives::product_transport::transport_contract(product)
                    .requires_producer_success()
        });
        if requires_producer_success && provider_supports_unit(provider, producer) {
            let job = unit_job_id(provider, &prerequisite.producer);
            if !needs.contains(&job) {
                needs.push(job);
            }
        }
    }
    needs
}

/// The GitHub-owned macOS image jobs with `platform = "macos-arm64"` run on.
/// Hosted selectors carry Linux labels; Apple execution needs the macOS
/// image, which only exists on the hosted provider.
pub(crate) const MACOS_HOSTED_RUNS_ON: &str = "macos-26";

/// The `runs-on:` YAML value for one provider selector: a bare scalar for a
/// single label, a flow list otherwise.
pub(crate) fn selector_runs_on_yaml(selector: &provider::ProviderSelector) -> String {
    runs_on_labels_yaml(&selector.runs_on)
}

/// The `runs-on:` YAML value for a label slice: a bare scalar for a single
/// label, a flow list otherwise.
pub(crate) fn runs_on_labels_yaml(labels: &[String]) -> String {
    if labels.len() == 1 {
        return yaml_scalar(&labels[0]);
    }
    let labels = labels
        .iter()
        .map(|label| yaml_scalar(label))
        .collect::<Vec<_>>()
        .join(", ");
    format!("[{labels}]")
}

/// The `runs-on:` expression form of one selector, for templates that embed
/// the legacy `fromJSON(...)` selector shape.
pub(crate) fn selector_runs_on_expression(selector: &provider::ProviderSelector) -> String {
    let labels = selector
        .runs_on
        .iter()
        .map(|label| format!("\\\"{label}\\\""))
        .collect::<Vec<_>>()
        .join(",");
    format!("fromJSON('[{labels}]')")
}

pub(crate) fn github_expression(expression: &str) -> String {
    format!("${{{{ {expression} }}}}")
}

/// Render a string as a YAML scalar that a YAML 1.1/1.2 reader resolves as a
/// string. Plain spelling is kept only for words that cannot resolve to
/// another type: a value the reader would type as a boolean (`true`, `no`,
/// `off`), a null (`null`, `~`), or a number (a leading digit, sign, or dot)
/// is double-quoted, so a `workflow_call` string input never receives a
/// boolean or a number and a unit id is never re-typed.
pub(crate) fn yaml_scalar(value: &str) -> String {
    let plain_characters = value
        .chars()
        .all(|character| character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.'));
    let typed_word = matches!(
        value.to_ascii_lowercase().as_str(),
        "true" | "false" | "yes" | "no" | "on" | "off" | "y" | "n" | "null" | "~"
    );
    let numeric_shape = value
        .chars()
        .next()
        .is_some_and(|first| first.is_ascii_digit() || matches!(first, '-' | '.'));
    if !value.is_empty() && plain_characters && !typed_word && !numeric_shape {
        value.to_owned()
    } else {
        format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""))
    }
}

/// Hosted runtime setup for jobs that also run the policy check: a single
/// setup of the declared pin, which is both the runtime on PATH and the
/// policy binary. No second revision is ever provisioned next to it.
fn workflow_runtime_setup(
    provider: provider::ProviderId,
    repository: &str,
    revision: &str,
) -> String {
    workflow_runtime_setup_with_install_rev(provider, repository, revision, revision)
}

/// Hosted runtime setup when the owner's composite action is inside a
/// checkout at `checkout_path`. Consumers still resolve the immutable remote
/// action; only the owner-local action path is rooted at the named checkout.
pub(crate) fn workflow_runtime_setup_at_checkout_path(
    provider: provider::ProviderId,
    repository: &str,
    revision: &str,
    checkout_path: &str,
) -> String {
    workflow_runtime_setup_with_install_rev_at_checkout_path(
        provider,
        repository,
        revision,
        revision,
        Some(checkout_path),
    )
}

/// The `uses:` reference for `setup-velnor-workflow`: the owner's checkout
/// (`./…`, no version) for the repository that ships the action, the
/// published `revision` pin for every consumer.
pub(crate) fn workflow_setup_action_uses(repository: &str, revision: &str) -> String {
    workflow_setup_action_uses_at_checkout_path(repository, revision, None)
}

fn workflow_setup_action_uses_at_checkout_path(
    repository: &str,
    revision: &str,
    checkout_path: Option<&str>,
) -> String {
    if !repository.is_empty() && repository == workflow_setup_action_repository() {
        checkout_path.map_or_else(
            || VELNOR_WORKFLOW_LOCAL_SETUP_ACTION.to_owned(),
            |path| {
                format!(
                    "./{path}/{}",
                    VELNOR_WORKFLOW_LOCAL_SETUP_ACTION
                        .strip_prefix("./")
                        .unwrap_or(VELNOR_WORKFLOW_LOCAL_SETUP_ACTION)
                )
            },
        )
    } else {
        format!("{VELNOR_WORKFLOW_SETUP_ACTION}@{revision}")
    }
}

/// The `uses:` reference for `report-velnor-ci-outcomes`: local path for the
/// owner repository, published pin for every consumer.
pub(crate) fn ci_report_action_uses(repository: &str, revision: &str) -> String {
    if !repository.is_empty() && repository == workflow_setup_action_repository() {
        VELNOR_CI_LOCAL_REPORT_ACTION.to_owned()
    } else {
        format!("{VELNOR_CI_REPORT_ACTION}@{revision}")
    }
}

/// The repository that publishes `setup-velnor-workflow`, derived from the
/// action's own coordinate so owner/consumer routing cannot drift from it.
pub(crate) fn workflow_setup_action_repository() -> &'static str {
    match VELNOR_WORKFLOW_SETUP_ACTION.split_once("/.github/") {
        Some((repository, _)) => repository,
        None => VELNOR_WORKFLOW_SETUP_ACTION,
    }
}

/// Hosted `rev:` for `setup-velnor-workflow`: always the tree's declared
/// generator pin, for every repository and every event.
///
/// The runtime product is identified by the generator revision the tree
/// declares, never by the event SHA. On `pull_request`, `github.sha` is the
/// synthetic `refs/pull/<n>/merge` commit; no trusted default-branch product
/// can ever have been built at that SHA, so resolving the runtime through it
/// misses by construction and every consumer falls back to compiling from
/// source. The pin is the Stage-0 product every lane consumes; a candidate
/// generator under test is produced at most once by the producer job and
/// shared as an artifact, never rebuilt inside consumers.
pub(crate) fn workflow_setup_install_rev(_repository: &str, revision: &str) -> String {
    revision.to_owned()
}

/// Hosted runtime install. `uses:` is [`workflow_setup_action_uses`] (the
/// owner's checkout, or the published pin for consumers — GitHub Actions
/// rejects expressions in `uses:` versions, HTTP 422). `rev:` is
/// `install_rev`, always the tree's declared pin: every lane consumes the
/// same Stage-0 product, never an event SHA.
fn workflow_runtime_setup_with_install_rev(
    provider: provider::ProviderId,
    repository: &str,
    revision: &str,
    install_rev: &str,
) -> String {
    workflow_runtime_setup_with_install_rev_at_checkout_path(
        provider,
        repository,
        revision,
        install_rev,
        None,
    )
}

fn workflow_runtime_setup_with_install_rev_at_checkout_path(
    provider: provider::ProviderId,
    repository: &str,
    revision: &str,
    install_rev: &str,
    checkout_path: Option<&str>,
) -> String {
    if provider != provider::ProviderId::GithubHosted {
        return String::new();
    }
    format!(
        "      - name: Set up Velnor workflow runtime\n        id: runtime\n        uses: {}\n        with:\n          rev: {install_rev}\n      - name: Set trusted workflow policy revision\n        run: echo \"{VELNOR_POLICY_REVISION_ENV}={revision}\" >> \"$GITHUB_ENV\"\n",
        workflow_setup_action_uses_at_checkout_path(repository, revision, checkout_path)
    )
}

/// Where `setup-velnor-workflow` keeps every hosted runtime it provisions:
/// one directory per revision, holding the product layout
/// (`bin/velnor-workflow`) and the product `manifest.json`. The directory is
/// the action's cache path and the landing place of a downloaded product, so
/// a caller that needs a specific revision addresses it by path instead of by
/// whatever `~/.cargo/bin` holds.
pub(crate) const HOSTED_WORKFLOW_RUNTIME_HOME: &str = "$HOME/.cache/velnor/workflow-runtime";

/// Velnor lane: the job home is the packaged runtime, whose revision follows
/// the fleet release rather than the generator pin, so a unit that runs the
/// generator's `--check` provisions the pinned binary itself. `$CARGO_HOME/bin`
/// is the host-persistent (trust-scoped) executable store, so one download per
/// slot per closure serves every later job. Nothing here compiles: the step
/// resolves the pin's source-closure digest from the job checkout (fetching
/// the pin commit when a shallow checkout does not contain it), downloads and
/// attests the manifest, and compares the slot binary's digest against the
/// manifest before executing anything: a digest mismatch takes the slow path
/// (download the asset, verify attestation and digest, install), and only
/// then — against bytes the digest just proved — does the step execute the
/// slot binary for its `--closure` self-report gate. Digest decides reuse;
/// the self-report only confirms. The step exports the slot for the guard
/// (`VELNOR_WORKFLOW_PINNED_BINARY`) so the offline check never compiles.
/// The reuse path stays online (one manifest download plus one attestation
/// verification per run; the asset downloads only on mismatch): offline reuse
/// of a persistent-host slot on self-report alone is the planted-binary hole
/// this manifest-first shape closes.
///
/// Residual Velnor-lane trust scope (documented, not fixed here):
/// * `verify-velnor` executes `velnor-workflow run` from the fleet image at
///   whatever revision the fleet ships; a stale or divergent fleet runtime
///   silently changes check semantics for **all** Velnor units, with no
///   per-job digest or self-report gate.
/// * Only the `velnor-workflow-policy` slot is pinned and verified, and only
///   when the dispatched unit runs `--plain --check` (today: the generator
///   owner unit only). Non-owner Velnor units run fully ambient.
/// * The slot is host-persistent and trust-scoped: reuse spans jobs on the
///   host, and the check step relies on `VELNOR_WORKFLOW_PINNED_BINARY`,
///   never `PATH`, for the guard.
/// * Fleet-vs-pin drift for the `run` binary has no alarm by design; if that
///   becomes unacceptable, the fix is a new feature (provision and verify
///   `velnor-workflow` on Velnor per job, mirroring the GitHub
///   `Download`→`Verify`→`Add to PATH` triple), not a parity restoration.
pub(crate) fn workflow_pinned_policy_runtime_local(revision: &str, checkout: &str) -> String {
    format!(
        "      - name: Provision pinned Velnor workflow policy runtime\n        shell: bash\n        env:\n          GH_TOKEN: ${{{{ github.token }}}}\n          PINNED_REVISION: {revision}\n          CHECKOUT_PATH: {checkout}\n        run: |\n          set -euo pipefail\n          if ! git -C \"$CHECKOUT_PATH\" cat-file -e \"$PINNED_REVISION^{{commit}}\" 2>/dev/null; then\n            git fetch --no-tags --depth 1 \"$GITHUB_SERVER_URL/$GITHUB_REPOSITORY\" \"$PINNED_REVISION\"\n          fi\n          listing=\"$(git -C \"$CHECKOUT_PATH\" ls-tree -r \"$PINNED_REVISION\" -- crates/velnor-workflow Cargo.toml Cargo.lock rust-toolchain.toml rust-toolchain .cargo)\"\n          test \"$listing\" != '' || {{ echo \"::error::revision $PINNED_REVISION has no closure inputs\" >&2; exit 1; }}\n          if command -v sha256sum >/dev/null 2>&1; then\n            closure=\"$(printf '%s\\nclosure-version:1\\nfeatures:\\nprofile:release\\n' \"$(LC_ALL=C sort <<<\"$listing\")\" | sha256sum | awk '{{print $1}}')\"\n          else\n            closure=\"$(printf '%s\\nclosure-version:1\\nfeatures:\\nprofile:release\\n' \"$(LC_ALL=C sort <<<\"$listing\")\" | shasum -a 256 | awk '{{print $1}}')\"\n          fi\n          binary=\"${{CARGO_HOME:-$HOME/.cargo}}/bin/velnor-workflow-policy\"\n          tag=\"velnor-workflow-runtime-v1-${{closure:0:16}}\"\n          asset=\"velnor-workflow-${{RUNNER_OS}}-${{RUNNER_ARCH}}\"\n          temporary=\"$(mktemp -d)\"\n          trap 'rm -rf \"$temporary\"' EXIT\n          if ! gh release download \"$tag\" --repo tailrocks/velnor --pattern manifest.json --dir \"$temporary\"; then\n            echo \"::error::no policy runtime product for revision $PINNED_REVISION (closure ${{closure:0:16}}); the mainline runtime-product publisher builds it after merge\" >&2\n            exit 1\n          fi\n          gh attestation verify \"$temporary/manifest.json\" --owner tailrocks --signer-workflow tailrocks/velnor/.github/workflows/ci-runtime-products.yml\n          revision=\"$(jq -er '.revision | select(test(\"^[0-9a-f]{{40}}$\"))' \"$temporary/manifest.json\")\"
          jq -e --arg closure \"$closure\" --arg revision \"$revision\" --arg platform \"${{RUNNER_OS}}-${{RUNNER_ARCH}}\" --arg asset \"$asset\" '.closure == $closure and (.revision | test(\"^[0-9a-f]{{40}}$\")) and .profile == \"release\" and .features == \"\" and (.products[$platform].binary | test(\"^[0-9a-f]{{64}}$\")) and .products[$platform].asset == $asset and (.products[$platform].build | .schema == \"velnor-workflow.runtime-build-identity.v1\" and .source_revision == $revision and .platform == $platform and .toolchain != \"\" and .rustc != \"\" and .target != \"\" and .host != \"\" and .profile == \"release\" and .features == \"\" and (.rustflags | type == \"string\") and (.cargo_encoded_rustflags | type == \"string\") and (.linker | type == \"string\") and (.cc | type == \"string\") and (.cflags | type == \"string\"))' \"$temporary/manifest.json\" >/dev/null
          expected=\"$(jq -er --arg platform \"${{RUNNER_OS}}-${{RUNNER_ARCH}}\" '.products[$platform].binary' \"$temporary/manifest.json\")\"\n          existing=\"\"\n          if [[ -x \"$binary\" ]]; then\n            if command -v sha256sum >/dev/null 2>&1; then\n              existing=\"$(sha256sum \"$binary\" | awk '{{print $1}}')\"\n            else\n              existing=\"$(shasum -a 256 \"$binary\" | awk '{{print $1}}')\"\n            fi\n          fi\n          if [[ \"$existing\" != \"$expected\" ]]; then\n            gh release download \"$tag\" --repo tailrocks/velnor --pattern \"$asset\" --dir \"$temporary\"\n            gh attestation verify \"$temporary/$asset\" --owner tailrocks --signer-workflow tailrocks/velnor/.github/workflows/ci-runtime-products.yml\n            if command -v sha256sum >/dev/null 2>&1; then\n              actual=\"$(sha256sum \"$temporary/$asset\" | awk '{{print $1}}')\"\n            else\n              actual=\"$(shasum -a 256 \"$temporary/$asset\" | awk '{{print $1}}')\"\n            fi\n            [[ \"$actual\" == \"$expected\" ]] || {{ echo \"::error::policy runtime digest mismatch\" >&2; exit 1; }}\n            install -Dm0755 \"$temporary/$asset\" \"$binary\"\n          fi\n          reported=\"$(\"$binary\" --closure)\"\n          [[ \"$reported\" == \"$closure\" ]] || {{ echo \"::error::pinned workflow policy runtime reports closure $reported, expected $closure\" >&2; exit 1; }}\n          echo \"{VELNOR_WORKFLOW_PINNED_BINARY_ENV}=$binary\" >> \"$GITHUB_ENV\"\n"
    )
}

/// Where a hosted unit job places the runtime pair it downloads from the
/// Planning artifact (`bin/velnor-workflow` at the event revision,
/// `bin/velnor-workflow-policy` at the pin). Job-scoped and never
/// `~/.cargo/bin`: that directory is restored from the cargo-bin toolchain
/// cache, so a runtime copied there would be saved into a cache keyed by
/// `mise.lock` and resurface at a stale revision in later jobs.
pub(crate) const HOSTED_WORKFLOW_RUNTIME_ARTIFACT_HOME: &str =
    "$RUNNER_TEMP/velnor-workflow-runtime-artifact";

fn workflow_runtime_download(provider: provider::ProviderId, revision: &str) -> String {
    if provider == provider::ProviderId::GithubHosted {
        format!(
            "      - name: Download Velnor workflow runtime\n        uses: {}\n        with:\n          name: velnor-workflow-runtime-{revision}-${{{{ runner.os }}}}-${{{{ runner.arch }}}}\n          path: .velnor-workflow-runtime\n      - name: Verify Velnor workflow runtime\n        shell: bash\n        env:\n          EXPECTED_REVISION: {revision}\n        run: |\n          set -euo pipefail\n          manifest=.velnor-workflow-runtime/manifest.json\n          jq -e --arg revision \"$EXPECTED_REVISION\" --arg repository \"$GITHUB_REPOSITORY\" --arg platform \"${{RUNNER_OS}}-${{RUNNER_ARCH}}\" --arg run_id \"$GITHUB_RUN_ID\" '.revision == $revision and .repository == $repository and .platform == $platform and .run_id == $run_id and (.run_id | test(\"^[0-9]+$\")) and .job_id != \"\" and (.binary_sha256 | test(\"^[0-9a-f]{{64}}$\")) and (.policy_binary_sha256 | test(\"^[0-9a-f]{{64}}$\")) and (.closure | test(\"^[0-9a-f]{{64}}$\")) and (.policy_closure | test(\"^[0-9a-f]{{64}}$\"))' \"$manifest\" >/dev/null\n          expected=\"$(jq -er '.binary_sha256' \"$manifest\")\"\n          actual=\"$(sha256sum .velnor-workflow-runtime/velnor-workflow | awk '{{print $1}}')\"\n          [[ \"$actual\" == \"$expected\" ]] || {{ echo \"::error::runtime digest mismatch\" >&2; exit 1; }}\n          expected=\"$(jq -er '.policy_binary_sha256' \"$manifest\")\"\n          actual=\"$(sha256sum .velnor-workflow-runtime/velnor-workflow-policy | awk '{{print $1}}')\"\n          [[ \"$actual\" == \"$expected\" ]] || {{ echo \"::error::policy runtime digest mismatch\" >&2; exit 1; }}\n      - name: Add Velnor workflow runtime to PATH\n        shell: bash\n        env:\n          EXPECTED_REVISION: {revision}\n        run: |\n          set -euo pipefail\n          home=\"{HOSTED_WORKFLOW_RUNTIME_ARTIFACT_HOME}\"\n          install -Dm0755 .velnor-workflow-runtime/velnor-workflow \"$home/bin/velnor-workflow\"\n          install -Dm0755 .velnor-workflow-runtime/velnor-workflow-policy \"$home/bin/velnor-workflow-policy\"\n          expected_closure=\"$(jq -er '.policy_closure' .velnor-workflow-runtime/manifest.json)\"\n          reported=\"$(\"$home/bin/velnor-workflow-policy\" --closure)\"\n          [[ \"$reported\" == \"$expected_closure\" ]] || {{ echo \"::error::policy runtime reports closure $reported, expected $expected_closure\" >&2; exit 1; }}\n          echo \"$home/bin\" >> \"$GITHUB_PATH\"\n          echo \"{VELNOR_WORKFLOW_PINNED_BINARY_ENV}=$home/bin/velnor-workflow-policy\" >> \"$GITHUB_ENV\"\n",
            ActionPin::DownloadArtifact.reference()
        )
    } else {
        String::new()
    }
}

fn workflow_runtime_artifact_upload(revision: &str) -> String {
    format!(
        "      - name: Prepare Velnor workflow runtime\n        shell: bash\n        env:\n          EXPECTED_REVISION: {revision}\n        run: |\n          set -euo pipefail\n          stage=\"$RUNNER_TEMP/velnor-workflow-runtime\"\n          rm -rf \"$stage\"\n          mkdir -p \"$stage\"\n          src=\"$(command -v velnor-workflow)\"\n          install -m 0755 \"$src\" \"$stage/velnor-workflow\"\n          digest=\"$(sha256sum \"$stage/velnor-workflow\" | awk '{{print $1}}')\"\n          policy_src=\"${{{VELNOR_WORKFLOW_PINNED_BINARY_ENV}:-$src}}\"\n          install -m 0755 \"$policy_src\" \"$stage/velnor-workflow-policy\"\n          policy_revision=\"$(\"$stage/velnor-workflow-policy\" --revision)\"\n          policy_closure=\"$(\"$stage/velnor-workflow-policy\" --closure)\"\n          [[ \"$policy_closure\" == \"${{{{ steps.runtime.outputs.closure }}}}\" ]] || {{ echo \"::error::policy runtime reports closure $policy_closure, expected ${{{{ steps.runtime.outputs.closure }}}}\" >&2; exit 1; }}\n          policy_digest=\"$(sha256sum \"$stage/velnor-workflow-policy\" | awk '{{print $1}}')\"\n          jq -n --arg repository \"$GITHUB_REPOSITORY\" --arg revision \"$EXPECTED_REVISION\" --arg closure \"${{{{ steps.runtime.outputs.closure }}}}\" --arg head_branch \"${{{{ github.ref_name }}}}\" --arg platform \"${{{{ runner.os }}}}-${{{{ runner.arch }}}}\" --arg run_id \"$GITHUB_RUN_ID\" --arg job_id \"${{{{ github.job }}}}\" --arg binary_sha256 \"$digest\" --arg policy_revision \"$policy_revision\" --arg policy_closure \"$policy_closure\" --arg policy_binary_sha256 \"$policy_digest\" '{{repository: $repository, revision: $revision, closure: $closure, head_branch: $head_branch, platform: $platform, run_id: $run_id, job_id: $job_id, binary_sha256: $binary_sha256, policy_revision: $policy_revision, policy_closure: $policy_closure, policy_binary_sha256: $policy_binary_sha256}}' > \"$stage/manifest.json\"\n      - name: Publish Velnor workflow runtime\n        uses: {}\n        with:\n          name: velnor-workflow-runtime-{revision}-${{{{ runner.os }}}}-${{{{ runner.arch }}}}\n          path: ${{{{ runner.temp }}}}/velnor-workflow-runtime\n          if-no-files-found: error\n          retention-days: 7\n",
        ActionPin::UploadArtifact.reference()
    )
}

/// Selection-file field sources for one materialize step: already-rendered
/// GitHub expressions such as `${{ inputs.base_sha }}` or
/// `${{ needs.plan.outputs.unit_ids }}`. The `units` source must be the
/// plan's CSV `unit_ids` output — never the JSON `units` output, which the
/// runner's CSV-only selection parser rejects.
pub(crate) struct SelectionFieldSources<'a> {
    pub(crate) base_sha: &'a str,
    pub(crate) head_sha: &'a str,
    pub(crate) scope: &'a str,
    pub(crate) units: &'a str,
    pub(crate) full_units: &'a str,
    pub(crate) plan_digest: &'a str,
}

const WORKFLOW_SELECTION_FILE_MATERIALIZE_RUN: &str = r#"          set -euo pipefail
          mkdir -p .velnor-ci-selection
          {
            printf 'version={version}\n'
            printf 'base_sha=%s\n' "$SELECTION_BASE_SHA"
            printf 'head_sha=%s\n' "$SELECTION_HEAD_SHA"
            printf 'scope=%s\n' "$SELECTION_SCOPE"
            printf 'units=%s\n' "$SELECTION_UNITS"
            printf 'full_units=%s\n' "$SELECTION_FULL_UNITS"
            printf 'plan_digest=%s\n' "$SELECTION_PLAN_DIGEST"
          } > .velnor-ci-selection/velnor-ci-selection
"#;

/// Write the plan selection file from values the caller already has (plan
/// outputs or reusable-workflow inputs) instead of an artifact
/// upload/download round-trip. `run` consumes the same seven-field format and
/// keeps its fail-closed SHA/unit/digest checks; transport can no longer skew
/// the SHAs because the file and the job env render from the same sources.
pub(crate) fn workflow_selection_file_materialize(sources: &SelectionFieldSources<'_>) -> String {
    let run = WORKFLOW_SELECTION_FILE_MATERIALIZE_RUN
        .replace("{version}", crate::s2::runtime::SELECTION_FILE_VERSION);
    format!(
        "      - name: Materialize Velnor CI selection\n        shell: bash\n        env:\n          SELECTION_BASE_SHA: {}\n          SELECTION_HEAD_SHA: {}\n          SELECTION_SCOPE: {}\n          SELECTION_UNITS: {}\n          SELECTION_FULL_UNITS: {}\n          SELECTION_PLAN_DIGEST: {}\n        run: |\n{run}",
        sources.base_sha,
        sources.head_sha,
        sources.scope,
        sources.units,
        sources.full_units,
        sources.plan_digest,
    )
}

pub(crate) fn hosted_mold_setup(default_branch: &str, cache_save: bool) -> String {
    let mold_id = "mold-cache";
    let mut output = format!(
        "      - name: Restore mold {MOLD_VERSION} cache\n        id: {mold_id}\n        uses: {}\n        with:\n          path: ~/.cache/velnor/mold/{MOLD_VERSION}\n          key: velnor-mold-{MOLD_VERSION}-${{{{ runner.os }}}}-${{{{ runner.arch }}}}\n      - name: Set up mold {MOLD_VERSION}\n        shell: bash\n        env:\n          MOLD_VERSION: {MOLD_VERSION}\n        run: |\n          set -euo pipefail\n          case \"$(uname -m)\" in\n            x86_64) mold_arch=x86_64; expected='{MOLD_X86_64_SHA256}' ;;\n            aarch64) mold_arch=aarch64; expected='{MOLD_AARCH64_SHA256}' ;;\n            *) echo \"unsupported mold architecture: $(uname -m)\" >&2; exit 1 ;;\n          esac\n          cache_dir=\"$HOME/.cache/velnor/mold/$MOLD_VERSION\"\n          archive=\"$cache_dir/mold-$MOLD_VERSION-$mold_arch-linux.tar.gz\"\n          mkdir -p \"$cache_dir\"\n          if [[ ! -s \"$archive\" ]]; then\n            temporary=\"$archive.download\"\n            trap 'rm -f \"$temporary\"' EXIT\n            curl {curl_flags} \\\n              --output \"$temporary\" \\\n              \"https://github.com/rui314/mold/releases/download/v$MOLD_VERSION/mold-$MOLD_VERSION-$mold_arch-linux.tar.gz\"\n            printf '%s  %s\\n' \"$expected\" \"$temporary\" | sha256sum --check --strict\n            mv \"$temporary\" \"$archive\"\n            trap - EXIT\n          fi\n          printf '%s  %s\\n' \"$expected\" \"$archive\" | sha256sum --check --strict\n          if [[ \"$(id -u)\" -eq 0 ]]; then\n            tar --directory /usr/local --strip-components=1 --no-overwrite-dir -xzf \"$archive\"\n          else\n            sudo tar --directory /usr/local --strip-components=1 --no-overwrite-dir -xzf \"$archive\"\n          fi\n          command -v mold >/dev/null\n          mold --version | grep -F \"$MOLD_VERSION\"\n",
        ActionPin::CacheRestore.reference(),
        curl_flags = crate::s2::runtime::CURL_DOWNLOAD_FLAGS,
    );
    if cache_save {
        let trusted = primitives::trusted_cache_save_expression(default_branch);
        let _ = writeln!(
            output,
            "      - name: Save mold {MOLD_VERSION} cache\n        if: ({trusted}) && steps.{mold_id}.outputs.cache-hit != 'true'\n        uses: {}\n        with:\n          path: ~/.cache/velnor/mold/{MOLD_VERSION}\n          key: velnor-mold-{MOLD_VERSION}-${{{{ runner.os }}}}-${{{{ runner.arch }}}}",
            ActionPin::CacheSave.reference()
        );
    }
    output
}

#[cfg(test)]
mod hosted_mold_setup_tests {
    use super::hosted_mold_setup;

    /// The mold download carries the canonical bounded-download flags:
    /// retries and time bounds travel together, never one without the other.
    #[test]
    fn mold_download_uses_the_canonical_bounded_flags() {
        let setup = hosted_mold_setup("main", true);
        assert!(
            setup.contains(crate::s2::runtime::CURL_DOWNLOAD_FLAGS),
            "mold must download with the canonical flags: {setup}"
        );
    }
}

/// Restore the shared `~/.cargo/bin` cache for hosted jobs that provision
/// policy and test tools through `taiki-e/install-action` instead of mise.
pub(crate) fn hosted_cargo_bin_toolchain_restore() -> String {
    format!(
        "      - name: Restore cargo bin toolchain\n        id: cargo-bin-toolchain\n        uses: {}\n        with:\n          path: ~/.cargo/bin\n          key: velnor-cargo-bin-v2-${{{{ runner.os }}}}-${{{{ runner.arch }}}}-${{{{ hashFiles('mise.lock', 'mise.toml') }}}}\n",
        ActionPin::CacheRestore.reference()
    )
}

/// After a cache hit, prove every requested cargo-bin tool is on PATH and
/// registers as a working cargo subcommand. Stale v1 cache entries and mise
/// shims can satisfy `command -v` without making `cargo deny` usable.
pub(crate) fn hosted_cargo_bin_toolchain_verify(tool_list: &str) -> String {
    format!(
        "      - name: Verify cargo bin tools\n        if: ${{{{ steps.cargo-bin-toolchain.outputs.cache-hit == 'true' }}}}\n        id: cargo-bin-verify\n        shell: bash\n        env:\n          CARGO_BIN_TOOLS: {tool_list}\n        run: |\n          set -euo pipefail\n          missing=0\n          IFS=',' read -ra tools <<< \"$CARGO_BIN_TOOLS\"\n          for tool in \"${{tools[@]}}\"; do\n            tool=\"${{tool#\"${{tool%%[![:space:]]*}}\"}}\"\n            tool=\"${{tool%\"${{tool##*[![:space:]]}}\"}}\"\n            [[ -z \"$tool\" ]] && continue\n            if ! command -v \"$tool\" >/dev/null; then\n              missing=1\n              break\n            fi\n            if ! \"$tool\" --version >/dev/null 2>&1; then\n              missing=1\n              break\n            fi\n            if [[ \"$tool\" == cargo-* ]]; then\n              subcommand=\"${{tool#cargo-}}\"\n              if ! cargo \"$subcommand\" --version >/dev/null 2>&1; then\n                missing=1\n                break\n              fi\n            fi\n          done\n          echo \"missing=$missing\" >> \"$GITHUB_OUTPUT\"\n"
    )
}

/// Persist `~/.cargo/bin` only after install so cached snapshots include the
/// requested tools, not just the workflow runtime added earlier in the job.
pub(crate) fn hosted_cargo_bin_toolchain_save(default_branch: &str) -> String {
    let trusted = primitives::trusted_cache_save_expression(default_branch);
    format!(
        "      - name: Save cargo bin toolchain\n        if: ({trusted}) && (steps.cargo-bin-toolchain.outputs.cache-hit != 'true' || steps.cargo-bin-verify.outputs.missing == 'true')\n        uses: {}\n        with:\n          path: ~/.cargo/bin\n          key: velnor-cargo-bin-v2-${{{{ runner.os }}}}-${{{{ runner.arch }}}}-${{{{ hashFiles('mise.lock', 'mise.toml') }}}}\n",
        ActionPin::CacheSave.reference()
    )
}

#[cfg(test)]
mod hosted_cargo_bin_toolchain_tests {
    use super::{
        hosted_cargo_bin_toolchain_restore, hosted_cargo_bin_toolchain_save,
        hosted_cargo_bin_toolchain_verify,
    };

    #[test]
    fn save_follows_install_and_repairs_stale_cache_hits() {
        let block = format!(
            "{}{}{}\n{}",
            hosted_cargo_bin_toolchain_restore(),
            hosted_cargo_bin_toolchain_verify("${{ inputs.cargo_bin_tools }}"),
            "      - name: Set up cargo bin tools\n",
            hosted_cargo_bin_toolchain_save("main"),
        );
        let positions = [
            "Restore cargo bin toolchain",
            "Verify cargo bin tools",
            "Set up cargo bin tools",
            "Save cargo bin toolchain",
        ]
        .map(|step| block.find(step));
        assert!(
            positions.iter().all(Option::is_some)
                && positions.windows(2).all(|pair| pair[0] < pair[1]),
            "restore, verify, install, save in that order: {block}"
        );
        assert!(block.contains("cargo-bin-verify.outputs.missing == 'true'"));
        assert!(block.contains("cargo \"$subcommand\" --version"));
        assert!(block.contains("velnor-cargo-bin-v2-"));
    }
}

pub(crate) fn rendered_cache_values(cache: &CacheSpec) -> (String, String) {
    let paths = cache
        .paths
        .iter()
        .map(|path| format!("            {path}"))
        .collect::<Vec<_>>()
        .join("\n");
    let key = cache
        .key_files
        .iter()
        .map(|path| format!("'{}'", path.replace('\'', "''")))
        .collect::<Vec<_>>()
        .join(", ");
    (paths, key)
}

/// Run the generator from the process argument vector.
///
/// # Errors
/// Reports parsing, clone, scanning, and write failures without replacing a
/// manually edited file unless explicit adoption was requested. Individual
/// generated files are replaced atomically.
pub fn run_from_env() -> Result<(), GeneratorError> {
    let arguments = env::args_os().skip(1).collect::<Vec<_>>();
    if runtime::try_run(&arguments)? {
        return Ok(());
    }
    let raw = match parse_raw_clap(arguments) {
        Ok(raw) => raw,
        Err(error)
            if matches!(
                error.kind(),
                clap::error::ErrorKind::DisplayHelp | clap::error::ErrorKind::DisplayVersion
            ) =>
        {
            print!("{error}");
            return Ok(());
        }
        Err(error) => return Err(clap_usage_error(&error)),
    };
    if raw.revision {
        println!("{SOURCE_REVISION}");
        return Ok(());
    }
    if raw.closure {
        println!("{SOURCE_CLOSURE}");
        return Ok(());
    }
    if raw.build_identity {
        println!("{SOURCE_BUILD_IDENTITY}");
        return Ok(());
    }
    let cli = raw.try_into()?;
    run(&cli)
}

/// Interactive dispatch: the TUI owns attached terminals unless `--plain`
/// forces the line-oriented report. Builds without the `tui` feature always
/// take the headless path.
fn use_tui(cli: &Cli) -> bool {
    if cli.plain {
        return false;
    }
    #[cfg(feature = "tui")]
    {
        io::stdin().is_terminal() && io::stdout().is_terminal()
    }
    #[cfg(not(feature = "tui"))]
    {
        false
    }
}

/// One in-memory render of a repository root: the resolved config, the
/// generated files, and the generation inputs the ownership state records.
/// The generator CLI and `promote` share this path, so a promoted tree is
/// byte-identical to a plain regeneration of the same stamped tree.
pub(crate) struct RenderedTree {
    pub(crate) config: ProjectConfig,
    pub(crate) files: BTreeMap<PathBuf, String>,
    pub(crate) symlinks: BTreeMap<PathBuf, PathBuf>,
    pub(crate) inputs: GenerationInputs,
}

pub(crate) fn render_tree(
    root: &Path,
    providers: Option<provider::ProviderSet>,
    default_branch: &str,
) -> Result<RenderedTree, GeneratorError> {
    let scanned = scan_target(root, providers, default_branch)?;
    if scanned.config.units.is_empty() && scanned.config.workflow_templates.is_empty() {
        return Err(GeneratorError::usage(
            "scanner found no supported manifest or project shape; add project.toml manually only after defining a safe command",
        ));
    }
    let mut config = scanned.config;
    let surface = primitives::generate(root, &scanned.shape, &config, scanned.generation.as_ref())?;
    config.units.clone_from(&surface.units);
    // A declared release-side family can add a workflow file the scan did not
    // own; declaring it is what makes it part of the owned surface.
    for file in &surface.added_files {
        if !config.workflow_files.contains(file) {
            config.workflow_files.push(file.clone());
        }
    }
    let files = generated_files_with_surface(&config, Some(&surface))?;
    let inputs = scanned.inputs;
    Ok(RenderedTree {
        config,
        files,
        symlinks: crate::generated_symlinks(),
        inputs,
    })
}

fn run(cli: &Cli) -> Result<(), GeneratorError> {
    run_with_policy_lookup(cli, None)
}

fn run_with_policy_lookup(
    cli: &Cli,
    policy_lookup: Option<&policy::PinnedBinaryLookup>,
) -> Result<(), GeneratorError> {
    #[cfg(feature = "tui")]
    if use_tui(cli) {
        return tui::run(cli);
    }
    #[cfg(not(feature = "tui"))]
    debug_assert!(
        !use_tui(cli),
        "builds without the `tui` feature always take the headless path"
    );
    let source = RepositorySource::parse(&cli.target)?;
    let checkout = source.checkout()?;
    let default_branch = match cli.default_branch.as_deref() {
        Some(branch) => validate_default_branch(branch)?.to_owned(),
        None => source.default_branch(checkout.path())?,
    };
    let output_root = match cli.output.as_deref() {
        Some(path) => resolve_output_path(path)?,
        None => source.output_root(checkout.path())?,
    };
    let rendered = render_tree(checkout.path(), cli.providers.clone(), &default_branch)?;
    let config = rendered.config;
    let files = rendered.files;
    let symlinks = rendered.symlinks;
    let inputs = rendered.inputs;
    if cli.check {
        // A candidate renderer may be under qualification while the checked-in
        // workflows remain owned by an earlier active renderer. Checking the
        // candidate's render here made that valid staged state impossible and
        // recreated the candidate-as-authority exception in a different
        // layer. The active tree is therefore checked only against its
        // declared active pin; candidate rendering is qualified separately
        // and can never authorize a checked-in tree.
        match policy_lookup {
            Some(lookup) => policy::verify_declared_pin_renders_tree_with_lookup(
                &output_root,
                checkout.path(),
                &config,
                lookup,
            )?,
            None => policy::verify_declared_pin_renders_tree(
                &output_root,
                checkout.path(),
                &config,
                cli.pin_build,
            )?,
        }
        print_report(
            &cli.target,
            &config,
            &files,
            &symlinks,
            &WriteOutcome::Unchanged,
            &output_root,
        );
        return Ok(());
    }
    let outcome = write_generated_with_options(
        &output_root,
        &files,
        &symlinks,
        &inputs,
        cli.dry_run,
        false,
        cli.force,
        cli.force && !cli.check,
    )?;
    print_report(
        &cli.target,
        &config,
        &files,
        &symlinks,
        &outcome,
        &output_root,
    );
    Ok(())
}

#[cfg(any(feature = "tui", test))]
fn generated_files(config: &ProjectConfig) -> Result<BTreeMap<PathBuf, String>, GeneratorError> {
    generated_files_with_surface(config, None)
}

/// The generated surface, with the workflow families the declared primitives
/// own taken from the rendered surface instead of the legacy renderer.
/// The runtime-product producer is owner-only infrastructure: the repository
/// that ships the setup action owns `ci-runtime-products.yml` without
/// declaring it, so the publisher can never fall out of the owner's surface
/// through a config edit. Consumers never carry the file; the renderer
/// refuses them, and an adopted surface keeps its reviewed templates.
fn add_owner_runtime_products_file(config: &mut ProjectConfig) {
    if !config.adopted_workflow_surface
        && config.repository == workflow_setup_action_repository()
        && !config
            .workflow_files
            .iter()
            .any(|file| file == primitives::runtime_products::RUNTIME_PRODUCTS_FILE)
    {
        config
            .workflow_files
            .push(primitives::runtime_products::RUNTIME_PRODUCTS_FILE.to_owned());
    }
}

#[expect(
    clippy::too_many_lines,
    reason = "surface assembly keeps every unconditional file emission inline"
)]
fn generated_files_with_surface(
    config: &ProjectConfig,
    surface: Option<&primitives::Surface>,
) -> Result<BTreeMap<PathBuf, String>, GeneratorError> {
    let mut config = config.clone();
    add_owner_runtime_products_file(&mut config);
    provider::require_selectors_for(&config.selectors, &config.providers)?;
    provider::validate_selector_disjointness(&config.selectors)?;
    let workflow = WorkflowIr::from_config(&config);
    primitives::validate_cache_transports(&workflow)?;
    // The toolchain contract is a generation precondition, checked here so no
    // rendering path — scanned or declared — can emit a Rust job without a
    // pin or a release matrix the pin does not declare.
    validate_workflow_revision(&config)?;
    validate_rust_units_are_pinned(&config)?;
    validate_toolchain_matrix_providers(&config)?;
    validate_release_targets_are_pinned(&config)?;
    validate_unit_provider_coverage(&config)?;
    let mut files = BTreeMap::new();
    files.insert(
        PathBuf::from(".github/actionlint.yaml"),
        render_actionlint_config(&config),
    );
    if !config.adopted_workflow_surface {
        for kind in config
            .units
            .iter()
            .map(|unit| unit.kind)
            .collect::<BTreeSet<_>>()
        {
            let Some((filename, content)) = workflow
                .render_kind_unit_workflow(kind, surface.map(|surface| &surface.contracts))?
            else {
                continue;
            };
            if content.len() > primitives::GITHUB_WORKFLOW_BYTE_LIMIT {
                return Err(GeneratorError::usage(format!(
                    "rendered `{filename}` is {} bytes, above GitHub's {}-byte workflow limit",
                    content.len(),
                    primitives::GITHUB_WORKFLOW_BYTE_LIMIT
                )));
            }
            files.insert(PathBuf::from(".github/workflows").join(filename), content);
        }
    }
    files.insert(PathBuf::from(".github/ci/project.toml"), config.toml());
    for workflow_file in &config.workflow_files {
        let path = PathBuf::from(".github/workflows").join(workflow_file);
        if let Some(content) = surface.and_then(|surface| surface.files.get(&path)) {
            files.insert(path, content.clone());
            continue;
        }
        let content = config
            .workflow_templates
            .get(workflow_file)
            .map(|template| render_static_template_for_config(&config, workflow_file, template))
            .transpose()?;
        let content = match content {
            Some(content) => Some(content),
            None if config.adopted_workflow_surface => None,
            None => match workflow_file.as_str() {
                "ci-pr.yml" | "ci-pull-request.yml" => Some(generated_ci_pr(&workflow)),
                "ci-policy.yml" => Some(generated_ci_policy(&config)?),
                "ci-release-package-signer.yml" => Some(generated_release_package_signer(&config)),
                "ci-main.yml" => Some(generated_ci_main(&workflow)),
                "nightly.yml" => Some(generated_nightly(&workflow)),
                "maintenance.yml" => Some(generated_maintenance(&config)),
                "preview.yml" => Some(generated_preview(&config)),
                "release.yml" => generated_release(&config),
                "renovate.yml" => primitives::renovate::renovate_content(&config)?,
                "renovate-validate.yml" => {
                    primitives::renovate::renovate_validate_content(&config)?
                }
                "docs.yml" => generated_docs_site(&config),
                "ci-runtime-products.yml" => generated_runtime_products(&config)?,
                _ => None,
            },
        };
        if let Some(content) = content {
            files.insert(path, content);
        }
    }
    for (name, template) in &config.workflow_templates {
        files.insert(
            PathBuf::from(WORKFLOW_TEMPLATE_DIR).join(name),
            render_static_template_for_config(&config, name, template)?,
        );
    }
    for (path, content) in builtin_generated_actions() {
        files.entry(path).or_insert(content);
    }
    for owned in &config.static_files {
        files.insert(PathBuf::from(&owned.path), owned.content.clone());
    }
    files.insert(
        PathBuf::from("config/fleet/velnor-host.env"),
        config::render_velnor_host_env(&config.velnor_host_cache),
    );
    // The agent-instruction file is unconditional: every render owns these
    // exact bytes, even for minimal repositories. A `static_files` row for a
    // generator-owned agent path can never take effect, so it fails closed
    // with a remediation instead of being silently overridden. The
    // reviewer-assignment file is generator-owned the same way even though
    // its emission is conditional: an unvalidated passthrough row must never
    // stand in for typed `[[reviewers]]` input.
    for reserved in [
        crate::GITHUB_AGENTS_MD,
        crate::GITHUB_CLAUDE_MD,
        crate::CODEOWNERS_PATH,
    ] {
        if config
            .static_files
            .iter()
            .any(|owned| Path::new(&owned.path) == Path::new(reserved))
        {
            return Err(GeneratorError::usage(format!(
                "remove the `[[static_files]]` row for `{reserved}`: the generator owns this path"
            )));
        }
    }
    files.insert(
        PathBuf::from(crate::GITHUB_AGENTS_MD),
        crate::GENERATED_GITHUB_AGENTS_MD.to_owned(),
    );
    // Reviewer assignment is opt-in: zero rows render no file, so
    // repositories without `[[reviewers]]` rows see no tree change.
    if !config.reviewers.is_empty() {
        let rules = config
            .reviewers
            .iter()
            .map(|rule| (rule.pattern.as_str(), rule.owners.as_slice()))
            .collect::<Vec<_>>();
        files.insert(
            PathBuf::from(crate::CODEOWNERS_PATH),
            crate::render_codeowners_contents(&rules),
        );
    }
    validate_ruleset_required_status_checks(&config, &files)?;
    validate_hosted_mr_boxington_store_budget(&files)?;
    validate_policy_jobs_check_out_full_history(&files)?;
    validate_workflow_runtime_install_roots(&files)?;
    validate_provider_admission_single_source(&files)?;
    // GitHub loads every reusable workflow once per calling job into one
    // 10 MiB template budget; refuse a surface whose expansion passes the
    // generator's 8 MiB ceiling before it can fail every run at startup.
    template_memory::validate_template_memory(&files)?;
    Ok(files)
}

