    #[test]
    fn cli_defaults_to_github_and_accepts_documented_target_forms() {
        let implicit = Cli::parse_args([]);
        assert!(matches!(
            implicit,
            Ok(Cli {
                target,
                plain: false,
                pin_build: false,
                ..
            }) if target == "."
        ));
        let pin_build = Cli::parse_args([
            OsString::from("--plain"),
            OsString::from("--check"),
            OsString::from("--pin-build"),
        ]);
        assert!(matches!(
            pin_build,
            Ok(Cli {
                check: true,
                pin_build: true,
                ..
            })
        ));
        let accepted_without_check = Cli::parse_args([OsString::from("--pin-build")]);
        assert!(matches!(
            accepted_without_check,
            Ok(Cli {
                check: false,
                pin_build: true,
                ..
            })
        ));
        let plain = Cli::parse_args([OsString::from("--plain")]);
        assert!(matches!(
            plain,
            Ok(Cli {
                target,
                plain: true,
                ..
            }) if target == "."
        ));
        let local = Cli::parse_args([OsString::from("generate"), OsString::from(".")]);
        assert!(matches!(
            local,
            Ok(Cli {
                providers: None,
                ..
            })
        ));
        let adopt = Cli::parse_args([OsString::from("--adopt"), OsString::from("--plain")]);
        assert!(
            adopt.is_err(),
            "--adopt is removed; foreign workflow bodies are never imported"
        );
        let remote = Cli::parse_args([
            OsString::from("example-org/example-repo"),
            OsString::from("--providers"),
            OsString::from("github-hosted,github-self-hosted,velnor"),
            OsString::from("--dry-run"),
        ]);
        let remote = must(remote, "parse explicit provider universe");
        assert_eq!(remote.providers, Some(all_providers()));
        assert!(remote.dry_run);
        let url = Cli::parse_args([
            OsString::from("generate"),
            OsString::from("https://github.com/example-org/example-repo"),
            OsString::from("--providers"),
            OsString::from("velnor"),
        ]);
        let url = must(url, "parse single provider override");
        assert_eq!(url.providers, Some(provider_set([ProviderId::Velnor])));
        let explicit_branch = Cli::parse_args([
            OsString::from("."),
            OsString::from("--default-branch"),
            OsString::from("trunk"),
        ]);
        assert!(matches!(
            explicit_branch,
            Ok(Cli {
                default_branch: Some(branch),
                ..
            }) if branch == "trunk"
        ));
    }

