    #[test]
    fn hosted_runtime_setup_uses_the_versioned_setup_action() {
        let config = must(
            scan_repository_with_default_branch(
                &fixture_root(),
                Some(provider_set([ProviderId::GithubHosted])),
                "main",
            ),
            "scan fixture for hosted runtime setup",
        );
        let workflow = generated_ci_main(&WorkflowIr::from_config(&config));
        let plan = yaml_job(&workflow, "plan");
        let uses_line = setup_action_uses_line(plan);
        assert!(
            uses_line.contains(&format!("@{FIXTURE_REVISION}")),
            "Planning uses the SOURCE_REV pin: {uses_line}"
        );
        assert!(
            !uses_line.contains("github.sha"),
            "GitHub Actions forbids expressions in uses: versions: {uses_line}"
        );
        assert!(
            plan.contains(&format!("rev: {FIXTURE_REVISION}")),
            "foreign repos install the published pin: {plan}"
        );
        assert!(
            !plan.contains(&format!("rev: {}", github_expression("github.sha"))),
            "foreign Planning must not cargo-install a foreign github.sha: {plan}"
        );
        assert!(
            !plan.contains(&format!(
                "uses: {VELNOR_WORKFLOW_SETUP_ACTION}@{}",
                github_expression("github.sha")
            )),
            "CI Planning must not resolve setup at HEAD: {plan}"
        );
        let mut home = config.clone();
        home.repository = workflow_setup_action_repository().to_owned();
        let home_workflow = generated_ci_main(&WorkflowIr::from_config(&home));
        let home_plan = yaml_job(&home_workflow, "plan");
        assert!(
            home_plan.contains(&format!("rev: {FIXTURE_REVISION}")),
            "the setup-action owner installs the declared pin, never an event SHA: {home_plan}"
        );
        assert!(
            !home_plan.contains(&format!("rev: {}", github_expression("github.sha"))),
            "owner Planning must not resolve the runtime at an event SHA: {home_plan}"
        );
        assert!(workflow.contains("name: Publish Velnor workflow runtime"));
        assert!(!workflow.contains("candidate_publish: true"));
        let kind = must_some(
            must(
                WorkflowIr::from_config(&config).render_kind_unit_workflow(UnitKind::Rust, None),
                "render rust kind reusable",
            ),
            "rust kind has members",
        )
        .1;
        assert!(kind.contains("name: Download Velnor workflow runtime"));
        assert!(kind.contains("name: Verify Velnor workflow runtime"));
        assert!(kind.contains(".run_id == $run_id"));
        assert!(kind.contains(".platform == $platform"));
        assert!(kind.contains("runtime digest mismatch"));
        assert!(kind.contains("name: velnor-workflow-runtime-"));
        assert!(kind.contains("${{ runner.os }}-${{ runner.arch }}"));
        assert!(kind.contains("manifest.json"));
        assert!(!kind.contains("cargo install --locked --git"));
    }

    #[test]
    fn premerge_generator_changes_bootstrap_from_published_base_runtime() {
        const PUBLISHED_BASE_REVISION: &str = "0dc79895ff1c5e88be7c3822c437e1c5b5282e12";
        let mut config = scanned_fixture(provider_set([ProviderId::GithubHosted]));
        config.repository = workflow_setup_action_repository().to_owned();
        config.workflow_revision = PUBLISHED_BASE_REVISION.to_owned();
        assert_ne!(
            SOURCE_REVISION, PUBLISHED_BASE_REVISION,
            "the test must model an unpublished generator revision"
        );

        let workflow = WorkflowIr::from_config(&config);
        let pull_request = generated_ci_pr(&workflow);
        assert!(
            pull_request.contains(&format!("rev: {PUBLISHED_BASE_REVISION}")),
            "PR planning must use the published base runtime: {pull_request}"
        );
        assert!(
            !pull_request.contains(SOURCE_REVISION),
            "PR planning must not bootstrap an unpublished generator revision: {pull_request}"
        );

        let policy = must(generated_ci_policy(&config), "render policy entrypoint");
        assert!(
            policy.contains(&format!("rev: {PUBLISHED_BASE_REVISION}")),
            "policy must use the published base runtime: {policy}"
        );
        assert!(
            policy.contains("Set up Velnor workflow runtime"),
            "policy must execute the published active runtime: {policy}"
        );
        assert!(
            !policy.contains(SOURCE_REVISION),
            "policy must not execute an unpublished candidate runtime: {policy}"
        );
        assert!(
            !policy.contains("Acquire candidate generator product")
                && !policy.contains("ci-pr.yml")
                && !policy.contains("candidate-manifest")
                && !policy.contains("gh run")
                && !policy.contains("sleep "),
            "policy must not discover or poll for a PR-produced candidate: {policy}"
        );
    }

    #[test]
    fn install_rev_is_always_the_declared_pin() {
        assert_eq!(
            workflow_setup_install_rev(workflow_setup_action_repository(), FIXTURE_REVISION),
            FIXTURE_REVISION,
            "the owner installs the declared pin: an event SHA (the synthetic merge commit on pull_request) can never name a trusted product"
        );
        assert_eq!(
            workflow_setup_install_rev("example/consumer", FIXTURE_REVISION),
            FIXTURE_REVISION,
            "a consumer installs the published pin"
        );
        let head_rev = github_expression("github.sha");
        let maintenance = workflow_runtime_setup_with_install_rev(
            ProviderId::GithubHosted,
            "example/consumer",
            FIXTURE_REVISION,
            FIXTURE_REVISION,
        );
        let uses_line = setup_action_uses_line(&maintenance);
        assert!(
            uses_line.contains(&format!("@{FIXTURE_REVISION}")),
            "a consumer's uses: is always SOURCE_REV: {uses_line}"
        );
        assert!(
            !uses_line.contains("github.sha"),
            "GitHub Actions forbids expressions in uses: versions: {uses_line}"
        );
        assert!(
            maintenance.contains(&format!("rev: {FIXTURE_REVISION}")),
            "maintenance installs the declared pin: {maintenance}"
        );
        let owner = workflow_runtime_setup_with_install_rev(
            ProviderId::GithubHosted,
            workflow_setup_action_repository(),
            FIXTURE_REVISION,
            FIXTURE_REVISION,
        );
        assert!(
            owner.contains(&format!("uses: {VELNOR_WORKFLOW_LOCAL_SETUP_ACTION}\n")),
            "the owner runs its own checkout of the action, never a self pin: {owner}"
        );
        assert!(
            !owner.contains(VELNOR_WORKFLOW_SETUP_ACTION),
            "the owner must not reference itself by remote path: {owner}"
        );
        let config = must(
            scan_repository_with_default_branch(
                &fixture_root(),
                Some(provider_set([ProviderId::GithubHosted])),
                "main",
            ),
            "scan fixture for Planning install",
        );
        let workflow = generated_ci_main(&WorkflowIr::from_config(&config));
        let planning = yaml_job(&workflow, "plan");
        assert!(
            planning.contains(&format!(
                "uses: {VELNOR_WORKFLOW_SETUP_ACTION}@{FIXTURE_REVISION}"
            )),
            "Planning must pin setup to SOURCE_REV: {planning}"
        );
        assert!(
            planning.contains(&format!("rev: {FIXTURE_REVISION}")),
            "foreign Planning installs the published pin: {planning}"
        );
        assert!(
            !planning.contains(&format!("uses: {VELNOR_WORKFLOW_SETUP_ACTION}@{head_rev}")),
            "Planning must not resolve setup at HEAD: {planning}"
        );
        assert!(
            !planning.contains(&format!("rev: {head_rev}")),
            "foreign Planning must not install a foreign github.sha: {planning}"
        );
        let mut home = config.clone();
        home.repository = workflow_setup_action_repository().to_owned();
        let home_workflow = generated_ci_main(&WorkflowIr::from_config(&home));
        let home_plan = yaml_job(&home_workflow, "plan");
        assert!(
            home_plan.contains(&format!("rev: {FIXTURE_REVISION}")),
            "the setup-action owner installs the declared pin: {home_plan}"
        );
        assert!(
            !home_plan.contains(&format!("rev: {head_rev}")),
            "owner Planning must not install an event SHA: {home_plan}"
        );
    }

