    #[test]
    fn scanner_extracts_package_json_manager_scripts_and_package_dependencies() {
        let root = temporary_repository("package-json-analysis");
        let app = root.join("packages/app");
        must(fs::create_dir_all(&app), "create package workspace");
        must(
            fs::write(
                root.join("package.json"),
                r#"{"name":"web","packageManager":"bun@1.3.14","workspaces":["packages/*"],"scripts":{"typecheck":"tsc --noEmit","build":"vite build"}}"#,
            ),
            "write package root",
        );
        must(
            fs::write(root.join("bun.lock"), "lockfileVersion = 1\n"),
            "write bun lockfile",
        );
        must(
            fs::write(
                app.join("package.json"),
                r#"{"name":"@scope/app","scripts":{"lint":"eslint .","test":"bun test"},"dependencies":{"web":"workspace:*"}}"#,
            ),
            "write app package",
        );
        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan package workspace",
        );
        let root_unit = must_some(
            config.units.iter().find(|unit| unit.id == "bun-web"),
            "root bun unit",
        );
        let app_unit = must_some(
            config.units.iter().find(|unit| unit.id == "bun-scope-app"),
            "app bun unit",
        );
        assert_eq!(app_unit.tool_version.as_deref(), Some("1.3.14"));
        assert!(root_unit
            .pr_commands
            .iter()
            .any(|command| command == "bun install --frozen-lockfile"));
        assert!(root_unit
            .pr_commands
            .iter()
            .any(|command| command == "bun run typecheck"));
        assert!(!root_unit
            .pr_commands
            .iter()
            .any(|command| command.contains("bun test")));
        assert!(app_unit
            .pr_commands
            .iter()
            .any(|command| command == "cd -- 'packages/app' && bun run test"));
        assert!(app_unit.depends_on.contains(&"bun-web".to_owned()));
        assert!(config
            .analysis
            .detected
            .contains(&"package-manager:bun:.".to_owned()));
        let _ = fs::remove_dir_all(root);
    }

