    #[expect(
        clippy::too_many_lines,
        reason = "the workspace fixture keeps all evidence assertions together"
    )]
    #[test]
    fn scanner_analyzes_rust_workspace_packages_and_local_dependencies() {
        let root = temporary_repository("rust-workspace-analysis");
        let core = root.join("crates/core");
        let app = root.join("crates/app");
        must(fs::create_dir_all(core.join("src")), "create core source");
        must(fs::create_dir_all(app.join("src")), "create app source");
        must(
            fs::create_dir_all(root.join(".config")),
            "create nextest config",
        );
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[workspace]\nmembers = [\n  \"crates/core\",\n  \"crates/app\",\n]\n[workspace.dependencies]\ncore = { path = \"crates/core\" }\n",
            ),
            "write workspace manifest",
        );
        must(
            fs::write(
                core.join("Cargo.toml"),
                "[package]\nname = \"core\"\nversion = \"0.1.0\"\nbuild = \"build.rs\"\n[features]\nrelease-build = []\n",
            ),
            "write core manifest",
        );
        must(
            fs::write(
                app.join("Cargo.toml"),
                "[package]\nname = \"app\"\nversion = \"0.1.0\"\n[dependencies]\ncore.workspace = true\ncore-alias = { package = \"core\", path = \"../core\" }\n[[bin]]\nname = \"app-cli\"\n[[test]]\nname = \"integration\"\n",
            ),
            "write app manifest",
        );
        must(
            fs::write(core.join("build.rs"), "fn main() {}\n"),
            "write build script",
        );
        must(
            fs::write(core.join("src/lib.rs"), "pub fn value() {}\n"),
            "write core source",
        );
        must(
            fs::write(app.join("src/main.rs"), "fn main() {}\n"),
            "write app source",
        );
        must(
            fs::write(
                root.join(".config/nextest.toml"),
                "[profile.ci]\nfail-fast = false\n",
            ),
            "write nextest config",
        );
        must(
            fs::write(root.join("deny.toml"), "[advisories]\n"),
            "write deny config",
        );

        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan Rust workspace",
        );
        let rust_units = config
            .units
            .iter()
            .filter(|unit| unit.kind == UnitKind::Rust)
            .collect::<Vec<_>>();
        assert_eq!(rust_units.len(), 3);
        let core_unit = must_some(
            rust_units.iter().find(|unit| unit.id == "rust-core"),
            "core unit",
        );
        let app_unit = must_some(
            rust_units.iter().find(|unit| unit.id == "rust-app"),
            "app unit",
        );
        assert_eq!(app_unit.depends_on, vec!["rust-core"]);
        assert!(core_unit.watch.contains(&"crates/core/build.rs".to_owned()));
        assert!(app_unit
            .pr_commands
            .iter()
            .any(|command| command.contains("mbx nextest run") && command.contains("app")));
        assert!(app_unit
            .pr_commands
            .iter()
            .any(|command| command.contains("mbx nextest run") && !command.contains("--locked")));
        let files = must(generated_files(&config), "generate the workspace surface");
        let reusable = must_some(
            files.get(&PathBuf::from(".github/workflows/ci-unit-rust.yml")),
            "rust kind reusable",
        );
        assert!(reusable.contains("name: Set up cargo bin tools"));
        assert!(
            reusable.contains("tool: ${{ inputs.cargo_bin_tools }}"),
            "{reusable}"
        );
        // The callers pass the scanned tool set through the input.
        let caller = must_some(
            files.get(&PathBuf::from(".github/workflows/ci-pr.yml")),
            "ci-pr.yml",
        );
        assert!(
            caller.contains("cargo-nextest") && caller.contains("cargo-deny"),
            "callers must pass the scanned cargo bin tools: {caller}"
        );
        let policy_unit = must_some(
            rust_units.iter().find(|unit| unit.id == "rust-policy"),
            "Rust policy unit",
        );
        assert!(policy_unit
            .pr_commands
            .iter()
            .any(|command| command == "mbx deny check advisories bans sources"));
        assert!(config
            .analysis
            .detected
            .contains(&"rust-workspace-members:2".to_owned()));
        assert!(config
            .analysis
            .limitations
            .iter()
            .any(|note| note.contains("build scripts")));

        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn scanner_requires_a_pinned_toolchain_and_provisions_exactly_it() {
        let root = temporary_repository("mise-ci-quality");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\n",
            ),
            "write manifest",
        );
        must(
            fs::write(
                root.join("mise.toml"),
                "[tasks.check]\ndepends = [\"test\"]\n[tasks.ci]\ndepends = [\"lint\"]\n",
            ),
            "write Mise configuration",
        );

        // A Rust repository without a pin has no toolchain contract to
        // render, so the scan refuses it instead of letting a workflow step
        // resolve whatever toolchain it happens to find.
        must(
            fs::remove_file(root.join("rust-toolchain.toml")),
            "drop the pin the shared repository helper writes",
        );
        let unpinned = scan_repository(
            &root,
            Some(std::collections::BTreeSet::from([
                crate::s2::provider::ProviderId::GithubHosted,
            ])),
        );
        let error = must_some(
            unpinned.err(),
            "an unpinned Rust repository must fail the scan",
        );
        assert!(
            error.to_string().contains("pins no Rust toolchain"),
            "the error must name the missing pin: {error}"
        );

        // A repository pin is the only toolchain source: rustup provisions
        // exactly the pinned channel with its components and targets, and
        // mise is never asked for rust at all.
        must(
            fs::write(
                root.join("rust-toolchain.toml"),
                "[toolchain]\nchannel = \"1.91.1\"\nprofile = \"minimal\"\ncomponents = [\"clippy\"]\ntargets = [\"x86_64-unknown-linux-musl\"]\n",
            ),
            "write pinned toolchain",
        );
        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "rescan pinned workspace",
        );
        // The Rust kind reusable carries the toolchain steps for every
        // provider lane, so the whole toolchain contract is visible in one
        // shipped body.
        let files = must(generated_files(&config), "generate the pinned surface");
        let workflow = must_some(
            files.get(&PathBuf::from(".github/workflows/ci-unit-rust.yml")),
            "rust kind reusable",
        );
        assert!(
            config
                .units
                .iter()
                .filter(|unit| unit.kind == UnitKind::Rust)
                .all(|unit| unit.toolchain
                    == Some(RustToolchain {
                        channel: "1.91.1".to_owned(),
                        components: vec!["clippy".to_owned()],
                        targets: vec!["x86_64-unknown-linux-musl".to_owned()],
                        profile: Some("minimal".to_owned()),
                    })),
            "every Rust unit must carry the parsed toolchain fact"
        );
        assert!(workflow.contains("name: Restore Rust toolchain"));
        assert!(workflow.contains("id: rustup-toolchain"));
        assert!(workflow.contains("name: Provision Rust toolchain"));
        assert!(workflow.contains("rustup toolchain install --profile minimal"));
        assert!(workflow.contains("rustup target add 'x86_64-unknown-linux-musl'"));
        assert!(workflow.contains("key: velnor-rustup-${{ runner.os }}-${{ runner.arch }}-${{ hashFiles('rust-toolchain.toml', 'rust-toolchain') }}"));
        // No unit commands run nextest and none hand work to the mise task
        // runner, so the pinned unit installs nothing through mise.
        assert!(!workflow.contains("name: Set up Mise"));
        // The toolchain entry is saved from trusted events only, keyed by the
        // pin, and only when the restore was not an exact hit.
        let save = must_some(
            workflow.find("      - name: Save Rust toolchain"),
            "Save Rust toolchain step",
        );
        let save_body = &workflow[save..];
        assert!(save_body.contains("if: ((github.event_name == 'push' && github.ref == 'refs/heads/main') || github.event_name == 'schedule' || (github.event_name == 'workflow_dispatch' && github.ref == 'refs/heads/main')) && steps.rustup-toolchain.outputs.cache-hit != 'true'"));
        assert!(save_body.contains("path: |\n            ~/.rustup"));

        let _ = fs::remove_dir_all(root);
    }

    /// A repo-declared unit may pin its commands per lane only, so the mise
    /// decision must read the declared commands on every lane — a step is
    /// rendered for a unit whose override invokes `mise run` and for a unit
    /// whose scan-derived commands do, and for no unit otherwise.
