    #[test]
    fn scanned_nextest_commands_tolerate_test_less_crates() {
        let root = nextest_fixture_repository("nextest-no-tests");
        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan nextest workspace",
        );
        let rust = must_some(
            config.units.iter().find(|unit| unit.kind == UnitKind::Rust),
            "Rust unit",
        );
        assert!(
            rust.pr_commands
                .iter()
                .any(|command| command.contains("nextest run")
                    && command.contains("--no-tests pass")),
            "nextest must pass the empty collection: {}",
            rust.pr_commands.join(" | ")
        );
        let nextest_index = must_some(
            rust.pr_commands
                .iter()
                .position(|command| command.contains(" nextest ")),
            "nextest command",
        );
        let clippy_index = must_some(
            rust.pr_commands
                .iter()
                .position(|command| command.contains(" clippy ")),
            "clippy command",
        );
        assert!(
            clippy_index < nextest_index,
            "clippy must report lint failures before nextest runs: {}",
            rust.pr_commands.join(" | ")
        );
        assert!(
            rust.pr_commands[clippy_index].contains("--profile test"),
            "clippy must use the test profile to match nextest: {}",
            rust.pr_commands[clippy_index]
        );
        // The phase activation tags scan units: the order contract holds
        // on the commands and the phase list mirrors them. The fixture
        // ships no lib target, so no doctest phase follows the tests.
        assert_eq!(
            rust.phases,
            vec![
                ValidationPhase::Fmt,
                ValidationPhase::Clippy,
                ValidationPhase::Test,
            ],
            "scan units carry phase tags: {}",
            rust.pr_commands.join(" | ")
        );
        assert_eq!(
            rust.check_commands.len(),
            1,
            "scan units carry one prerequisite check: {:?}",
            rust.check_commands
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn validate_unit_phases_rejects_misaligned_and_check_shapes() {
        let phased_unit = || Unit {
            xcode: None,
            id: "rust-app".to_owned(),
            label: "rust-app".to_owned(),
            kind: UnitKind::Rust,
            root: ".".to_owned(),
            watch: vec!["crates/app/**".to_owned()],
            pr_commands: vec!["fmt".to_owned(), "clippy".to_owned(), "test".to_owned()],
            full_commands: vec!["fmt".to_owned(), "clippy".to_owned(), "test".to_owned()],
            phases: vec![
                ValidationPhase::Fmt,
                ValidationPhase::Clippy,
                ValidationPhase::Test,
            ],
            check_commands: vec!["check".to_owned()],
            depends_on: Vec::new(),
            pinned_lockfile: true,
            cache: None,
            tool_version: None,
            mise_tools: Vec::new(),
            toolchain: None,
            services: Vec::new(),
            trust: provider::TrustReq::UntrustedOk,
            capabilities: provider::Capabilities::default(),
            workspace_check: false,
            reads_closed: false,
            full_history: false,
            platform: provider::Platform::LinuxX64,
            products: Vec::new(),
            prerequisites: Vec::new(),
            docker_contexts: Vec::new(),
            env: std::collections::BTreeMap::new(),
            mbx: None,
            prepared_tools: Vec::new(),
        };
        let validate = |unit: Unit| {
            validate_unit_phases(&ProjectConfig {
                units: vec![unit],
                ..header_fixture_config()
            })
        };
        must(validate(phased_unit()), "aligned phases validate");
        let mut skewed = phased_unit();
        skewed.full_commands.push("extra".to_owned());
        let error = must_fail(validate(skewed), "misaligned tags");
        assert!(
            error.to_string().contains("must tag every command"),
            "tag/command misalignment fails closed: {error}"
        );
        let mut checkless = phased_unit();
        checkless.check_commands.clear();
        let error = must_fail(validate(checkless), "phases without a check");
        assert!(
            error
                .to_string()
                .contains("without prerequisite check commands"),
            "phases without a stored check fail closed: {error}"
        );
        let mut tagless = phased_unit();
        tagless.phases.clear();
        let error = must_fail(validate(tagless), "a check without phases");
        assert!(
            error.to_string().contains("without validation phases"),
            "a stored check without phases fails closed: {error}"
        );
    }

    #[test]
    fn runtime_rejects_unknown_phases_without_a_scan_fixture() {
        // Hand-written TOML, no scan: the scan emits no phases until the
        // activation lands, but the runtime already parses them strictly.
        let root = temporary_repository("unknown-phase");
        let project = root.join("project.toml");
        must(
            fs::write(
                &project,
                "schema = 3\nrepository = \"example/phases\"\nprofile = \"generic\"\nverified = true\ndefault_branch = \"main\"\nproviders = [\"github-hosted\", \"github-self-hosted\", \"velnor\"]\nautomatic_providers = [\"github-hosted\", \"github-self-hosted\", \"velnor\"]\ndefault_dispatch_providers = [\"github-hosted\", \"github-self-hosted\", \"velnor\"]\n\n[workflow]\nversion_bump_units = []\n\n[[unit]]\nid = \"rust-app\"\nplatform = \"linux-x64\"\ntrust = \"untrusted-ok\"\nkind = \"rust\"\nroot = \".\"\nwatch = [\"crates/app/**\"]\npr_commands = [\"cargo fmt --check\"]\nfull_commands = [\"cargo fmt --check\"]\nphases = [\"fmt\", \"fuzz\"]\ncheck_commands = [\"cargo check --locked\"]\n",
            ),
            "write bad project.toml",
        );
        let error = must_fail(
            runtime::read_config_for_test(&project),
            "an unknown phase must fail the pinned runtime",
        );
        assert!(
            error.to_string().contains("fuzz"),
            "the failure names the unknown phase: {error}"
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn scan_skips_unresolvable_crates_but_keeps_detached_ones() {
        let root = temporary_repository("workspace-membership");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[workspace]\nmembers = [\"crates/member\"]\nexclude = [\"crates/legacy\"]\n",
            ),
            "write workspace manifest",
        );
        for package in [
            "crates/member",
            "crates/legacy",
            "vendor/orphan",
            "tools/detached",
        ] {
            must(
                fs::create_dir_all(root.join(package).join("src")),
                "create package sources",
            );
        }
        must(
            fs::write(
                root.join("crates/member/Cargo.toml"),
                "[package]\nname = \"member\"\nversion = \"0.1.0\"\n",
            ),
            "write member manifest",
        );
        must(
            fs::write(
                root.join("crates/legacy/Cargo.toml"),
                "[package]\nname = \"legacy\"\nversion = \"0.1.0\"\n",
            ),
            "write excluded manifest",
        );
        must(
            fs::write(
                root.join("vendor/orphan/Cargo.toml"),
                "[package]\nname = \"orphan\"\nversion = \"0.1.0\"\n",
            ),
            "write orphan manifest",
        );
        must(
            fs::write(
                root.join("tools/detached/Cargo.toml"),
                "[package]\nname = \"detached\"\nversion = \"0.1.0\"\n\n[workspace]\n",
            ),
            "write detached manifest",
        );
        must(
            fs::write(
                root.join("rust-toolchain.toml"),
                "[toolchain]\nchannel = \"stable\"\n",
            ),
            "write pinned toolchain",
        );
        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan mixed workspace",
        );
        let ids = config
            .units
            .iter()
            .map(|unit| unit.id.as_str())
            .collect::<Vec<_>>();
        assert!(
            ids.iter().any(|id| id.contains("member")),
            "members verify: {ids:?}"
        );
        assert!(
            ids.iter().any(|id| id.contains("detached")),
            "self-governing crates resolve from their own directory: {ids:?}"
        );
        assert!(
            ids.iter().all(|id| !id.contains("legacy")),
            "excluded crates are out of the contract: {ids:?}"
        );
        assert!(
            ids.iter().all(|id| !id.contains("orphan")),
            "orphans no workspace claims resolve nowhere: {ids:?}"
        );
        let _ = fs::remove_dir_all(root);
    }

