    fn report_action_script() -> String {
        let action = report_velnor_ci_outcomes_action_template();
        let body = must_some(
            action.split_once("      run: |\n").map(|(_, body)| body),
            "locate report action run body",
        );
        body.lines()
            .map(|line| line.strip_prefix("        ").unwrap_or(line))
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn jq_timestamp(epoch: u64) -> String {
        let epoch = epoch.to_string();
        let output = must(
            Command::new("jq")
                .args([
                    "-nr",
                    "--argjson",
                    "epoch",
                    epoch.as_str(),
                    "$epoch | todateiso8601",
                ])
                .output(),
            "format telemetry test timestamp",
        );
        assert!(
            output.status.success(),
            "jq timestamp formatting failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        String::from_utf8_lossy(&output.stdout).trim().to_owned()
    }

    fn run_report_action_case(
        name: &str,
        markers: &[(&str, &str)],
        run_started_at: Option<&str>,
        queue_time: Option<&str>,
    ) -> serde_json::Value {
        run_report_action_case_with_env(name, markers, run_started_at, queue_time, &[])
    }

    fn run_report_action_case_with_env(
        name: &str,
        markers: &[(&str, &str)],
        run_started_at: Option<&str>,
        queue_time: Option<&str>,
        env_markers: &[(&str, &str)],
    ) -> serde_json::Value {
        run_report_action_case_with_env_and_log(
            name,
            markers,
            run_started_at,
            queue_time,
            env_markers,
            None,
        )
    }

    fn run_report_action_case_with_env_and_log(
        name: &str,
        markers: &[(&str, &str)],
        run_started_at: Option<&str>,
        queue_time: Option<&str>,
        env_markers: &[(&str, &str)],
        log: Option<&str>,
    ) -> serde_json::Value {
        let root = temporary_directory(&format!("telemetry-{name}"));
        let timing_dir = root.join("velnor-ci-timing-42-1-telemetry");
        must(
            fs::create_dir_all(&timing_dir),
            "create telemetry timing directory",
        );
        for (marker, value) in markers {
            must(
                fs::write(timing_dir.join(marker), format!("{value}\n")),
                "write telemetry marker",
            );
        }
        let script = root.join("report.sh");
        must(
            fs::write(&script, report_action_script()),
            "write report action test script",
        );
        if let Some(log) = log {
            must(
                fs::write(root.join("velnor-unit-log.txt"), log),
                "write report action log fixture",
            );
        }
        let summary = root.join("summary.md");
        let mut command = Command::new("bash");
        command
            .arg(&script)
            .env("RUNNER_TEMP", &root)
            .env("GITHUB_RUN_ID", "42")
            .env("GITHUB_RUN_ATTEMPT", "1")
            .env("GITHUB_JOB", "telemetry")
            .env("GITHUB_STEP_SUMMARY", &summary)
            .env(
                "VELNOR_CONTEXT_RUN_STARTED_AT",
                run_started_at.unwrap_or(""),
            )
            .env("VELNOR_JOB_QUEUED_AT", queue_time.unwrap_or(""));
        for (key, value) in env_markers {
            command.env(key, value);
        }
        let output = must(command.output(), "run report action test script");
        assert!(
            output.status.success(),
            "report action failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        let stdout = String::from_utf8_lossy(&output.stdout);
        let report = must_some(
            stdout
                .lines()
                .find_map(|line| line.strip_prefix("VELNOR_CI_REPORT ")),
            "locate report telemetry line",
        );
        let report = must(serde_json::from_str(report), "parse report telemetry JSON");
        must(fs::remove_dir_all(&root), "remove telemetry test directory");
        report
    }

    #[test]
    fn report_action_prefers_fractional_queue_time_and_bounds_markers() {
        let now = must(
            SystemTime::now().duration_since(UNIX_EPOCH),
            "read telemetry test clock",
        )
        .as_secs();
        let job_started = now.saturating_sub(30);
        let checks_started = now.saturating_sub(25);
        let checks_ended = now.saturating_sub(10);
        let queue_time = jq_timestamp(now.saturating_sub(40));
        let queue_time = format!(
            "{}.123Z",
            must_some(queue_time.strip_suffix('Z'), "strip queue Z")
        );
        let hosted_run_started = jq_timestamp(now.saturating_sub(100));
        let report = run_report_action_case(
            "valid-fractional-queue",
            &[
                ("JOB_STARTED", &job_started.to_string()),
                ("CHECKS_STARTED", &checks_started.to_string()),
                ("CHECKS_ENDED", &checks_ended.to_string()),
            ],
            Some(&hosted_run_started),
            Some(&queue_time),
        );
        assert_eq!(report["queue_source"], serde_json::json!("job_queue_time"));
        let queue_seconds = must_some(report["queue_seconds"].as_u64(), "fractional queue seconds");
        assert!((10..30).contains(&queue_seconds));
        assert_eq!(report["total_source"], serde_json::json!("job_markers"));
        assert!(report["total_seconds"].as_u64().is_some());
        assert!(report["checks_wall_seconds"].as_u64().is_some());

        let hosted_fallback = run_report_action_case(
            "hosted-queue-fallback",
            &[("JOB_STARTED", &job_started.to_string())],
            Some(&hosted_run_started),
            Some(" "),
        );
        assert_eq!(
            hosted_fallback["queue_source"],
            serde_json::json!("workflow_run_started_at")
        );

        let invalid = run_report_action_case("invalid-start", &[("JOB_STARTED", "0")], None, None);
        assert!(invalid["total_seconds"].is_null());
        assert!(invalid["runner_setup_seconds"].is_null());

        let future_started = (now + 120).to_string();
        let future = run_report_action_case(
            "future-markers",
            &[
                ("JOB_STARTED", &future_started),
                ("CHECKS_STARTED", &(now + 121).to_string()),
                ("CHECKS_ENDED", &(now + 122).to_string()),
            ],
            None,
            None,
        );
        assert!(future["total_seconds"].is_null());
        assert!(future["checks_wall_seconds"].is_null());

        let stale_started = now.saturating_sub(8 * 24 * 60 * 60);
        let stale = run_report_action_case(
            "stale-markers",
            &[
                ("JOB_STARTED", &stale_started.to_string()),
                ("CHECKS_STARTED", &(stale_started + 1).to_string()),
                ("CHECKS_ENDED", &(stale_started + 2).to_string()),
            ],
            None,
            None,
        );
        assert!(stale["total_seconds"].is_null());
        assert!(stale["checks_wall_seconds"].is_null());

        let ordering = run_report_action_case(
            "reversed-phase",
            &[
                ("JOB_STARTED", &job_started.to_string()),
                ("CHECKS_STARTED", &(now - 5).to_string()),
                ("CHECKS_ENDED", &(now - 6).to_string()),
            ],
            None,
            None,
        );
        assert!(ordering["checks_wall_seconds"].is_null());

        let spoof_start = (now - 20).to_string();
        let spoof_checks_started = (now - 15).to_string();
        let spoof_checks_ended = (now - 5).to_string();
        let env_override = run_report_action_case_with_env(
            "legacy-env-markers-ignored",
            &[],
            None,
            None,
            &[
                ("VELNOR_JOB_STARTED_EPOCH", &spoof_start),
                ("VELNOR_CHECKS_STARTED_EPOCH", &spoof_checks_started),
                ("VELNOR_CHECKS_ENDED_EPOCH", &spoof_checks_ended),
            ],
        );
        assert!(env_override["total_seconds"].is_null());
        assert!(env_override["checks_wall_seconds"].is_null());
    }

    fn assert_cache_outcomes(name: &str, env_markers: &[(&str, &str)], expected: &[(&str, &str)]) {
        let report = run_report_action_case_with_env(name, &[], None, None, env_markers);
        for &(layer, outcome) in expected {
            assert_eq!(
                report["cache_outcomes"][layer],
                serde_json::json!(outcome),
                "{name}: {layer}"
            );
        }
    }

    fn assert_github_cache_outcomes() {
        assert_cache_outcomes(
            "github-cache-outcomes",
            &[
                ("VELNOR_CI_LANE", "github"),
                (
                    "VELNOR_CACHE_DECLARED_LAYERS",
                    "rustup,mold,cargo,mbx,docker_seed",
                ),
                ("VELNOR_CACHE_RUSTUP_OUTCOME", "success"),
                ("VELNOR_CACHE_RUSTUP_PRIMARY", "velnor-rustup-Linux-X64-abc"),
                ("VELNOR_CACHE_RUSTUP_MATCHED", "velnor-rustup-Linux-X64-abc"),
                ("VELNOR_CACHE_MOLD_OUTCOME", "success"),
                ("VELNOR_CACHE_MOLD_PRIMARY", "velnor-mold-2.42.0-Linux-X64"),
                ("VELNOR_CACHE_MOLD_MATCHED", "velnor-mold-2.42.0-Linux"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "success"),
                ("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef"),
                ("VELNOR_CACHE_CARGO_MATCHED", ""),
                ("VELNOR_CACHE_MBX_OUTCOME", "success"),
                ("VELNOR_CACHE_MBX_HIT", "false"),
                ("VELNOR_CACHE_DOCKER_SEED_OUTCOME", "skipped"),
            ],
            &[
                ("rustup", "exact"),
                ("mold", "compatible_seed"),
                ("cargo", "miss"),
                ("mbx", "unknown"),
                ("docker_seed", "not_run"),
            ],
        );
        assert_cache_outcomes(
            "github-matched-without-primary",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_MATCHED", "matched-only"),
            ],
            &[("cargo", "unknown")],
        );
    }

    fn assert_cache_lifecycle_outcomes() {
        assert_cache_outcomes(
            "all-layers-disabled",
            &[("VELNOR_CI_LANE", "github")],
            &[
                ("rustup", "disabled"),
                ("mold", "disabled"),
                ("cargo", "disabled"),
                ("mbx", "disabled"),
                ("docker_seed", "disabled"),
            ],
        );
        assert_cache_outcomes(
            "partial-declaration-disables-the-rest",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "success"),
                ("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef"),
                ("VELNOR_CACHE_CARGO_MATCHED", "ci-Linux-rust-deadbeef"),
            ],
            &[
                ("rustup", "disabled"),
                ("mold", "disabled"),
                ("cargo", "exact"),
                ("mbx", "disabled"),
                ("docker_seed", "disabled"),
            ],
        );
        assert_cache_outcomes(
            "failed-restore-never-completed",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "failure"),
            ],
            &[("cargo", "not_run")],
        );
        assert_cache_outcomes(
            "miss-that-saved-populates-later-runs",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "success"),
                ("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef"),
                ("VELNOR_CACHE_CARGO_SAVED", "true"),
            ],
            &[("cargo", "saved")],
        );
        assert_cache_outcomes(
            "match-wins-over-save-evidence",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "success"),
                ("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef"),
                ("VELNOR_CACHE_CARGO_MATCHED", "ci-Linux-rust-deadbeef"),
                ("VELNOR_CACHE_CARGO_SAVED", "true"),
            ],
            &[("cargo", "exact")],
        );
        assert_cache_outcomes(
            "failed-verification-invalidates-restore",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "success"),
                ("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef"),
                ("VELNOR_CACHE_CARGO_MATCHED", "ci-Linux-rust-deadbeef"),
                ("VELNOR_CACHE_CARGO_VERIFIED", "false"),
            ],
            &[("cargo", "invalid")],
        );
        assert_cache_outcomes(
            "keys-on-undeclared-layer-contradict-plan",
            &[("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef")],
            &[("cargo", "unknown")],
        );
        assert_cache_outcomes(
            "keys-on-skipped-step-contradict-outcome",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "skipped"),
                ("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef"),
            ],
            &[("cargo", "unknown")],
        );
        assert_cache_outcomes(
            "corrupt-step-outcome-stays-unknown",
            &[
                ("VELNOR_CACHE_DECLARED_LAYERS", "cargo"),
                ("VELNOR_CACHE_CARGO_OUTCOME", "stuck"),
                ("VELNOR_CACHE_CARGO_PRIMARY", "ci-Linux-rust-deadbeef"),
            ],
            &[("cargo", "unknown")],
        );
    }

