        assert_github_cache_outcomes();
        assert_cache_lifecycle_outcomes();
        assert_mbx_key_cache_outcomes();
        assert_mbx_boolean_cache_outcomes();
        assert_compiler_log_does_not_classify_mbx();
        assert_velnor_cache_declarations();
