    #[test]
    fn mbx_command_rewrite_routes_all_supported_cargo_commands() {
        assert_eq!(mbxify_cargo_command("cargo fmt --all"), "mbx fmt --all");
        assert_eq!(
            mbxify_cargo_command("cargo clippy --locked --no-deps --all-targets"),
            "mbx clippy --locked --all-targets"
        );
        assert_eq!(
            mbxify_cargo_command("cargo clippy --no-deps && cargo check --no-deps"),
            "mbx clippy && mbx check"
        );
        assert_eq!(
            mbxify_cargo_command("cargo zigbuild -p velnor-runner"),
            "mbx zigbuild -p velnor-runner"
        );
        assert_eq!(
            mbxify_cargo_command("MBX_CC=0 cargo zigbuild -p velnor-runner"),
            "MBX_CC=0 mbx zigbuild -p velnor-runner"
        );
        assert_eq!(
            mbxify_cargo_command("MBX_CC=0 cargo zigbuild -p alpha"),
            "MBX_CC=0 mbx zigbuild -p alpha"
        );
        assert_eq!(
            mbxify_cargo_command("cd -- 'crates/app' && cargo nextest run"),
            "cd -- 'crates/app' && mbx nextest run"
        );
        assert_eq!(
            mbxify_cargo_command(PER_CRATE_TEST_COMMAND),
            format!("{MR_BOXINGTON_ENABLED_ENV}=1 {PER_CRATE_TEST_COMMAND}")
        );
        assert_eq!(
            mbxify_cargo_command("cargo-deny --version"),
            "cargo-deny --version"
        );
        assert_eq!(
            mbxify_cargo_command("cargo update --workspace --offline"),
            "mbx update --workspace --offline"
        );
        assert_eq!(
            mbxify_cargo_command("cargo install --locked --path ."),
            "cargo install --locked --path ."
        );
    }

    #[test]
    fn static_templates_route_rust_commands_through_mr_boxington() {
        let template = "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n      - uses: actions/checkout@v7\n      - run: |\n          cargo test --locked\n          rustup run \"${MSRV}\" cargo check --locked\n          cargo install --locked --path .\n";

        let rendered = render_static_template(template, FIXTURE_REVISION);
        assert!(rendered.starts_with(GENERATED_HEADER));
        assert!(rendered.contains("jdx/mr-boxington-action@"));
        assert!(rendered.contains("run: |\n          mbx test --locked"));
        assert!(rendered.contains("mbx +\"${MSRV}\" check --locked"));
        assert!(rendered.contains("version: 1.12.0"));
        assert!(rendered.contains("cargo install --locked --path ."));
        assert!(!rendered.contains("cargo test"));
        assert!(!rendered.contains("cargo check"));
    }

    /// A hosted job that points Mr. Boxington's local backend at a disposable
    /// runner claims persistence nothing can serve. Generation refuses it
    /// unless the job selects the persistent runner pool — and the GitHub
    /// object-cache alternative is refused too when it carries no cache key,
    /// because a keyless snapshot import restores nothing (§9.1 test 7).
    #[test]
    fn static_templates_reject_local_mbx_without_declared_persistence() {
        let hosted_local = "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: local\n          version: 1.11.1\n";
        let rejected = must_fail(
            validate_static_template_cache_transports(hosted_local),
            "hosted local mbx must be rejected",
        );
        let message = rejected.to_string();
        assert!(message.contains("build"), "{message}");
        assert!(message.contains("backend: local"), "{message}");

        let self_hosted_local = "name: CI\njobs:\n  build:\n    runs-on: [self-hosted, pool]\n    steps:\n      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: local\n";
        must(
            validate_static_template_cache_transports(self_hosted_local),
            "local mbx on the persistent pool is accepted",
        );

        let group_local = "name: CI\njobs:\n  build:\n    runs-on: ${{ fromJSON('{\"group\":\"ci\",\"labels\":[\"self-hosted\",\"pool\"]}') }}\n    steps:\n      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: local\n";
        must(
            validate_static_template_cache_transports(group_local),
            "local mbx behind the persistent runner group is accepted",
        );

        let keyless_github = "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: github\n          version: 1.11.1\n";
        let rejected = must_fail(
            validate_static_template_cache_transports(keyless_github),
            "keyless object-cache mbx must be rejected",
        );
        let message = rejected.to_string();
        assert!(message.contains("cache-key"), "{message}");

        // A key that names compatibility but hashes no source state is the
        // frozen-snapshot defect itself: GitHub cache entries are immutable,
        // so the first save under that key refuses every later save.
        let compatibility_only = "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: github\n          github-cache-mode: objects\n          version: 1.11.1\n          cache-key: example-${{ runner.os }}-${{ hashFiles('Cargo.lock') }}\n          restore-keys: |\n            example-${{ runner.os }}-\n";
        let rejected = must_fail(
            validate_static_template_cache_transports(compatibility_only),
            "a compatibility-only key must be rejected",
        );
        let message = rejected.to_string();
        assert!(message.contains("compatibility only"), "{message}");

        // A complete key with a freshness segment, and prefixes-only restore
        // keys, is the shape generation accepts.
        let keyed_github = "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: github\n          github-cache-mode: objects\n          version: 1.11.1\n          cache-key: example-mbx-v3-a1b2c3d4e5f6-${{ runner.os }}-${{ hashFiles('Cargo.lock') }}-${{ hashFiles('**/*.rs') }}\n          restore-keys: |\n            example-mbx-v3-a1b2c3d4e5f6-${{ runner.os }}-${{ hashFiles('Cargo.lock') }}-\n            example-mbx-v3-a1b2c3d4e5f6-${{ runner.os }}-\n";
        must(
            validate_static_template_cache_transports(keyed_github),
            "a freshness-carrying snapshot key is accepted",
        );

        // A complete generation on the restore list would shadow newer
        // compatible fallbacks, so generation refuses it.
        let complete_restore_key = "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: github\n          github-cache-mode: objects\n          version: 1.11.1\n          cache-key: example-mbx-v3-a1b2c3d4e5f6-${{ runner.os }}-${{ hashFiles('Cargo.lock') }}-${{ hashFiles('**/*.rs') }}\n          restore-keys: |\n            example-mbx-v3-a1b2c3d4e5f6-${{ runner.os }}-${{ hashFiles('Cargo.lock') }}-${{ hashFiles('**/*.rs') }}\n";
        let rejected = must_fail(
            validate_static_template_cache_transports(complete_restore_key),
            "a complete generation on the restore list must be rejected",
        );
        let message = rejected.to_string();
        assert!(message.contains("prefixes only"), "{message}");

        // The generator's own canonical static step must satisfy the contract
        // it enforces once its identity markers are filled.
        let filled = static_mr_boxington_step()
            .replace("__VELNOR_SNAPSHOT_COMPATIBILITY__", "v3-a1b2c3d4e5f6")
            .replace("__VELNOR_SNAPSHOT_STATE__", "${{ hashFiles('**/*.rs') }}");
        must(
            validate_static_template_cache_transports(&format!(
                "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n{filled}"
            )),
            "the canonical static Mr. Boxington step passes its own validation",
        );
    }

    /// Every file the generator writes for the schema-2 polyglot fixture.
    /// The bridge keeps the dogfood repository on schema 1, so fixture
    /// renders — not repository renders — carry the surface-wide
    /// assertions.
    fn rendered_fixture_files() -> BTreeMap<PathBuf, String> {
        must(
            generated_files(&scanned_fixture(all_providers())),
            "render fixture files",
        )
    }

    #[test]
    fn generated_rust_surface_declares_and_passes_mbx_input() {
        let config = scanned_fixture(all_providers());
        let files = must(generated_files(&config), "render fixture files");
        let rust = must_some(
            files.get(&PathBuf::from(".github/workflows/ci-unit-rust.yml")),
            "generated Rust reusable",
        );
        assert!(
            rust.contains(
                "      mbx_enabled:\n        required: false\n        type: boolean\n        default: false"
            ),
            "the Rust reusable declares the typed MBX input: {rust}"
        );

        let mut caller_count = 0;
        for aggregate in ["ci-pr.yml", "ci-main.yml"] {
            let workflow = must_some(
                files.get(&PathBuf::from(".github/workflows").join(aggregate)),
                aggregate,
            );
            for (_, block) in static_workflow_job_blocks(workflow) {
                if !block.contains("uses: ./.github/workflows/ci-unit-rust.yml")
                    || !(block.contains("provider: github-hosted")
                        || block.contains("provider: velnor"))
                {
                    continue;
                }
                caller_count += 1;
                assert!(
                    block.contains("      mbx_enabled: true\n"),
                    "{aggregate} Rust caller passes the typed MBX value: {block}"
                );
            }
        }
        assert!(
            caller_count > 0,
            "generated aggregate workflows contain Rust provider callers"
        );
    }

    /// The fixture configuration with two cargo-restricted Rust units: the
    /// clones keep the scanned commands (which resolve no inputs of their
    /// own) and pin their lockfiles, so the prepare-cargo aggregate and
    /// the per-provider prep jobs render.
    fn restricted_fixture_config() -> ProjectConfig {
        let mut config = scanned_fixture(all_providers());
        let rust = must_some(
            config
                .units
                .iter()
                .find(|unit| unit.kind == UnitKind::Rust)
                .cloned(),
            "fixture rust unit",
        );
        for index in 0..2 {
            let mut unit = rust.clone();
            unit.id = format!("rust-restricted-{index}");
            unit.label = format!("Rust restricted {index}");
            unit.pinned_lockfile = true;
            config.units.push(unit);
        }
        if let Some(unit) = config
            .units
            .iter_mut()
            .find(|unit| unit.kind == UnitKind::Rust && !unit.id.starts_with("rust-restricted-"))
        {
            unit.pinned_lockfile = true;
        }
        config
    }

    /// A scanned schema-2 repository declaring the rust-binary release
    /// contract: the release-family renders (release, preview,
    /// maintenance) for surface-wide assertions.
    fn scanned_release_config() -> ProjectConfig {
        let root = configured_repository(
            "release-surface",
            Some(
                "schema = 2\n\n[generator]\nrepository = \"example/fixture\"\n\n\
                 [workflow]\nproviders = [\"github-hosted\"]\n\n\
                 [workflow.selectors.github-hosted]\nruns_on = [\"ubuntu-24.04\"]\n\n\
                 [release]\nenabled = true\nkind = \"rust-binary\"\npackage = \"example\"\n\
                 binary = \"example\"\ntargets = [\"x86_64-unknown-linux-gnu\"]\n",
            ),
        );
        let config = must(
            scan_repository(&root, Some(provider_set([ProviderId::GithubHosted]))),
            "scan release repository",
        );
        let _ = fs::remove_dir_all(root);
        config
    }

    fn workflow_job_block(files: &BTreeMap<PathBuf, String>, file: &str, job: &str) -> String {
        let workflow = must_some(
            files.get(&PathBuf::from(".github/workflows").join(file)),
            &format!("rendered {file}"),
        );
        must_some(
            static_workflow_job_blocks(workflow)
                .into_iter()
                .find_map(|(id, block)| (id == job).then_some(block)),
            &format!("job `{job}` in {file}"),
        )
    }

    fn step_names(block: &str) -> Vec<String> {
        named_workflow_steps(block)
            .into_iter()
            .map(|(name, _)| name)
            .collect()
    }

    /// The hosted store budget is a property of running Mr. Boxington against
    /// the GitHub backend: every such job exports it before the action, so
    /// the import, every Cargo command, and the post-step export run under
    /// the same bound; no local-backend job carries it. The GitHub-lane Rust
    /// job is the unit whose 5.2 GiB footprint crossed mbx's 5 GiB floor.
    #[test]
    fn github_backend_mr_boxington_jobs_export_the_hosted_store_budget() {
        let export = format!("{MR_BOXINGTON_STORE_BUDGET_ENV}={MR_BOXINGTON_HOSTED_STORE_BUDGET}");
        let files = rendered_fixture_files();
        must(
            validate_hosted_mr_boxington_store_budget(&files),
            "every rendered GitHub-backend Mr. Boxington job carries the store budget",
        );

        let github_lane = workflow_job_block(&files, "ci-unit-rust.yml", "verify-github-hosted");
        let names = step_names(&github_lane);
        let budget = must_some(
            names
                .iter()
                .position(|name| name == MR_BOXINGTON_STORE_BUDGET_STEP),
            "GitHub-lane Rust job exports the store budget",
        );
        let action = must_some(
            names.iter().position(|name| name == "Set up Mr. Boxington"),
            "GitHub-lane Rust job sets up Mr. Boxington",
        );
        assert!(budget < action, "{names:?}");
        assert!(
            github_lane.contains(&format!("run: echo \"{export}\" >> \"$GITHUB_ENV\"")),
            "{github_lane}"
        );
        assert!(github_lane.contains("backend: github"), "{github_lane}");

        // The Velnor lane's store is host-persistent and budgeted by the
        // fleet env; the hosted ceiling must not reach it.
        let velnor_lane = workflow_job_block(&files, "ci-unit-rust.yml", "verify-velnor");
        assert!(velnor_lane.contains("backend: local"), "{velnor_lane}");
        assert!(!velnor_lane.contains(&export), "{velnor_lane}");

        // Every hosted job of every family, not only the unit lanes.
        let mut hosted_jobs = 0;
        for (_, workflow) in rendered_workflow_files(&files) {
            for (_, block) in static_workflow_job_blocks(workflow) {
                if block.contains("backend: github") {
                    hosted_jobs += 1;
                    assert!(block.contains(&export), "{block}");
                }
            }
        }
        assert!(
            hosted_jobs >= 1,
            "the fixture renders hosted Mr. Boxington jobs"
        );
    }

    /// The validator behind the test above, on hand-written shapes: the
    /// budget must exist, precede the action, and stay off local stores.
    #[test]
    fn hosted_store_budget_validator_requires_the_export_before_the_action() {
        let budget = mr_boxington_store_budget_step();
        let action = "      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: github\n          github-cache-mode: objects\n";
        let local = "      - name: Set up Mr. Boxington\n        uses: jdx/mr-boxington-action@a20e1ffcd962370fb2b6045c13b7b349f7b03386 # v1.3.1\n        with:\n          backend: local\n";
        let workflow = |steps: &str| {
            BTreeMap::from([(
                PathBuf::from(".github/workflows/ci.yml"),
                format!(
                    "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n{steps}"
                ),
            )])
        };

        must(
            validate_hosted_mr_boxington_store_budget(&workflow(&format!("{budget}{action}"))),
            "budget before the GitHub-backend action is accepted",
        );
        must(
            validate_hosted_mr_boxington_store_budget(&workflow(local)),
            "a local-backend job without the hosted budget is accepted",
        );

        let missing = must_fail(
            validate_hosted_mr_boxington_store_budget(&workflow(action)),
            "a GitHub-backend job without the budget is refused",
        )
        .to_string();
        assert!(missing.contains("ci.yml: job `build`"), "{missing}");
        assert!(missing.contains(MR_BOXINGTON_STORE_BUDGET_ENV), "{missing}");
        assert!(
            missing.contains(MR_BOXINGTON_HOSTED_STORE_BUDGET),
            "{missing}"
        );

        let late = must_fail(
            validate_hosted_mr_boxington_store_budget(&workflow(&format!("{action}{budget}"))),
            "a budget exported after the action is refused",
        )
        .to_string();
        assert!(late.contains("ahead of the action"), "{late}");

        let leaked = must_fail(
            validate_hosted_mr_boxington_store_budget(&workflow(&format!("{budget}{local}"))),
            "the hosted budget on a local-backend job is refused",
        )
        .to_string();
        assert!(leaked.contains("local-backend"), "{leaked}");
    }

    /// Full history is a property of running the validator: every job whose
    /// steps run `velnor-workflow policy` checks out with `fetch-depth: 0`,
    /// because `pin-reachable` walks from the audited head to the declared
    /// pin and a shallow checkout holds neither.
    #[test]
    fn policy_running_jobs_check_out_full_history() {
        let mut files = rendered_fixture_files();
        // The fixture declares no release contract, so the release-family
        // validator jobs come from the release repository.
        let release_config = scanned_release_config();
        if let Some(release) = primitives::release::release_content(&release_config) {
            files.insert(PathBuf::from(".github/workflows/release.yml"), release);
        }
        files.insert(
            PathBuf::from(".github/workflows/preview.yml"),
            primitives::release::preview_content(&release_config),
        );
        must(
            validate_policy_jobs_check_out_full_history(&files),
            "every rendered validator-running job checks out full history",
        );
        let mut validator_jobs = Vec::new();
        for (path, workflow) in rendered_workflow_files(&files) {
            for (job, block) in static_workflow_job_blocks(workflow) {
                let steps = named_workflow_steps(&block);
                if !steps
                    .iter()
                    .any(|(_, body)| step_runs_workflow_policy(body))
                {
                    continue;
                }
                assert!(
                    steps.iter().any(|(_, body)| {
                        body.contains("actions/checkout@")
                            && body.lines().any(|line| line.trim() == "fetch-depth: 0")
                    }),
                    "{path}: job `{job}` runs the validator from a shallow checkout:\n{block}"
                );
                // The audited checkout above is full; any shallow checkout
                // beside it must be the base-tree setup-action checkout (base
                // ref, action directory only), never a head checkout.
                for (name, body) in &steps {
                    if !body.lines().any(|line| line.trim() == "fetch-depth: 1") {
                        continue;
                    }
                    assert!(
                        body.contains(
                            "ref: ${{ github.event.pull_request.base.sha || github.sha }}"
                        ) && body
                            .contains("sparse-checkout: .github/actions/setup-velnor-workflow")
                            && !body.contains("head.sha"),
                        "{path}: job `{job}` step `{name}` declares a shallow checkout that is not the base-tree setup-action checkout:\n{block}"
                    );
                }
                validator_jobs.push(format!("{path}#{job}"));
            }
        }
        // The release-family validator jobs come from the rust-binary
        // release repository (the fixture declares no release contract);
        // nightly dispatches ci-main and runs no validator of its own.
        for expected in [
            ".github/workflows/preview.yml#build",
            ".github/workflows/release.yml#verify",
            ".github/workflows/ci-policy.yml#policy",
            ".github/workflows/ci-main.yml#policy",
        ] {
            assert!(
                validator_jobs.iter().any(|job| job == expected),
                "{expected} runs the validator: {validator_jobs:?}"
            );
        }
    }

    /// The validator behind the test above, on hand-written shapes.
    #[test]
    fn full_history_validator_refuses_a_shallow_policy_job() {
        let workflow = |checkout_with: &str| {
            BTreeMap::from([(
                PathBuf::from(".github/workflows/preview.yml"),
                format!(
                    "name: Preview\njobs:\n  identity:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Checkout\n        uses: {}\n        with:\n{checkout_with}          persist-credentials: false\n      - name: Enforce workflow policy\n        run: velnor-workflow policy --workflow-root \"$GITHUB_WORKSPACE\"\n",
                    ActionPin::Checkout.reference()
                ),
            )])
        };
        must(
            validate_policy_jobs_check_out_full_history(&workflow("          fetch-depth: 0\n")),
            "a full-history checkout is accepted",
        );
        for shallow in ["          fetch-depth: 1\n", ""] {
            let message = must_fail(
                validate_policy_jobs_check_out_full_history(&workflow(shallow)),
                "a shallow checkout ahead of the validator is refused",
            )
            .to_string();
            assert!(message.contains("preview.yml: job `identity`"), "{message}");
            assert!(message.contains("fetch-depth: 0"), "{message}");
        }

        // A job that only mentions the validator in a comment is not bound.
        let commented = BTreeMap::from([(
            PathBuf::from(".github/workflows/ci.yml"),
            format!(
                "name: CI\njobs:\n  build:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Checkout\n        uses: {}\n        with:\n          persist-credentials: false\n      - name: Build\n        # unlike `velnor-workflow policy`, this needs no history\n        run: cargo build\n",
                ActionPin::Checkout.reference()
            ),
        )]);
        must(
            validate_policy_jobs_check_out_full_history(&commented),
            "a comment naming the validator does not bind the job",
        );
    }

    /// Failure 3 of the post-#872 `main` runs: hosted Planning set up the
    /// pinned validator and then the event runtime through the same action,
    /// whose source build ran `cargo install` into the default `~/.cargo/bin`
    /// that the first install had already filled (`binary velnor-workflow
    /// already exists in destination`, run 35056570751). Every rendered
    /// install of the runtime owns a revision-addressed root, nothing puts the
    /// runtime binary into the shared cargo bin, and the composite action's
    /// layout is the one Planning and the unit jobs address.
    #[test]
    fn every_runtime_install_owns_a_revision_addressed_root() {
        let files = rendered_fixture_files();
        must(
            validate_workflow_runtime_install_roots(&files),
            "every rendered velnor-workflow install owns its root",
        );
        let mut installs = Vec::new();
        for (path, rendered) in rendered_workflow_and_action_files(&files) {
            assert!(
                !rendered.lines().any(names_shared_cargo_bin_runtime),
                "{path} places the runtime in the shared cargo bin"
            );
            for install in workflow_runtime_installs(rendered) {
                let root = must_some(install.root.clone(), &install.command);
                assert!(
                    !root_is_shared_cargo_bin(&root),
                    "{path}: {}",
                    install.command
                );
                installs.push(format!(
                    "{path}: --root {root} --rev {:?}",
                    install.revision
                ));
            }
        }
        // No generated consumer compiles the runtime: the setup action, the
        // Velnor lane, and the policy entrypoint all acquire immutable
        // prebuilt products. Any `cargo install ... velnor-workflow` left in the
        // generated tree is a regression of the multi-minute bootstrap class
        // this test exists to forbid.
        assert!(installs.is_empty(), "{installs:#?}");

        // The checked-in action is what those paths address: its cargo root,
        // Downloaded product, cache path, and PATH entry are one
        // closure-addressed directory: every commit sharing the closure
        // reuses the same product.
        let action = declared_setup_action();
        let runtime = format!("runtime=\"{HOSTED_WORKFLOW_RUNTIME_HOME}/$CLOSURE\"");
        assert!(action.contains(&runtime), "{action}");
        assert!(
            action.contains("\"$runtime/bin/velnor-workflow\""),
            "{action}"
        );
        assert!(
            action.contains("echo \"$runtime/bin\" >> \"$GITHUB_PATH\""),
            "{action}"
        );
        assert!(
            action.contains("path: ~/.cache/velnor/workflow-runtime\n"),
            "{action}"
        );
        assert!(
            action.contains("steps.closure.outputs.value"),
            "the cache key is closure-addressed: {action}"
        );
        assert!(
            action.contains("default: velnor-workflow-v3"),
            "the product layout changed, so the cache key namespace moves: {action}"
        );
        assert!(
            !action
                .lines()
                .any(|line| !line.trim_start().starts_with('#') && line.contains(".cargo/bin")),
            "no script line touches the shared cargo bin: {action}"
        );
        assert_eq!(
            HOSTED_WORKFLOW_RUNTIME_HOME,
            "$HOME/.cache/velnor/workflow-runtime"
        );
    }

    /// The validator behind the test above, on hand-written shapes.
    #[test]
    fn runtime_install_root_validator_refuses_shared_destinations() {
        let job = |run: &str| {
            BTreeMap::from([(
                PathBuf::from(".github/workflows/ci-main.yml"),
                format!(
                    "name: CI\njobs:\n  plan:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Install\n        env:\n          PINNED_REVISION: {FIXTURE_REVISION}\n        run: |\n{run}"
                ),
            )])
        };
        let install = |rev: &str, root: &str| {
            format!(
                "          cargo install --locked --git {VELNOR_WORKFLOW_INSTALL_GIT_URL} --rev {rev} {root} velnor-workflow --bin velnor-workflow\n"
            )
        };

        must(
            validate_workflow_runtime_install_roots(&job(&install(
                "\"$PINNED_REVISION\"",
                "--root \"$RUNNER_TEMP/velnor-workflow-$PINNED_REVISION\"",
            ))),
            "a revision-addressed root is accepted",
        );
        let message = must_fail(
            validate_workflow_runtime_install_roots(&job(&install("\"$PINNED_REVISION\"", ""))),
            "an install without --root is refused",
        )
        .to_string();
        assert!(
            message.contains("ci-main.yml: plan installs velnor-workflow without `--root`"),
            "{message}"
        );

        for shared in [
            "\"$HOME/.cargo\"",
            "\"$HOME/.cargo/bin\"",
            "\"${CARGO_HOME:-$HOME/.cargo}\"",
            "\"$CARGO_HOME/bin\"",
        ] {
            let message = must_fail(
                validate_workflow_runtime_install_roots(&job(&install(
                    "\"$PINNED_REVISION\"",
                    &format!("--root {shared}"),
                ))),
                "the shared cargo bin is refused as a root",
            )
            .to_string();
            assert!(
                message.contains("shared cargo bin directory"),
                "{shared}: {message}"
            );
        }

        // A variable revision must be part of its root: the same step text
        // runs once per revision.
        let message = must_fail(
            validate_workflow_runtime_install_roots(&job(&install(
                "\"$INSTALL_REV\"",
                "--root \"$RUNNER_TEMP/velnor-workflow\"",
            ))),
            "a variable revision outside its root is refused",
        )
        .to_string();
        assert!(
            message.contains("variable revision `$INSTALL_REV`"),
            "{message}"
        );
        // …and a root reached through a shell assignment is judged by the
        // path it names, the way the composite action spells it.
        must(
            validate_workflow_runtime_install_roots(&job(&format!(
                "          runtime=\"$HOME/.cache/velnor/workflow-runtime/$INSTALL_REV\"\n{}",
                install("\"$INSTALL_REV\"", "--root \"$runtime\"")
            ))),
            "an assigned root that embeds the revision is accepted",
        );

        // Two revisions in one job need two roots; the identical revision may
        // share one.
        let other = "0123456789abcdef0123456789abcdef01234567";
        let message = must_fail(
            validate_workflow_runtime_install_roots(&job(&format!(
                "{}{}",
                install(FIXTURE_REVISION, "--root \"$RUNNER_TEMP/velnor-workflow\""),
                install(other, "--root \"$RUNNER_TEMP/velnor-workflow\"")
            ))),
            "two revisions into one root are refused",
        )
        .to_string();
        assert!(
            message.contains("into one root `$RUNNER_TEMP/velnor-workflow`"),
            "{message}"
        );
        must(
            validate_workflow_runtime_install_roots(&job(&format!(
                "{}{}",
                install(FIXTURE_REVISION, "--root \"$RUNNER_TEMP/velnor-workflow\""),
                install(FIXTURE_REVISION, "--root \"$RUNNER_TEMP/velnor-workflow\"")
            ))),
            "the identical revision may share a root",
        );
    }

    /// The same validator on the copy and composite-action shapes.
    #[test]
    fn runtime_install_root_validator_refuses_shared_copies_and_judges_actions() {
        let job = |run: &str| {
            BTreeMap::from([(
                PathBuf::from(".github/workflows/ci-main.yml"),
                format!(
                    "name: CI\njobs:\n  plan:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Install\n        run: |\n{run}"
                ),
            )])
        };
        let install = |rev: &str, root: &str| {
            format!(
                "          cargo install --locked --git {VELNOR_WORKFLOW_INSTALL_GIT_URL} --rev {rev} {root} velnor-workflow --bin velnor-workflow\n"
            )
        };
        // Copying the runtime binary into the shared cargo bin is the other
        // way to build the collision; the distinctly named Velnor policy copy
        // is not it.
        let message = must_fail(
            validate_workflow_runtime_install_roots(&job(
                "          install -Dm0755 \"$RUNNER_TEMP/velnor-workflow/bin/velnor-workflow\" \"$HOME/.cargo/bin/velnor-workflow\"\n",
            )),
            "copying the runtime into the shared cargo bin is refused",
        )
        .to_string();
        assert!(message.contains("shared cargo bin directory"), "{message}");
        must(
            validate_workflow_runtime_install_roots(&job(
                "          binary=\"${CARGO_HOME:-$HOME/.cargo}/bin/velnor-workflow-policy\"\n",
            )),
            "the Velnor lane's distinctly named policy copy is not the runtime",
        );

        // Composite actions are judged as one block.
        let action = BTreeMap::from([(
            PathBuf::from(".github/actions/setup-velnor-workflow/action.yml"),
            format!(
                "name: Setup\nruns:\n  using: composite\n  steps:\n    - name: Install\n      shell: bash\n      env:\n        INSTALL_REV: ${{{{ inputs.rev }}}}\n      run: |\n{}",
                install("\"$INSTALL_REV\"", "")
            ),
        )]);
        let message = must_fail(
            validate_workflow_runtime_install_roots(&action),
            "a composite action install without --root is refused",
        )
        .to_string();
        assert!(
            message
                .contains("action.yml: composite action installs velnor-workflow without `--root`"),
            "{message}"
        );
    }

    fn guest_seed_job_with_prefix() -> String {
        "name: Preview\njobs:\n  guest-payload:\n    runs-on: ubuntu-24.04\n    steps:\n      - name: Restore guest seed\n        id: guest-seed\n        uses: actions/cache/restore@sha\n        with:\n          path: .guest-seed/${{ matrix.arch }}\n          key: guest-seed-${{ matrix.arch }}-${{ hashFiles('microvm/**', 'Cargo.lock') }}\n          restore-keys: |\n            guest-seed-${{ matrix.arch }}-\n      - name: Build guest agent for rootfs\n        run: cargo build --locked --release --package example --bin example-guest-agent\n      - name: Reuse verified guest seed\n        id: guest-seed-reuse\n        run: |\n          sha256sum --check --strict vmlinux.sha256\n          echo restored=false\n          echo restored=false\n      - name: Download pinned kernel tarball\n        if: steps.guest-seed-reuse.outputs.restored != 'true'\n        run: |\n          jq -er .kernel_tarball microvm/pins.json\n          curl --fail -o linux.tar.xz\n      - name: Build guest vmlinux and rootfs.ext4\n        if: steps.guest-seed-reuse.outputs.restored != 'true'\n        run: cargo run --locked --release --package example --bin example-guest-image -- build\n      - name: Collect verified guest seed\n        if: github.event_name == 'push' && github.ref == 'refs/heads/main' && steps.guest-seed.outputs.cache-hit != 'true'\n        run: |\n          cp dist/microvm/vmlinux .guest-seed/\n      - name: Save guest seed\n        if: github.event_name == 'push' && github.ref == 'refs/heads/main' && steps.guest-seed.outputs.cache-hit != 'true'\n        uses: actions/cache/save@sha\n        with:\n          path: .guest-seed/${{ matrix.arch }}\n          key: guest-seed-${{ matrix.arch }}-${{ hashFiles('microvm/**', 'Cargo.lock') }}\n".to_owned()
    }

    fn guest_seed_job() -> String {
        guest_seed_job_with_prefix().replace(
            "          restore-keys: |\n            guest-seed-${{ matrix.arch }}-\n",
            "",
        )
    }

    #[test]
    fn guest_seed_lifecycle_requires_trusted_exact_miss_save() {
        must(
            validate_guest_seed_lifecycle(&guest_seed_job(), "main"),
            "a complete guest-seed lifecycle is accepted",
        );

        let missing_save = guest_seed_job().replace(
            "      - name: Save guest seed\n        if: github.event_name == 'push' && github.ref == 'refs/heads/main' && steps.guest-seed.outputs.cache-hit != 'true'\n        uses: actions/cache/save@sha\n        with:\n          path: .guest-seed/${{ matrix.arch }}\n          key: guest-seed-${{ matrix.arch }}-${{ hashFiles('microvm/**', 'Cargo.lock') }}\n",
            "",
        );
        let error = must_fail(
            validate_guest_seed_lifecycle(&missing_save, "main"),
            "a restore without save must be rejected",
        );
        assert!(error.to_string().contains("Save guest seed"), "{error}");

        let keyed_by_sha = guest_seed_job().replace(
            "guest-seed-${{ matrix.arch }}-${{ hashFiles('microvm/**', 'Cargo.lock') }}",
            "guest-seed-${{ matrix.arch }}-${{ github.sha }}",
        );
        let error = must_fail(
            validate_guest_seed_lifecycle(&keyed_by_sha, "main"),
            "a github.sha guest-seed key must be rejected",
        );
        assert!(error.to_string().contains("github.sha"), "{error}");

        let ungated_kernel = guest_seed_job().replace(
            "      - name: Download pinned kernel tarball\n        if: steps.guest-seed-reuse.outputs.restored != 'true'\n",
            "      - name: Download pinned kernel tarball\n",
        );
        let error = must_fail(
            validate_guest_seed_lifecycle(&ungated_kernel, "main"),
            "an ungated kernel tarball download must be rejected",
        );
        assert!(error.to_string().contains("kernel tarball"), "{error}");

        let prefix_restore_key = guest_seed_job_with_prefix();
        let error = must_fail(
            validate_guest_seed_lifecycle(&prefix_restore_key, "main"),
            "a prefix guest-seed restore must be rejected",
        );
        assert!(error.to_string().contains("exact-only"), "{error}");

        let trunk = guest_seed_job().replace("refs/heads/main", "refs/heads/trunk");
        must(
            validate_guest_seed_lifecycle(&trunk, "trunk"),
            "the configured default branch is accepted",
        );

        let arbitrary_branch = guest_seed_job().replace("refs/heads/main", "refs/heads/feature");
        let error = must_fail(
            validate_guest_seed_lifecycle(&arbitrary_branch, "main"),
            "an arbitrary branch must be rejected",
        );
        assert!(error.to_string().contains("default-branch"), "{error}");

        let stub_reuse =
            guest_seed_job().replace("sha256sum --check --strict vmlinux.sha256", "true");
        let error = must_fail(
            validate_guest_seed_lifecycle(&stub_reuse, "main"),
            "a reuse step that only checks file presence must be rejected",
        );
        assert!(error.to_string().contains("checksum"), "{error}");
    }

    #[test]
    fn preview_static_surface_saves_guest_seed_on_trusted_exact_miss() {
        // A synthetic microvm repository: the guest-seed lifecycle needs a
        // microvm-watching unit plus scanned guest-agent/guest-image bins,
        // which the schema-1 dogfood tree can no longer lend this suite.
        let root = temporary_repository("preview-guest-seed");
        must(
            fs::write(
                root.join("rust-toolchain.toml"),
                "[toolchain]\nchannel = \"1.91.1\"\ntargets = [\"x86_64-unknown-linux-gnu\", \"aarch64-unknown-linux-gnu\"]\n",
            ),
            "write toolchain pin with release targets",
        );
        must(
            fs::create_dir_all(root.join("microvm/src/bin")),
            "create microvm sources",
        );
        must(
            fs::write(
                root.join("microvm/Cargo.toml"),
                "[package]\nname = \"example\"\nversion = \"0.1.0\"\n\n\
                 [features]\nrelease-build = []\n\n\
                 [[bin]]\nname = \"example-guest-agent\"\npath = \"src/bin/agent.rs\"\n\n\
                 [[bin]]\nname = \"example-guest-image\"\npath = \"src/bin/image.rs\"\n",
            ),
            "write microvm manifest",
        );
        must(
            fs::write(root.join("microvm/src/bin/agent.rs"), "fn main() {}\n"),
            "write agent source",
        );
        must(
            fs::write(root.join("microvm/src/bin/image.rs"), "fn main() {}\n"),
            "write image source",
        );
        must(
            fs::create_dir_all(root.join(".github-gen")),
            "create config dir",
        );
        must(
            fs::write(
                root.join(".github-gen/velnor-workflow.toml"),
                "schema = 2\n\n[generator]\nrepository = \"example/fixture\"\n\n\
                 [workflow]\nproviders = [\"github-hosted\"]\n\
                 files = [\"ci-pr.yml\", \"release.yml\", \"ci-release-package-signer.yml\"]\n\n\
                 [workflow.selectors.github-hosted]\nruns_on = [\"ubuntu-24.04\"]\n\n\
                 [release]\nenabled = true\nkind = \"native\"\npackage = \"example\"\n\
                 binary = \"example\"\ntargets = [\"x86_64-unknown-linux-gnu\", \"aarch64-unknown-linux-gnu\"]\n\
                 consumer_repository = \"example/consumer\"\n\n\
                 [[declare]]\nprimitive = \"preview\"\nfile = \"preview.yml\"\n",
            ),
            "write generation config",
        );
        rebind_visibility_evidence(&root, "public");
        let scanned = must(
            scan_target(
                &root,
                Some(provider_set([ProviderId::GithubHosted])),
                "main",
            ),
            "scan microvm repository",
        );
        let surface = must(
            crate::s2::primitives::generate(
                &root,
                &scanned.shape,
                &scanned.config,
                scanned.generation.as_ref(),
            ),
            "render declared static surface",
        );
        let preview = must_some(
            surface
                .files
                .get(&PathBuf::from(".github/workflows/preview.yml")),
            "preview.yml",
        )
        .clone();
        must(
            validate_guest_seed_lifecycle(&preview, &scanned.config.default_branch),
            "preview guest seed lifecycle",
        );
        assert!(preview.contains("- name: Restore guest seed"));
        assert!(preview.contains("- name: Reuse verified guest seed"));
        assert!(preview.contains("- name: Collect verified guest seed"));
        assert!(preview.contains("- name: Save guest seed"));
        assert!(preview.contains("actions/cache/restore@"));
        assert!(preview.contains("actions/cache/save@"));
        assert!(preview.contains("guest-seed-${{ matrix.arch }}-"));
        assert!(preview.contains("hashFiles("));
        assert!(preview.contains("'microvm/**'"));
        assert!(preview.contains("Cargo.lock"));
        assert!(preview.contains("rust-toolchain.toml"));
        assert!(preview.contains("restored=false"));
        assert!(!preview.contains("guest-seed-${{ matrix.arch }}-${{ github.sha }}"));
        assert!(preview.contains("if: steps.guest-seed-reuse.outputs.restored != 'true'"));
        assert!(preview.contains(
            "if: github.event_name == 'push' && github.ref == 'refs/heads/main' && steps.guest-seed.outputs.cache-hit != 'true'"
        ));
        assert!(preview.contains("microvm/pins.json"), "{preview}");
        assert!(preview.contains("curl --fail"), "{preview}");
        assert!(preview.contains("cp dist/microvm/vmlinux"), "{preview}");
        assert!(preview.contains("sha256sum --check --strict"), "{preview}");
        assert!(preview.contains("mmdebstrap"), "{preview}");
        assert!(preview.contains("gcc-aarch64-linux-gnu"), "{preview}");
        assert!(preview.contains("flex bison bc"), "{preview}");
        assert!(preview.contains("--bin example-guest-agent"), "{preview}");
        assert!(preview.contains("--bin example-guest-image"), "{preview}");
        assert!(
            preview
                .contains("mbx run --locked --release --package example --bin example-guest-image")
                || preview.contains(
                    "cargo run --locked --release --package example --bin example-guest-image"
                ),
            "guest image build must invoke the scanned guest-image bin: {preview}"
        );
        assert!(
            !preview.contains("velnor-workflow release package-guest"),
            "{preview}"
        );

        let guest_start = must_some(preview.find("  guest-payload:\n"), "guest payload job");
        let guest_len = must_some(
            preview[guest_start..].find("\n  metadata:"),
            "guest payload job boundary",
        );
        let guest = &preview[guest_start..guest_start + guest_len];
        assert_eq!(guest.matches("runs-on:").count(), 1, "{guest}");
        assert!(
            guest.contains("    runs-on: ${{ matrix.runner }}\n"),
            "the guest producer must honor each architecture's hosted runner: {guest}"
        );
        let configured_hosted_runner = selector_runs_on_yaml(must_some(
            scanned.config.selectors.get(&ProviderId::GithubHosted),
            "hosted selector",
        ));
        assert!(
            guest.contains(&format!(
                "          - arch: x86_64\n            target: x86_64-unknown-linux-gnu\n            runner: {configured_hosted_runner}\n"
            )),
            "x86_64 guest payload must stay on the configured hosted runner: {guest}"
        );
        assert!(
            guest.contains(
                "          - arch: aarch64\n            target: aarch64-unknown-linux-gnu\n            runner: ubuntu-24.04-arm\n"
            ),
            "aarch64 guest payload must use GitHub's hosted arm64 runner: {guest}"
        );
        assert!(
            !guest.contains("self-hosted"),
            "the guest producer must never enter the Velnor lane: {guest}"
        );

        let generated = must(
            crate::s2::generated_files(&scanned.config),
            "generate workflow files",
        );
        let ci_units = must_some(
            generated.get(&PathBuf::from(".github/workflows/ci-unit-rust.yml")),
            "Rust unit workflow",
        );
        assert!(
            ci_units.contains("  verify-github-hosted:"),
            "Rust kind reusable must keep a collapsed GitHub verify job: {ci_units}"
        );
        assert!(
            !ci_units.contains("  verify-velnor:"),
            "a hosted-only tree renders no Velnor verify job: {ci_units}"
        );
        assert!(
            !ci_units.contains("inputs.unit == '"),
            "the collapsed provider jobs must not guard steps by unit identity: {ci_units}"
        );
        assert!(
            ci_units.contains(
                "contains(inputs.selected_units, format('\"unit_id\":\"{0}\"', inputs.unit))"
            ),
            "the collapsed provider jobs gate on the selected unit through inputs.unit: {ci_units}"
        );
        let ci_pr = must_some(
            generated.get(&PathBuf::from(".github/workflows/ci-pr.yml")),
            "ci-pr workflow",
        );
        for unit in scanned
            .config
            .units
            .iter()
            .filter(|unit| unit.kind == UnitKind::Rust)
        {
            let id = &unit.id;
            assert!(
                ci_pr.contains(&format!("  github-hosted-{id}:")),
                "native verification unit lost its GitHub lane caller: {id}: {ci_pr}"
            );
            assert!(
                !ci_pr.contains(&format!("  velnor-{id}:")),
                "a hosted-only tree renders no Velnor lane caller: {id}: {ci_pr}"
            );
        }

        let restore = must_some(preview.find("- name: Restore guest seed"), "restore step");
        let agent = must_some(
            preview.find("- name: Build guest agent for rootfs"),
            "agent step",
        );
        assert!(!preview[restore..agent].contains("restore-keys:"));
        let reuse = must_some(
            preview.find("- name: Reuse verified guest seed"),
            "reuse step",
        );
        let kernel = must_some(
            preview.find("- name: Download pinned kernel tarball"),
            "kernel step",
        );
        let image = must_some(
            preview.find("- name: Build guest vmlinux and rootfs.ext4"),
            "image step",
        );
        let collect = must_some(
            preview.find("- name: Collect verified guest seed"),
            "collect step",
        );
        let save = must_some(preview.find("- name: Save guest seed"), "save step");
        assert!(
            restore < agent
                && agent < reuse
                && reuse < kernel
                && kernel < image
                && image < collect
                && collect < save,
            "guest-seed steps must run restore, agent, reuse, kernel, image, collect, save"
        );

        let release = must_some(
            surface
                .files
                .get(&PathBuf::from(".github/workflows/release.yml")),
            "release.yml",
        );
        must(
            validate_guest_seed_lifecycle(release, &scanned.config.default_branch),
            "release guest seed lifecycle",
        );
        assert!(release.contains("- name: Save guest seed"));
        assert!(release.contains("if: steps.guest-seed-reuse.outputs.restored != 'true'"));
        // The identity Debian lane also waits on the metadata export it
        // stages into the deb.
        assert!(
            release.contains("needs: [verify, build, metadata, guest-payload]"),
            "{release}"
        );
        assert!(
            release.contains("name: guest-payload-${{ matrix.arch }}"),
            "{release}"
        );
        assert!(
            release.contains("stage --root \"$root\" --arch"),
            "{release}"
        );
        assert!(release.contains("--rootfs-sha256"), "{release}");
        assert!(release.contains("--guest-agent-sha256"), "{release}");
        assert!(
            release.contains(".tarballs[$a].firecracker_member"),
            "{release}"
        );
        // The identity lane stages the verified guest payload in shell, so
        // the packager takes no unverified guest copy.
        assert!(
            release.contains("name: guest-payload-${{ matrix.guest_arch }}"),
            "{release}"
        );
        assert!(!release.contains("--guest dist/microvm"), "{release}");
        assert!(
            !release.contains("velnor-workflow release package-guest"),
            "{release}"
        );
    }

    /// The Docker mutable mount seed renders the whole lifecycle in order —
    /// host restore, seed-context preparation, the build, trusted-only
    /// collection, trusted-only save — on the hosted lane, and nothing at all
    /// on the persistent self-hosted lane.
    fn both_runner_docker_config() -> (ProjectConfig, usize) {
        let root = temporary_repository("docker-seed");
        must(
            fs::write(root.join("Dockerfile"), "FROM scratch\n"),
            "write Dockerfile",
        );
        // The scan refuses a Both-runners repository that declares no
        // self-hosted labels; the seed lifecycle test needs both lanes, so the
        // labels are declared the way a generation config would.
        let mut config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan Docker repository",
        );
        config.selectors.insert(
            ProviderId::Velnor,
            provider::ProviderSelector {
                runs_on: vec!["self-hosted".to_owned(), "pool".to_owned()],
            },
        );
        config.providers = all_providers();
        config.automatic_providers = all_providers();
        let index = must_some(
            config
                .units
                .iter()
                .position(|unit| unit.kind == UnitKind::Docker),
            "scanned Docker unit",
        );
        config.units[index].pr_commands = vec![
            "docker buildx build --load --target ci --file 'Dockerfile' --tag local-ci:dockerfile '.'"
                .to_owned(),
        ];
        config.units[index].full_commands = vec![
            "docker buildx build --load --cache-from type=gha,scope=example-docker --file 'Dockerfile' --tag local-ci:dockerfile --build-context velnor-cache-seed='.velnor-docker-cache/seed' '.'".to_owned(),
            "docker buildx build --target velnor-cache-export --output type=local,dest=.velnor-docker-cache/export --file 'Dockerfile' '.'".to_owned(),
        ];
        config.units[index].cache = Some(CacheSpec {
            key_files: vec!["Cargo.lock".to_owned(), "Dockerfile".to_owned()],
            paths: vec![MUTABLE_MOUNT_HOST_DIR.to_owned()],
            purpose: CachePurpose::Generic,
            mbx_output_cache_justification: None,
            mutable_mount_seed: true,
        });
        (config, index)
    }

    #[test]
    fn docker_named_context_materializes_every_provider_lane() {
        let (mut config, index) = both_runner_docker_config();
        config.units[index].docker_contexts = vec![DockerContext {
            name: "checkout".to_owned(),
            path: ".".to_owned(),
        }];
        let root = temporary_repository("docker-context-lanes");
        must(
            materialize_capability_commands(&mut config, &root),
            "materialize Docker contexts across schema-2 lanes",
        );
        let unit = &config.units[index];
        for (lane, commands) in [
            ("pull request", &unit.pr_commands),
            ("full", &unit.full_commands),
        ] {
            assert!(!commands.is_empty(), "{lane} lane must have a command");
            assert!(
                commands
                    .iter()
                    .all(|command| command.contains("--build-context checkout='.'")),
                "every {lane} Docker command must carry the typed context: {commands:?}"
            );
        }
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn docker_seed_commands_carry_the_github_token_build_secret() {
        let pr = docker_seed_pull_request_command(
            "docker buildx build --load --target ci --file 'Dockerfile' --tag local-ci:dockerfile '.'",
            "example-docker",
        );
        assert!(
            pr.contains(DOCKER_BUILD_GITHUB_TOKEN_SECRET),
            "seeded PR commands authenticate mise provisioning: {pr}"
        );
        assert_eq!(
            docker_seed_pull_request_command(&pr, "example-docker")
                .matches(DOCKER_BUILD_GITHUB_TOKEN_SECRET)
                .count(),
            1,
            "reseeding never duplicates the secret: {pr}"
        );
        let full = docker_seed_full_command(
            "docker buildx build --load --file 'Dockerfile' --tag local-ci:dockerfile '.'",
            "example-docker",
        );
        assert!(
            full.contains(DOCKER_BUILD_GITHUB_TOKEN_SECRET),
            "seeded full commands authenticate mise provisioning: {full}"
        );
        assert_eq!(
            docker_seed_full_command(&full, "example-docker")
                .matches(DOCKER_BUILD_GITHUB_TOKEN_SECRET)
                .count(),
            1,
            "reseeding never duplicates the secret: {full}"
        );
    }

    #[test]
    fn docker_materialized_commands_all_carry_the_build_secret() {
        let (mut config, index) = both_runner_docker_config();
        // Unseeded full commands: materialization seeds them and appends the
        // cache-export build, and every one must carry the token secret.
        config.units[index].full_commands =
            vec!["docker build --file 'Dockerfile' --tag local-ci:dockerfile '.'".to_owned()];
        let root = temporary_repository("docker-token-secret");
        must(
            materialize_capability_commands(&mut config, &root),
            "materialize",
        );
        for command in config.units[index]
            .pr_commands
            .iter()
            .chain(config.units[index].full_commands.iter())
        {
            assert!(
                command.contains(DOCKER_BUILD_GITHUB_TOKEN_SECRET),
                "every materialized docker command carries the secret: {command}"
            );
        }
        assert_eq!(config.units[index].full_commands.len(), 2);
        assert!(
            config.units[index].full_commands[1].contains("velnor-cache-export"),
            "the export build is materialized: {:?}",
            config.units[index].full_commands
        );
        let _ = fs::remove_dir_all(root);
    }

    #[test]
    fn collapsed_trust_gated_docker_renders_the_trusted_verify_job() {
        let (mut config, index) = both_runner_docker_config();
        config.units[index].trust = provider::TrustReq::TrustedOnly;
        let rendered = must_some(
            must(
                WorkflowIr::from_config(&config).render_kind_unit_workflow(UnitKind::Docker, None),
                "render docker kind reusable",
            ),
            "docker kind has members",
        )
        .1;
        assert!(
            rendered.contains("verify-velnor-trusted:"),
            "a trusted-only docker unit renders the trusted collapsed verify job: {rendered}"
        );
        assert!(
            !rendered.contains("\n  verify-velnor:\n"),
            "no untrusted split exists for a trusted-only unit: {rendered}"
        );
        assert!(
            rendered.contains("github.event.pull_request.head.repo.fork"),
            "the trusted job gates on the event: {rendered}"
        );
    }

    #[test]
    fn docker_mutable_mount_seed_renders_restore_seed_and_trusted_export() {
        let (config, index) = both_runner_docker_config();
        must(
            primitives::validate_mutable_mount_seed(&config.units[index]),
            "a seed-consumed-and-extracted build declares a valid lifecycle",
        );

        let ir = WorkflowIr::from_config(&config);
        let unit = &config.units[index];
        let contract = UnitContract {
            providers: WorkflowIr::default_provider_jobs(&config.providers, true),
            timeout_minutes: DEFAULT_UNIT_TIMEOUT_MINUTES,
            cache: CacheBackend::Detected,
            cache_save: true,
            mutable_mount_seed: true,
        };
        let mut contracts = BTreeMap::new();
        contracts.insert(unit.id.clone(), contract);
        let rendered = must_some(
            must(
                ir.render_kind_unit_workflow(UnitKind::Docker, Some(&contracts)),
                "render docker kind reusable",
            ),
            "docker kind has members",
        )
        .1;

        let restore = must_some(
            rendered.find("Restore Docker build seed"),
            "seed restore rendered",
        );
        let prepare = must_some(
            rendered.find("Prepare Docker build seed context"),
            "seed context preparation rendered",
        );
        let run = must_some(rendered.find("Run unit checks"), "checks step rendered");
        let collect = must_some(
            rendered.find("Collect Docker mutable-cache export"),
            "export collection rendered",
        );
        let save = must_some(
            rendered.find("Save Docker build seed"),
            "seed save rendered",
        );
        assert!(restore < prepare && prepare < run && run < collect && collect < save);

        // Both collection and save are trusted-event surfaces; an untrusted
        // pull request restores and builds but never writes seed state.
        assert!(rendered.contains(
            "Collect Docker mutable-cache export\n        if: (github.event_name == 'push' && github.ref == 'refs/heads/main')"
        ));
        // The save gate wraps the trusted expression and adds the restore
        // outcome: an exact-key hit means the seed is already current, so
        // re-saving under an immutable key would write nothing new.
        assert!(rendered.contains("Save Docker build seed\n        if: always() && ("));
        assert!(rendered.contains("&& steps.cache.outputs.cache-hit != 'true'"));

        // The export collection refuses a partial export instead of seeding
        // the next builder with less than the declared contract.
        assert!(rendered.contains("Docker cache export is missing"));

        // One namespace for the Docker seed, distinct from the unit-lane mbx
        // keys. The collapsed job keys the seed from the caller's inputs, so
        // the key carries input expressions instead of literals.
        assert!(rendered.contains("velnor-docker-seed-"));
        assert!(!rendered.contains("velnor-mbx-"));

        // The local provider job carries no seed transport at all: the seed
        // lifecycle is a hosted build contract.
        let velnor = must_some(
            rendered
                .find("\n  verify-velnor:\n")
                .map(|index| &rendered[index..]),
            "velnor verify job rendered",
        );
        assert!(!velnor.contains("velnor-docker-seed-"));
        assert!(!velnor.contains("Collect Docker mutable-cache export"));
    }

    /// A declared seed the declared builds never consume is the exact
    /// "declared persistence that does not exist" this contract exists to
    /// remove, so every gap is a usage error with the missing direction named.
    #[test]
    fn mutable_mount_seed_validation_rejects_unconsumed_declarations() {
        let docker_unit = |mutate: &dyn Fn(&mut Unit)| {
            let root = temporary_repository("docker-seed-invalid");
            must(
                fs::write(root.join("Dockerfile"), "FROM scratch\n"),
                "write Dockerfile",
            );
            let mut config = must(
                scan_repository(
                    &root,
                    Some(std::collections::BTreeSet::from([
                        crate::s2::provider::ProviderId::GithubHosted,
                    ])),
                ),
                "scan Docker repository",
            );
            let index = must_some(
                config
                    .units
                    .iter()
                    .position(|unit| unit.kind == UnitKind::Docker),
                "scanned Docker unit",
            );
            config.units[index].cache = Some(CacheSpec {
                key_files: vec!["Dockerfile".to_owned()],
                paths: vec![MUTABLE_MOUNT_HOST_DIR.to_owned()],
                purpose: CachePurpose::Generic,
                mbx_output_cache_justification: None,
                mutable_mount_seed: true,
            });
            mutate(&mut config.units[index]);
            config.units[index].clone()
        };
        let full_commands = vec![
            "docker buildx build --load --file 'Dockerfile' --build-context velnor-cache-seed='.velnor-docker-cache/seed' '.'".to_owned(),
            "docker buildx build --target velnor-cache-export --output type=local,dest=.velnor-docker-cache/export --file 'Dockerfile' '.'".to_owned(),
        ];

        // A hosted full build that never injects the seed.
        let unit = docker_unit(&|unit: &mut Unit| {
            unit.full_commands = vec![full_commands[1].clone()];
        });
        let error = must_fail(
            primitives::validate_mutable_mount_seed(&unit),
            "a seed no build injects must be rejected",
        );
        assert!(error.to_string().contains("--build-context"), "{error}");

        // A hosted full build that injects but never extracts.
        let unit = docker_unit(&|unit: &mut Unit| {
            unit.full_commands = vec![full_commands[0].clone()];
        });
        let error = must_fail(
            primitives::validate_mutable_mount_seed(&unit),
            "a seed no build extracts must be rejected",
        );
        assert!(error.to_string().contains("velnor-cache-export"), "{error}");

        // Extraction on an untrusted pull-request lane writes seed state from
        // unreviewed code, so the declaration is refused outright.
        let unit = docker_unit(&|unit: &mut Unit| {
            unit.full_commands = full_commands.clone();
            unit.pr_commands = vec![full_commands[1].clone()];
        });
        let error = must_fail(
            primitives::validate_mutable_mount_seed(&unit),
            "a pull-request extraction must be rejected",
        );
        assert!(error.to_string().contains("pull-request"), "{error}");

        // The seed contract is a Docker image build contract; nothing else
        // owns cache mounts a seed can be injected into.
        let root = scanned_fixture(all_providers());
        let mut config = root;
        let index = must_some(
            config
                .units
                .iter()
                .position(|unit| unit.kind == UnitKind::Rust),
            "scanned Rust unit",
        );
        config.units[index].cache = Some(CacheSpec {
            key_files: vec!["Cargo.lock".to_owned()],
            paths: vec![MUTABLE_MOUNT_HOST_DIR.to_owned()],
            purpose: CachePurpose::Generic,
            mbx_output_cache_justification: None,
            mutable_mount_seed: true,
        });
        let error = must_fail(
            primitives::validate_mutable_mount_seed(&config.units[index]),
            "a non-Docker seed must be rejected",
        );
        assert!(error.to_string().contains("Docker image build"), "{error}");
    }

    /// Cache namespaces partition by surface: unit lanes restore the unit
    /// mbx keys, the Docker seed restores the seed keys, and neither surface
    /// can restore the other's state. The release-family keys are repo-owned
    /// template bytes, so the crate boundary this test pins is the one the
    /// generator renders.
    #[test]
    fn cache_namespaces_partition_unit_lanes_from_the_docker_seed() {
        let config = scanned_fixture(all_providers());
        let _rust = must_some(
            config.units.iter().find(|unit| unit.kind == UnitKind::Rust),
            "scanned Rust unit",
        );
        let nested = must_some(
            must(
                WorkflowIr::from_config(&config).render_kind_unit_workflow(UnitKind::Rust, None),
                "render rust kind reusable",
            ),
            "rust kind has members",
        )
        .1;
        assert!(nested.contains("velnor-mbx-"), "{nested}");
        assert!(!nested.contains("velnor-docker-seed-"), "{nested}");
        assert!(!nested.contains("velnor-release-mbx-"), "{nested}");
        assert!(static_mr_boxington_step().contains("velnor-static-mbx-"));
    }

