    /// The `id:` job body a generated aggregate renders, from the job key
    /// through the line before the next top-level job.
    fn yaml_job<'a>(workflow: &'a str, id: &str) -> &'a str {
        let header = format!("  {id}:");
        let mut start = None;
        let mut end = None;
        let mut offset = 0;
        for line in workflow.split_inclusive('\n') {
            let content = line.trim_end_matches('\n');
            if start.is_none() {
                if content == header {
                    start = Some(offset);
                }
            } else if content.starts_with("  ")
                && !content.starts_with("   ")
                && content.ends_with(':')
            {
                end = Some(offset);
                break;
            }
            offset += line.len();
        }
        let start = must_some(start, &format!("{id} job"));
        must_some(
            workflow.get(start..end.unwrap_or(workflow.len())),
            &format!("{id} job bytes"),
        )
    }

    #[test]
    fn generated_planning_follows_a_velnor_only_universe_without_the_hosted_aggregate_runtime() {
        let config = scanned_fixture(provider_set([ProviderId::Velnor]));
        let files = must(generated_files(&config), "generate");
        let workflow = must_some(
            files.get(&PathBuf::from(".github/workflows/ci-main.yml")),
            "generated ci-main.yml",
        );
        let plan = yaml_job(workflow, "plan");
        let lane = fixture_lane_selector();
        let plan_runs_on: Vec<&str> = plan
            .lines()
            .filter(|line| line.trim_start().starts_with("runs-on:"))
            .map(str::trim)
            .collect();
        assert_eq!(
            plan_runs_on.as_slice(),
            [lane.as_str()],
            "Planning follows a Velnor-only universe onto Velnor: {plan}"
        );
        assert!(
            plan.contains("github.event.pull_request.head.repo.fork"),
            "a local control plane carries the trusted-event gate: {plan}"
        );
        assert!(
            !plan.contains("name: Prepare Velnor workflow runtime"),
            "a local plan prepares no runtime artifact: ci-required scores ambient: {plan}"
        );
        assert!(
            !plan.contains("name: Publish Velnor workflow runtime"),
            "a local plan publishes no runtime artifact: ci-required scores ambient: {plan}"
        );
        let all_runs_on: Vec<&str> = workflow
            .lines()
            .filter(|line| line.trim_start().starts_with("runs-on:"))
            .map(str::trim)
            .collect();
        for runs_on in &all_runs_on {
            assert_eq!(
                *runs_on, lane,
                "only control-plane jobs render runs-on, on Velnor: {workflow}"
            );
        }
        for (path, content) in &files {
            let name = must_some(path.file_name(), "workflow file name");
            let name = must_some(name.to_str(), "workflow file name utf-8");
            if name.starts_with("ci-unit-") {
                assert!(
                    content.contains(&fixture_lane_selector()),
                    "{name} unit jobs must stay on config.runners"
                );
                assert!(
                    !content.contains("runs-on: ubuntu-24.04"),
                    "{name} must not emit a GitHub lane when runners=velnor"
                );
            }
        }
    }

