    #[test]
    fn selection_file_consumes_the_csv_unit_ids_channel_not_plan_json() {
        // Flip bug #2: plan `units` is JSON for `contains()` needles, but the
        // reusable once fed it raw into the selection file's CSV-only `units=`
        // field, so `run` failed closed in every executed leg. The plan now
        // emits the same affected set as CSV `unit_ids`, and the emitter
        // threads it through `selected_unit_ids` into `units=` — one format
        // per channel end to end.
        let config = scanned_fixture(all_providers());
        let files = must(generated_files(&config), "generate");
        let root = must_some(
            files.get(&PathBuf::from(".github/workflows/ci-pr.yml")),
            "root workflow",
        );
        let rust_unit = must_some(
            config.units.iter().find(|unit| unit.kind == UnitKind::Rust),
            "Rust fixture unit",
        );
        assert!(
            root.contains("      unit_ids: ${{ steps.plan.outputs.unit_ids }}"),
            "plan must expose the CSV unit_ids output:\n{root}"
        );
        let json_feeds = root
            .matches("selected_units: ${{ needs.plan.outputs.units }}")
            .count();
        let csv_feeds = root
            .matches("selected_unit_ids: ${{ needs.plan.outputs.unit_ids }}")
            .count();
        assert!(
            csv_feeds > 0 && csv_feeds == json_feeds,
            "every caller passing the JSON channel must pass the CSV channel too ({csv_feeds} vs {json_feeds}):\n{root}"
        );
        let crate_workflow = must_some(
            files
                .iter()
                .find(|(path, _)| {
                    path.as_path()
                        == PathBuf::from(".github/workflows")
                            .join(nested_unit_workflow_file(rust_unit))
                            .as_path()
                })
                .map(|(_, content)| content),
            "Rust crate workflow",
        );
        assert!(
            crate_workflow.contains("selected_unit_ids:\n        required: true"),
            "the reusable must declare the CSV input:\n{crate_workflow}"
        );
        assert!(
            crate_workflow.contains("SELECTION_UNITS: ${{ inputs.selected_unit_ids }}"),
            "the selection file must materialize units= from the CSV input:\n{crate_workflow}"
        );
        assert!(
            !crate_workflow.contains("SELECTION_UNITS: ${{ inputs.selected_units }}"),
            "plan JSON must never feed the CSV-only units= field:\n{crate_workflow}"
        );
        assert!(
            crate_workflow.contains("contains(inputs.selected_units"),
            "callee gates still match the JSON channel:\n{crate_workflow}"
        );
    }

    #[test]
    fn rust_kind_reusable_size_is_independent_of_unit_count() {
        let scanned = must(
            scan_target(
                &fixture_root(),
                Some(provider_set([ProviderId::GithubHosted])),
                "main",
            ),
            "scan fixture for rust kind reusable sizing",
        );
        let mut config = scanned.config;
        // A machinery test: the public fixture scans hosted, then the
        // universe is overridden to all providers for the sizing shape.
        config.providers = all_providers();
        config.automatic_providers = all_providers();
        config.selectors.insert(
            ProviderId::Velnor,
            provider::ProviderSelector {
                runs_on: FIXTURE_LABELS
                    .iter()
                    .map(|label| (*label).to_owned())
                    .collect(),
            },
        );
        let rust = must_some(
            config
                .units
                .iter()
                .find(|unit| unit.kind == UnitKind::Rust)
                .cloned(),
            "fixture rust unit",
        );
        let baseline = must(
            generated_files_with_surface(&config, None),
            "generate the baseline surface",
        );
        let baseline_rust = must_some(
            baseline.get(&PathBuf::from(".github/workflows/ci-unit-rust.yml")),
            "baseline rust kind reusable",
        );
        // GitHub loads the callee once per caller into one template-memory
        // budget, so the callee must not grow with the kind's unit count.
        // 17 three-provider rust units (51 callers) stay under the 8 MiB
        // ceiling the generator enforces on the aggregate; the ceiling
        // itself is covered by `template_memory`'s tests. The drift since
        // the three-provider cutover (dependency records, hardened
        // transfers, per-phase checks steps, unit-result record/upload
        // blocks, expected-work aggregate steps) honestly costs the
        // headroom the old 25-unit stress level consumed.
        for index in 0..16 {
            let mut unit = rust.clone();
            unit.id = format!("rust-pad{index:02}");
            unit.label = format!("Rust crate (pad{index:02})");
            config.units.push(unit);
        }
        let padded = must(
            generated_files_with_surface(&config, None),
            "generate the padded surface",
        );
        let padded_rust = must_some(
            padded.get(&PathBuf::from(".github/workflows/ci-unit-rust.yml")),
            "padded rust kind reusable",
        );
        assert!(
            !padded.contains_key(&PathBuf::from(".github/workflows/ci-unit-rust-2.yml")),
            "kind reusables are never sharded"
        );
        assert!(
            !padded_rust.contains("inputs.unit == '"),
            "the collapsed provider jobs must not guard steps by unit identity"
        );
        // The prepare-cargo job gate enumerates the restricted units (one
        // expression); every step block is rendered once per lane job.
        let growth = padded_rust.len().saturating_sub(baseline_rust.len());
        assert!(
            growth < 32 * 256,
            "the kind reusable grew by {growth} bytes for 16 extra units; the step blocks must not be per unit"
        );
        for name in ["ci-pr.yml", "ci-main.yml"] {
            let workflow = must_some(
                padded.get(&PathBuf::from(".github/workflows").join(name)),
                name,
            );
            assert!(
                workflow.contains("  github-hosted-rust-pad00:")
                    && workflow.contains("  github-self-hosted-rust-pad00:")
                    && workflow.contains("  velnor-rust-pad00:"),
                "{name} must declare per-(unit,provider) callers for the padded units:\n{workflow}"
            );
            assert!(
                !workflow.contains("ci-unit-rust-2.yml"),
                "{name} must call the single rust kind reusable:\n{workflow}"
            );
            assert!(
                workflow.contains("rust_matrix"),
                "{name} plan must expose rust_matrix:\n{workflow}"
            );
        }
    }

    #[test]
    fn plan_consumes_the_static_automatic_providers() {
        let config = scanned_fixture(all_providers());
        let generator = WorkflowIr::from_config(&config);
        // Every event selects the static automatic set: no provider input
        // survives to read.
        let automatic = config
            .automatic_providers
            .iter()
            .map(provider::ProviderId::as_str)
            .collect::<Vec<_>>()
            .join(",");
        let consumer = format!("VELNOR_PROVIDERS: {automatic}");
        for aggregate in [
            generator.render_nested(WorkflowKind::PullRequest, &legacy_plan(&generator), None),
            generator.render_nested(WorkflowKind::Main, &legacy_plan(&generator), None),
            generated_ci_main(&generator),
        ] {
            assert!(aggregate.contains(&consumer), "{aggregate}");
            assert!(
                !aggregate.contains("inputs.providers"),
                "no dispatch input selects providers: {aggregate}"
            );
            // The consumer sits in the plan step.
            let plan = must_some(aggregate.find("  plan:"), "plan job");
            let providers_env = must_some(aggregate.find(consumer.as_str()), "plan providers env");
            assert!(plan < providers_env, "{aggregate}");
        }
        // Single-provider universes narrow the value to the one provider.
        for (providers, expected) in [
            (
                provider_set([ProviderId::GithubHosted]),
                "VELNOR_PROVIDERS: github-hosted",
            ),
            (
                provider_set([ProviderId::Velnor]),
                "VELNOR_PROVIDERS: velnor",
            ),
        ] {
            let config = scanned_fixture(providers);
            let generator = WorkflowIr::from_config(&config);
            for aggregate in [
                generator.render_nested(WorkflowKind::PullRequest, &legacy_plan(&generator), None),
                generator.render_nested(WorkflowKind::Main, &legacy_plan(&generator), None),
            ] {
                assert!(aggregate.contains(expected), "{aggregate}");
            }
        }
    }

