    #[cfg(unix)]
    #[test]
    fn generated_runner_tests_each_cargo_package_manifest() {
        let root = temporary_repository("test-crates");
        let core = root.join("crates/core");
        let app = root.join("crates/app");
        must(fs::create_dir_all(&core), "create core crate");
        must(fs::create_dir_all(&app), "create app crate");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[workspace]\nmembers = [\"crates/core\", \"crates/app\"]\n",
            ),
            "write workspace manifest",
        );
        for (directory, name) in [(&core, "core"), (&app, "app")] {
            must(
                fs::write(
                    directory.join("Cargo.toml"),
                    format!("[package]\nname = \"{name}\"\nversion = \"0.1.0\"\n"),
                ),
                "write package manifest",
            );
        }

        let bin = root.join("fake-bin");
        must(fs::create_dir_all(&bin), "create fake binary directory");
        let calls = root.join("cargo-calls");
        let fake_cargo = bin.join("cargo");
        must(
            fs::write(
                &fake_cargo,
                format!(
                    "#!/usr/bin/env bash\nprintf '%s\\n' \"$*\" >> {}\n",
                    shell_quote(&calls.to_string_lossy())
                ),
            ),
            "write fake cargo",
        );
        must(
            fs::set_permissions(
                &fake_cargo,
                std::os::unix::fs::PermissionsExt::from_mode(0o755),
            ),
            "make fake cargo executable",
        );

        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan test workspace",
        );
        must(
            fs::create_dir_all(root.join(".github/ci")),
            "create CI directory",
        );
        must(
            fs::write(root.join(".github/ci/project.toml"), config.toml()),
            "write CI configuration",
        );
        must(
            runtime::test_crates(
                &root,
                &root.join(".github/ci/project.toml"),
                Some(&fake_cargo),
            ),
            "run per-crate test fanout",
        );
        let calls = must(fs::read_to_string(calls), "read fake cargo calls");
        let package_calls = calls
            .lines()
            .filter(|call| call.contains("--manifest-path"))
            .collect::<Vec<_>>();
        assert_eq!(package_calls.len(), 2);
        assert!(package_calls
            .iter()
            .all(|call| !call.contains("--workspace")));
        assert!(calls
            .lines()
            .any(|call| call.ends_with("/crates/core/Cargo.toml")));
        assert!(calls
            .lines()
            .any(|call| call.ends_with("/crates/app/Cargo.toml")));

        let _ = fs::remove_dir_all(root);
    }

    /// The policy job checks out the base repository's full history and then
    /// fetches the audited head into it, so pin ancestry against the base
    /// branch is decidable for same-repository and fork pull requests alike.
    #[test]
    fn policy_job_checks_out_full_history_and_the_audited_head() {
        for job in [
            hosted_policy_job("revision"),
            velnor_policy_job("revision", "[self-hosted, velnor]"),
        ] {
            assert!(job.contains("          fetch-depth: 0\n"), "{job}");
            assert!(
                job.contains("          persist-credentials: false\n"),
                "{job}"
            );
            assert!(job.contains("path: policy-checkout"), "{job}");
            assert!(!job.contains("allow-unsafe-pr-checkout"), "{job}");
            assert!(
                !job.contains("          repository: ${{ github.event.pull_request.head.repo"),
                "the checkout is the base repository; the head is fetched into it: {job}"
            );
            assert!(
                job.contains(
                    "git fetch --no-tags \"$GITHUB_SERVER_URL/$HEAD_REPOSITORY\" \"$HEAD_SHA\""
                ),
                "{job}"
            );
            assert!(
                job.contains("git checkout --quiet --detach \"$HEAD_SHA\""),
                "{job}"
            );
            assert!(
                job.contains("--head-sha \"$HEAD_SHA\"")
                    && job.contains("--base-sha \"$BASE_SHA\""),
                "the validator receives explicit head and base commits: {job}"
            );
            assert!(
                job.contains("BASE_SHA: ${{ github.event.pull_request.base.sha || github.sha }}"),
                "{job}"
            );
            assert!(job.contains("timeout-minutes: 20"), "{job}");
        }
    }

    /// The owner policy job runs the setup action from its own checkout
    /// (`./…`) while checking the repository out only under
    /// `policy-checkout/`: without a second checkout the setup step's `uses:`
    /// cannot resolve and the job dies at setup. The sparse checkout ahead of
    /// it provisions exactly the composite action directory from the BASE
    /// tree under the sibling `policy-setup-action/` — never the PR head,
    /// and never resolved out of `policy-checkout/`, either of which would
    /// execute fork-controlled action code under `pull_request_target`.
    /// Consumers pin the published action and the Velnor lane provisions its
    /// slot, so neither carries this checkout.
    #[test]
    fn owner_policy_job_checks_out_base_setup_action_before_setup() {
        let owner = hosted_policy_job("abc123");
        let checkout = must_some(
            owner.find("      - name: Check out base setup action\n"),
            "the owner policy job checks out the base setup action",
        );
        let setup = must_some(
            owner.find(&format!("uses: {VELNOR_WORKFLOW_POLICY_SETUP_ACTION}\n")),
            "the owner setup step runs the local composite out of the sibling checkout",
        );
        assert!(
            checkout < setup,
            "the sibling checkout precedes the setup step: {owner}"
        );
        let block = &owner[checkout..setup];
        assert!(
            block.contains(&format!("uses: {}\n", ActionPin::Checkout.reference())),
            "the sibling checkout pins actions/checkout: {owner}"
        );
        assert!(
            block.contains("ref: ${{ github.event.pull_request.base.sha || github.sha }}\n"),
            "the sibling checkout pins the BASE tree: {owner}"
        );
        assert!(
            block.contains("path: policy-setup-action\n"),
            "the sibling checkout lands beside the audited tree, never at the root: {owner}"
        );
        assert!(
            !block.contains("head.sha"),
            "the sibling checkout never names the PR head: {owner}"
        );
        assert!(
            block.contains("sparse-checkout: .github/actions/setup-velnor-workflow\n"),
            "the sibling checkout provisions exactly the composite directory: {owner}"
        );
        assert!(
            block.contains("fetch-depth: 1\n"),
            "the sibling checkout is shallow: {owner}"
        );
        assert!(
            block.contains("persist-credentials: false\n"),
            "the sibling checkout persists no credentials: {owner}"
        );
        assert!(
            !owner.contains("policy-checkout/.github/actions"),
            "the setup action never resolves out of the audited tree: {owner}"
        );
        for job in [
            hosted_policy_job_for_repository("abc123", "example/consumer"),
            velnor_policy_job("abc123", "[self-hosted, velnor]"),
        ] {
            assert!(
                !job.contains("Check out base setup action"),
                "only the owner lane checks out the setup action: {job}"
            );
            assert!(!job.contains("sparse-checkout"), "{job}");
        }
    }

    /// Every checkout in the owner policy job lands in a sibling directory:
    /// a root checkout wipes `policy-checkout/` under `clean: true` and the
    /// Acquire step then dies with "No such file or directory". The setup
    /// step resolves the composite out of the sibling checkout.
    #[test]
    fn owner_policy_job_never_checks_out_workspace_root() {
        let owner = hosted_policy_job("abc123");
        let checkout = format!("uses: {}\n", ActionPin::Checkout.reference());
        let mut checkouts = 0;
        for step in owner.split("      - name: ").skip(1) {
            if step.contains(&checkout) {
                checkouts += 1;
                assert!(
                    step.contains("\n          path: "),
                    "every policy-job checkout carries a path, never the root: {step}"
                );
            }
        }
        assert_eq!(checkouts, 2, "history plus base setup action: {owner}");
        assert!(
            owner.contains(&format!("uses: {VELNOR_WORKFLOW_POLICY_SETUP_ACTION}\n")),
            "the setup step resolves out of the sibling checkout: {owner}"
        );
    }

    /// No generated policy job passes `--pin-build`: an unprovisioned pin
    /// fails closed in every lane. Only hosted jobs resolve the live ruleset.
    #[test]
    fn no_policy_job_builds_pull_request_code() {
        let velnor = velnor_policy_job("revision", "[self-hosted, velnor]");
        assert!(!velnor.contains("--pin-build"), "{velnor}");
        assert!(!velnor.contains("--ruleset-contexts"), "{velnor}");
        assert!(!velnor.contains("gh api"), "{velnor}");
        let hosted = hosted_policy_job("revision");
        assert!(!hosted.contains("--pin-build"), "{hosted}");
        assert!(
            hosted.contains("--ruleset-contexts \"$RULESET_CONTEXTS\""),
            "{hosted}"
        );
        assert!(
            hosted.contains("gh api \"repos/$GITHUB_REPOSITORY/rulesets?includes_parents=true\""),
            "{hosted}"
        );
        assert!(
            hosted.contains("GH_TOKEN: ${{ github.token }}") && !hosted.contains("${{ secrets."),
            "the ruleset lookup uses the job token, never a secret expression: {hosted}"
        );
        assert!(
            hosted.contains("DECLARED_RULESET_CONTEXTS: ci-required,DCO,Policy"),
            "{hosted}"
        );
        assert!(
            hosted.contains("falling back to declared contexts"),
            "{hosted}"
        );
    }

    #[test]
    fn policy_job_acquires_validator_product_without_compiling() {
        let policy = hosted_policy_job("abc123");
        assert!(!policy.contains("cargo install"), "{policy}");
        assert!(!policy.contains("cargo build"), "{policy}");
        assert!(!policy.contains("RUSTC_WRAPPER"), "{policy}");
        assert!(!policy.contains("Mr. Boxington"), "{policy}");
        assert!(!policy.contains("CACHED_POLICY_RUNTIME"));
        assert!(!policy.contains("STAGED_POLICY_RUNTIME"));
        assert!(!policy.contains("ln -sf"));
        assert!(
            policy.contains("      - name: Set up Velnor workflow runtime\n"),
            "{policy}"
        );
        assert!(policy.contains("          rev: abc123\n"), "{policy}");
        assert!(
            !policy.contains("Acquire candidate generator product"),
            "active policy must not discover a PR-produced candidate: {policy}"
        );
        assert!(
            policy.contains(&format!("{VELNOR_POLICY_REVISION_ENV}: abc123")),
            "{policy}"
        );
        let consumer = hosted_policy_job_for_repository("abc123", "example/consumer");
        assert!(!consumer.contains("cargo install"), "{consumer}");
        assert!(!consumer.contains("cargo build"), "{consumer}");
        assert!(
            consumer.contains("Read declared generator pin"),
            "{consumer}"
        );
        assert!(
            consumer.contains("Set up declared generator product"),
            "{consumer}"
        );
        assert!(
            !consumer.contains("Acquire candidate generator product"),
            "{consumer}"
        );
        for job in [policy, consumer] {
            assert!(
                !job.contains("ci-pr.yml"),
                "policy never looks up PR runs: {job}"
            );
            assert!(
                !job.contains("gh run"),
                "policy never discovers a producer run: {job}"
            );
            assert!(
                !job.contains("sleep "),
                "policy never polls with sleeps: {job}"
            );
            assert!(
                !job.contains("candidate-manifest")
                    && !job.contains("VELNOR_WORKFLOW_CANDIDATE_MANIFEST")
                    && !job.contains("--candidate-manifest"),
                "policy never transports a candidate manifest: {job}"
            );
        }
    }

    #[test]
    fn no_generated_file_passes_pin_build() {
        // `--pin-build` is a local-development escape hatch on both CLIs; no
        // generated file may pass it, or an unprovisioned pin would silently
        // compile inside CI instead of failing closed.
        for repository in [workflow_setup_action_repository(), "example/consumer"] {
            let mut config = scanned_fixture(all_providers());
            config.repository = repository.to_owned();
            let files = must(generated_files(&config), "generate");
            assert!(!files.is_empty(), "the surface renders");
            for (path, content) in &files {
                assert!(
                    !content.contains("--pin-build"),
                    "{} renders --pin-build for {repository}",
                    path.display()
                );
            }
        }
    }

    /// Every file the schema-2 pipeline renders for this repository: the
    /// scan, surface, and file stages of `run` without the write.
    fn rendered_repository_files() -> BTreeMap<PathBuf, String> {
        let root = must(
            fs::canonicalize(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")),
            "repository root",
        );
        let default_branch = must(resolve_default_branch(&root), "resolve default branch");
        let scanned = must(
            scan_target(&root, None, &default_branch),
            "scan this repository",
        );
        let mut config = scanned.config;
        let surface = must(
            crate::s2::primitives::generate(
                &root,
                &scanned.shape,
                &config,
                scanned.generation.as_ref(),
            ),
            "render declared surface",
        );
        config.units.clone_from(&surface.units);
        for file in &surface.added_files {
            if !config.workflow_files.contains(file) {
                config.workflow_files.push(file.clone());
            }
        }
        must(
            generated_files_with_surface(&config, Some(&surface)),
            "render this repository's generated files",
        )
    }

    /// The schema-2 pipeline refuses a schema-1 repository: the dogfood
    /// tree flipped to schema 2 (R2m), so the refusal now runs against a
    /// synthetic schema-1 config instead of the repository itself. The
    /// scan must fail closed on the foreign config instead of rendering
    /// a mixed surface.
    #[test]
    fn schema2_pipeline_refuses_a_schema1_repository() {
        let root = configured_repository(
            "schema1-refusal",
            Some(
                "schema = 1\n\n[generator]\nrepository = \"example/fixture\"\n\n\
                 [workflow]\nrunners = \"both\"\n",
            ),
        );
        let error = must_fail(
            scan_target(
                &root,
                Some(crate::s2::provider::ProviderId::ALL.into_iter().collect()),
                "main",
            ),
            "scanning a schema-1 repository with the schema-2 pipeline must fail",
        );
        assert!(
            error.to_string().contains("invalid generation config"),
            "the refusal must reject the schema-1 config: {error}"
        );
        let _ = fs::remove_dir_all(root);
    }

    /// The checked-in workflows are byte-identical to what the schema-2
    /// pipeline renders for this repository: regeneration is a fixed
    /// point, so a template change without its regen (or a hand-edit)
    /// fails here before it fails in CI. The harness renders the
    /// repository's own surface the way `run` renders it, which makes
    /// comparing every workflow trivial — including the shared policy
    /// job in `ci-policy.yml` and `ci-main.yml`.
    #[test]
    fn checked_in_workflows_match_the_generator_byte_for_byte() {
        let root = must(
            fs::canonicalize(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")),
            "repository root",
        );
        let files = rendered_repository_files();
        let entries = must(
            fs::read_dir(root.join(".github/workflows")),
            "read checked-in workflows",
        );
        let mut checked_in = 0;
        for entry in entries {
            let path = must(entry, "workflow entry").path();
            if path.extension().is_none_or(|extension| extension != "yml") {
                continue;
            }
            let name = must_some(
                path.file_name().and_then(|name| name.to_str()),
                "workflow file name",
            )
            .to_owned();
            let disk = must(fs::read_to_string(&path), &format!("read {name}"));
            let rendered = must_some(
                files.get(&PathBuf::from(".github/workflows").join(&name)),
                &format!("the generator renders {name}"),
            );
            assert_eq!(rendered, &disk, "{name} drifted from the generator");
            checked_in += 1;
        }
        assert!(checked_in > 0, "the repository checks in workflows");
        for path in files.keys() {
            if path.starts_with(".github/workflows")
                && path.extension().is_some_and(|extension| extension == "yml")
            {
                assert!(
                    root.join(path).is_file(),
                    "{} is rendered but not checked in",
                    path.display()
                );
            }
        }
    }

