    #[test]
    fn raw_output_caches_alongside_mr_boxington_need_a_justification() {
        let mut config = scanned_fixture(provider_set([ProviderId::GithubHosted]));
        let rust_index = must_some(
            config
                .units
                .iter()
                .position(|unit| unit.kind == UnitKind::Rust),
            "scanned Rust unit",
        );
        config.units[rust_index].cache = Some(CacheSpec {
            key_files: vec!["Cargo.toml".to_owned()],
            paths: vec!["target".to_owned()],
            purpose: CachePurpose::Outputs,
            mbx_output_cache_justification: None,
            mutable_mount_seed: false,
        });
        let ir = WorkflowIr::from_config(&config);
        // Unjustified duplicate output transport is rejected, never silently
        // suppressed.
        let rejected = primitives::validate_cache_transports(&ir);
        assert!(rejected
            .err()
            .is_some_and(|error| error.to_string().contains("mbx_output_cache_justification")));
        config.units[rust_index].cache = Some(CacheSpec {
            key_files: vec!["Cargo.toml".to_owned()],
            paths: vec!["target".to_owned()],
            purpose: CachePurpose::Outputs,
            mbx_output_cache_justification: Some(
                "bench baselines read raw target artifacts the object transport drops".to_owned(),
            ),
            mutable_mount_seed: false,
        });
        let ir = WorkflowIr::from_config(&config);
        must(
            primitives::validate_cache_transports(&ir),
            "justified output cache is accepted",
        );
        let ir = WorkflowIr::from_config(&config);
        let kind = must_some(
            must(
                ir.render_kind_unit_workflow(UnitKind::Rust, None),
                "render rust kind reusable",
            ),
            "rust kind has members",
        )
        .1;
        assert!(kind.contains(
            "# output cache retained alongside mbx: bench baselines read raw target artifacts the object transport drops"
        ));
        assert!(kind.contains("name: Restore unit cache"));
        let aggregate = ir.render_nested(WorkflowKind::Main, &legacy_plan(&ir), None);
        assert!(
            aggregate.contains("target"),
            "the caller passes the retained paths: {aggregate}"
        );
    }

    #[test]
    #[expect(
        clippy::too_many_lines,
        reason = "the test pins the fetch-then-verify contract across units and lanes"
    )]
    fn rust_units_fetch_sources_first_and_verify_offline_except_policy() {
        let mut config = scanned_fixture(provider_set([ProviderId::GithubHosted]));
        let rust_index = must_some(
            config
                .units
                .iter()
                .position(|unit| unit.kind == UnitKind::Rust),
            "scanned Rust unit",
        );
        // The scan derives the lockfile pin from a root Cargo.lock the fixture
        // does not carry, so the hand-built config pins it explicitly: the test
        // exercises the fetch/offline contract itself, not the pin's absence.
        config.units[rust_index].pinned_lockfile = true;
        // Both exempt shapes are pinned in the commands: a toolchain modifier
        // and a quoted env value that splits into extra tokens must not break
        // the command-shape exemption.
        let toolchain = config
            .units
            .iter()
            .find(|unit| unit.kind == UnitKind::Rust)
            .and_then(|unit| unit.toolchain.clone());
        config.units.push(Unit {
            xcode: None,
            id: "rust-dependency-policy".to_owned(),
            label: "Rust dependency policy".to_owned(),
            kind: UnitKind::Rust,
            root: ".".to_owned(),
            pinned_lockfile: true,
            watch: vec!["Cargo.toml".to_owned()],
            pr_commands: vec!["cargo +nightly deny check".to_owned()],
            full_commands: vec!["RUSTFLAGS='-D warnings' mbx deny check".to_owned()],
            phases: Vec::new(),
            check_commands: Vec::new(),
            depends_on: Vec::new(),
            cache: None,
            tool_version: None,
            mise_tools: Vec::new(),
            toolchain,
            services: Vec::new(),
            trust: crate::s2::provider::TrustReq::UntrustedOk,
            platform: crate::s2::provider::Platform::LinuxX64,
            capabilities: crate::s2::provider::Capabilities::default(),
            workspace_check: false,
            reads_closed: false,
            full_history: false,
            products: Vec::new(),
            prerequisites: Vec::new(),
            docker_contexts: Vec::new(),
            env: std::collections::BTreeMap::new(),
            mbx: None,
            prepared_tools: Vec::new(),
        });
        let ir = WorkflowIr::from_config(&config);
        let rust = must_some(
            config.units.iter().find(|unit| unit.kind == UnitKind::Rust),
            "scanned Rust unit",
        );
        let kind = must_some(
            must(
                ir.render_kind_unit_workflow(UnitKind::Rust, None),
                "render rust kind reusable",
            ),
            "rust kind has members",
        )
        .1;
        let preparation = must_some(
            kind.find("      - name: Prepare Cargo sources"),
            "Cargo-source preparation step is rendered",
        );
        let restore = must_some(
            kind.find("      - name: Restore unit cache"),
            "Cargo-source cache restore is rendered",
        );
        let checks = must_some(
            verification_step_position(kind.as_str()),
            "run-checks step is rendered",
        );
        assert!(
            restore < preparation && preparation < checks,
            "preparation must sit between the cache restore and verification"
        );
        assert!(kind.contains("          cargo fetch --locked"));
        // The fetch is the recovery path the offline restriction presumes: it
        // must run online. A position comparison cannot prove that — an
        // offline line inside the preparation step would satisfy any "later"
        // assertion — so the step's own body is checked for the absence.
        let preparation_end = preparation
            + must_some(
                kind[preparation..].find("\n      - name: "),
                "another step follows the preparation step",
            );
        let preparation_body = &kind[preparation..preparation_end];
        assert!(
            !preparation_body.contains("cargo metadata --locked --offline"),
            "hosted preparation must not skip its unconditional fetch"
        );
        assert!(
            !preparation_body.contains("CARGO_NET_OFFLINE"),
            "the source-preparation fetch must run online; the offline\n         \
             restriction belongs to verification only"
        );
        assert!(kind.contains("CARGO_NET_OFFLINE: ${{ inputs.cargo_net_offline }}"));
        let offline = must_some(
            kind.find("CARGO_NET_OFFLINE"),
            "verification runs with the Cargo network restricted",
        );
        assert!(
            offline > preparation_end,
            "the offline restriction belongs to verification, not to preparation"
        );
        // The policy unit resolves its own advisory databases: no fetch root,
        // no offline restriction. The exemption follows from the command shape
        // (`cargo deny check`), not from any reserved unit identity.
        let policy = must_some(
            config
                .units
                .iter()
                .find(|unit| unit.id == "rust-dependency-policy"),
            "reviewed Rust policy unit",
        );
        let contract = ir.default_unit_contract(policy, false);
        let policy_facts = ir.unit_provider_facts(policy, &contract, ProviderId::GithubHosted);
        assert!(policy_facts.cargo_root.is_none());
        assert!(!policy_facts.cargo_net_offline);
        let rust_contract = ir.default_unit_contract(rust, false);
        let rust_facts = ir.unit_provider_facts(rust, &rust_contract, ProviderId::GithubHosted);
        assert!(rust_facts.cargo_root.is_some());
        assert!(rust_facts.cargo_net_offline);
        // The aggregate passes the per-unit cargo facts; the policy caller
        // carries no offline input.
        let aggregate = ir.render_nested(WorkflowKind::Main, &legacy_plan(&ir), None);
        assert!(aggregate.contains("cargo_net_offline: true"));
    }

    #[test]
    #[expect(
        clippy::too_many_lines,
        reason = "the test pins one explicit unit per tool-union combination"
    )]
    fn kind_reusable_unions_member_tools_and_covers_every_fetch_unit() {
        let mut config = scanned_fixture(provider_set([ProviderId::GithubHosted]));
        let rust_index = must_some(
            config
                .units
                .iter()
                .position(|unit| unit.kind == UnitKind::Rust),
            "scanned Rust unit",
        );
        config.units[rust_index].pinned_lockfile = true;
        let toolchain = config.units[rust_index].toolchain.clone();
        config.units.push(Unit {
            xcode: None,
            id: "rust-dependency-policy".to_owned(),
            label: "Rust dependency policy".to_owned(),
            kind: UnitKind::Rust,
            root: ".".to_owned(),
            pinned_lockfile: true,
            watch: vec!["Cargo.toml".to_owned()],
            pr_commands: vec!["cargo +nightly deny check".to_owned()],
            full_commands: vec!["RUSTFLAGS='-D warnings' mbx deny check".to_owned()],
            phases: Vec::new(),
            check_commands: Vec::new(),
            depends_on: Vec::new(),
            cache: None,
            tool_version: None,
            mise_tools: Vec::new(),
            toolchain,
            services: Vec::new(),
            trust: crate::s2::provider::TrustReq::UntrustedOk,
            platform: crate::s2::provider::Platform::LinuxX64,
            capabilities: crate::s2::provider::Capabilities::default(),
            workspace_check: false,
            reads_closed: false,
            full_history: false,
            products: Vec::new(),
            prerequisites: Vec::new(),
            docker_contexts: Vec::new(),
            env: std::collections::BTreeMap::new(),
            mbx: None,
            prepared_tools: Vec::new(),
        });
        let ir = WorkflowIr::from_config(&config);
        let kind = must_some(
            must(
                ir.render_kind_unit_workflow(UnitKind::Rust, None),
                "render rust kind reusable",
            ),
            "rust kind has members",
        )
        .1;
        assert!(
            !kind.contains("unknown unit for cargo fetch"),
            "kind jobs with fixed unit ids must not carry the union fetch case: {kind}"
        );
        assert!(kind.contains("          cargo fetch --locked"));
        // The callee renders one step block per lane job: the per-unit facts
        // (cargo-bin tools, the offline restriction) are inputs the callers
        // supply, gated on presence where members differ.
        assert!(
            kind.contains("tool: ${{ inputs.cargo_bin_tools }}"),
            "kind reusable must provision cargo-bin tools from the caller's input"
        );
        assert!(
            kind.contains("if: ${{ inputs.cargo_bin_tools != '' }}"),
            "the cargo-bin step is gated on the input when only some members need it"
        );
        assert!(
            kind.contains("CARGO_NET_OFFLINE: ${{ inputs.cargo_net_offline }}"),
            "mixed restriction reads the offline flag from the caller"
        );
        assert!(
            !kind.contains("inputs.unit == '"),
            "kind jobs must not guard steps by unit identity"
        );
        assert!(
            !kind.contains("export CARGO_NET_OFFLINE=true"),
            "kind jobs must not carry the union offline run prelude"
        );
        let pr = ir.render_nested(WorkflowKind::PullRequest, &legacy_plan(&ir), None);
        let policy_caller = must_some(
            pr.find("  github-hosted-rust-dependency-policy:"),
            "policy caller job",
        );
        let policy_block = &pr[policy_caller
            ..pr[policy_caller..]
                .find("\n  velnor-")
                .or_else(|| pr[policy_caller..].find("\n  ci-required:"))
                .map_or(pr.len(), |end| policy_caller + end)];
        assert!(
            policy_block.contains("cargo_bin_tools: cargo-deny"),
            "the policy caller passes its cargo-bin tools: {policy_block}"
        );
        assert!(
            !policy_block.contains("cargo_net_offline"),
            "deny resolves its own inputs, so its caller leaves the offline flag at the default: {policy_block}"
        );
        let restricted_caller = must_some(
            pr.find(&format!("  github-hosted-{}:", config.units[rust_index].id)),
            "restricted caller job",
        );
        assert!(
            pr[restricted_caller..].contains("cargo_net_offline: true"),
            "the restricted caller passes the offline flag: {}",
            &pr[restricted_caller..]
        );
    }

    #[test]
    #[allow(
        clippy::too_many_lines,
        reason = "the test pins every root and lane combination in one explicit contract"
    )]
    fn cargo_fetch_roots_deduplicate_workspace_members_and_keep_independent_lockfiles() {
        let workspace_member = |id: &str, root: &str| Unit {
            xcode: None,
            id: id.to_owned(),
            label: format!("Rust crate ({id})"),
            kind: UnitKind::Rust,
            root: root.to_owned(),
            pinned_lockfile: true,
            watch: vec!["Cargo.lock".to_owned()],
            pr_commands: vec!["cargo test --locked".to_owned()],
            full_commands: vec!["cargo test --locked".to_owned()],
            phases: Vec::new(),
            check_commands: Vec::new(),
            depends_on: Vec::new(),
            cache: Some(CacheSpec {
                key_files: vec!["Cargo.lock".to_owned(), format!("{root}/Cargo.toml")],
                paths: vec!["~/.cargo/registry".to_owned()],
                purpose: CachePurpose::CargoSources,
                mbx_output_cache_justification: None,
                mutable_mount_seed: false,
            }),
            tool_version: None,
            mise_tools: Vec::new(),
            toolchain: None,
            services: Vec::new(),
            trust: crate::s2::provider::TrustReq::UntrustedOk,
            platform: crate::s2::provider::Platform::LinuxX64,
            capabilities: crate::s2::provider::Capabilities::default(),
            workspace_check: false,
            reads_closed: false,
            full_history: false,
            products: Vec::new(),
            prerequisites: Vec::new(),
            docker_contexts: Vec::new(),
            env: std::collections::BTreeMap::new(),
            mbx: None,
            prepared_tools: Vec::new(),
        };
        let independent = Unit {
            root: "crates/contract".to_owned(),
            watch: vec!["crates/contract/Cargo.lock".to_owned()],
            cache: Some(CacheSpec {
                key_files: vec![
                    "crates/contract/Cargo.lock".to_owned(),
                    "crates/contract/Cargo.toml".to_owned(),
                ],
                paths: vec!["~/.cargo/registry".to_owned()],
                purpose: CachePurpose::CargoSources,
                mbx_output_cache_justification: None,
                mutable_mount_seed: false,
            }),
            ..workspace_member("rust-contract", "crates/contract")
        };
        let members = [
            &workspace_member("rust-model", "crates/model"),
            &workspace_member("rust-app", "crates/app"),
            &independent,
        ];
        let config = ProjectConfig {
            providers: std::collections::BTreeSet::from([crate::s2::provider::ProviderId::Velnor]),
            automatic_providers: std::collections::BTreeSet::from([
                crate::s2::provider::ProviderId::Velnor,
            ]),
            selectors: crate::s2::scan::default_selectors(),
            units: members.iter().map(|unit| (*unit).clone()).collect(),
            ..header_fixture_config()
        };
        let workflow = must_some(
            must(
                WorkflowIr::from_config(&config).render_kind_unit_workflow(UnitKind::Rust, None),
                "render rust kind reusable",
            ),
            "rust kind has members",
        )
        .1;
        assert!(
            workflow.matches("cargo fetch --locked").count() >= 2,
            "prep must fetch the workspace root and the independent lockfile tree"
        );
        assert!(
            !workflow.contains("cd -- 'crates/model'"),
            "workspace members must not fetch per crate: {workflow}"
        );
        assert!(
            workflow.contains(
                "cd -- 'crates/contract'\n          if cargo metadata --locked --offline --all-features --format-version 1"
            ),
            "independent lockfile trees keep their own fetch root"
        );
        let prep = must_some(
            workflow
                .split_once("  velnor-prepare-cargo-sources:\n")
                .map(|(_, block)| block),
            "velnor cargo prep job",
        );
        let prep = prep.split("\n  verify-").next().unwrap_or(prep);
        assert_eq!(
            prep.matches("cargo metadata --locked --offline --all-features --format-version 1")
                .count(),
            2,
            "deduplicated cargo prep must use the full feature graph for each fetch root"
        );
    }

    #[test]
    fn velnor_dependency_closure_adds_direct_depends_on_needs_edges() {
        let rust_unit = |id: &str, depends_on: Vec<&str>| Unit {
            xcode: None,
            id: id.to_owned(),
            label: format!("Rust crate ({id})"),
            kind: UnitKind::Rust,
            root: format!("crates/{id}"),
            pinned_lockfile: true,
            watch: vec!["Cargo.lock".to_owned()],
            pr_commands: vec!["cargo test --locked".to_owned()],
            full_commands: vec!["cargo test --locked".to_owned()],
            phases: Vec::new(),
            check_commands: Vec::new(),
            depends_on: depends_on.into_iter().map(str::to_owned).collect(),
            cache: Some(CacheSpec {
                key_files: vec!["Cargo.lock".to_owned()],
                paths: vec!["~/.cargo/registry".to_owned()],
                purpose: CachePurpose::CargoSources,
                mbx_output_cache_justification: None,
                mutable_mount_seed: false,
            }),
            tool_version: None,
            mise_tools: Vec::new(),
            toolchain: None,
            services: Vec::new(),
            trust: crate::s2::provider::TrustReq::UntrustedOk,
            platform: crate::s2::provider::Platform::LinuxX64,
            capabilities: crate::s2::provider::Capabilities::default(),
            workspace_check: false,
            reads_closed: false,
            full_history: false,
            products: Vec::new(),
            prerequisites: Vec::new(),
            docker_contexts: Vec::new(),
            env: std::collections::BTreeMap::new(),
            mbx: None,
            prepared_tools: Vec::new(),
        };
        let config = ProjectConfig {
            providers: std::collections::BTreeSet::from([crate::s2::provider::ProviderId::Velnor]),
            automatic_providers: std::collections::BTreeSet::from([
                crate::s2::provider::ProviderId::Velnor,
            ]),
            selectors: crate::s2::scan::default_selectors(),
            rust_needs: RustNeeds::DependencyClosure,
            units: vec![
                rust_unit("rust-model", vec![]),
                rust_unit("rust-client", vec!["rust-model"]),
            ],
            ..header_fixture_config()
        };
        let ir = WorkflowIr::from_config(&config);
        let workflow = ir.render_nested(WorkflowKind::Main, &legacy_plan(&ir), None);
        let job_needs = |job: &str| {
            let start = must_some(
                workflow.find(&format!("  {job}:\n")),
                "missing generated job",
            );
            let mut lines = workflow[start..].lines();
            let _ = lines.next();
            for line in lines {
                if line.starts_with("  ") && !line.starts_with("    ") {
                    break;
                }
                if let Some(needs) = line.strip_prefix("    needs: ") {
                    return Some(needs.to_owned());
                }
            }
            None
        };
        assert_eq!(
            job_needs("velnor-rust-client").as_deref(),
            Some("[plan, policy, prepare-cargo, velnor-rust-model]")
        );
        assert_eq!(
            job_needs("velnor-rust-model"),
            Some("[plan, policy, prepare-cargo]".to_owned())
        );
        assert!(
            !workflow.contains("needs: [plan, policy, velnor-rust-client]"),
            "dependency edges must not invent reverse needs: {workflow}"
        );
    }

