    #[test]
    fn ci_main_and_ci_pr_concurrency_groups_differ() {
        let config = ProjectConfig {
            providers: std::collections::BTreeSet::from([crate::s2::provider::ProviderId::Velnor]),
            automatic_providers: std::collections::BTreeSet::from([
                crate::s2::provider::ProviderId::Velnor,
            ]),
            selectors: crate::s2::scan::default_selectors(),
            concurrency_group: Some("example-${{ github.repository }}".to_owned()),
            ..header_fixture_config()
        };
        let ir = WorkflowIr::from_config(&config);
        let pr = generated_ci_pr(&ir);
        let main = generated_ci_main(&ir);
        let nightly = generated_nightly(&ir);
        assert!(
            pr.contains(
                "group: example-${{ github.repository }}-pr-${{ github.event.pull_request.number || github.ref }}\n"
            ),
            "ci-pr must use the derived -pr concurrency group: {pr}"
        );
        assert!(
            main.contains("group: example-${{ github.repository }}-main-${{ github.run_id }}\n"),
            "ci-main must use a per-run derived -main concurrency group: {main}"
        );
        assert!(
            !main.contains("group: example-${{ github.repository }}-main\n"),
            "ci-main must not serialize unrelated runs by ref: {main}"
        );
        assert!(
            main.contains("cancel-in-progress: false"),
            "ci-main must not cancel a valid running pipeline: {main}"
        );
        assert!(
            nightly.contains("group: example-${{ github.repository }}-nightly\n"),
            "nightly must use the derived -nightly concurrency group: {nightly}"
        );
        assert!(
            !main.contains("group: example-${{ github.repository }}-pr"),
            "a ci-main push must not share the ci-pr concurrency group: {main}"
        );
        assert!(
            !nightly.contains("group: example-${{ github.repository }}-main\n"),
            "nightly must not share the ci-main concurrency group: {nightly}"
        );
        assert!(
            !nightly.contains("group: example-${{ github.repository }}-pr"),
            "nightly must not share the ci-pr concurrency group: {nightly}"
        );
        let policy = must(
            render_policy_entrypoint(&config),
            "render policy entrypoint",
        );
        assert!(
            policy.contains("group: example-${{ github.repository }}-policy"),
            "policy must stay on the derived -policy group: {policy}"
        );
        assert!(
            !policy.contains("group: example-${{ github.repository }}-main"),
            "policy must not share the ci-main concurrency group: {policy}"
        );
    }

    #[test]
    fn configured_pr_concurrency_group_isolates_by_pull_request_number() {
        let config = ProjectConfig {
            concurrency_group: Some("example-${{ github.repository }}".to_owned()),
            ..header_fixture_config()
        };
        let pr = generated_ci_pr(&WorkflowIr::from_config(&config));
        assert!(
            pr.contains(
                "group: example-${{ github.repository }}-pr-${{ github.event.pull_request.number || github.ref }}\n"
            ),
            "distinct PRs must not share a configured concurrency group: {pr}"
        );
        assert!(
            !pr.contains("group: example-${{ github.repository }}\n"),
            "the raw configured group must not be emitted for ci-pr: {pr}"
        );
        assert!(
            pr.contains("cancel-in-progress: true"),
            "same-PR pushes may cancel the previous PR run: {pr}"
        );
    }

    #[test]
    fn default_aggregate_concurrency_keeps_main_runs_independent() {
        let config = header_fixture_config();
        assert!(config.concurrency_group.is_none());
        let ir = WorkflowIr::from_config(&config);
        let pr = generated_ci_pr(&ir);
        let main = generated_ci_main(&ir);
        let nightly = generated_nightly(&ir);
        let default_ref_group =
            "group: ci-${{ github.workflow }}-${{ github.event.pull_request.number || github.ref }}\n";
        assert!(
            pr.contains(default_ref_group),
            "unset concurrency_group must keep PR grouping by workflow+ref: {pr}"
        );
        assert!(
            nightly.contains(default_ref_group),
            "unset concurrency_group must keep nightly grouping by workflow+ref: {nightly}"
        );
        assert!(
            main.contains("group: ci-${{ github.workflow }}-${{ github.run_id }}\n"),
            "unset concurrency_group must use a unique group per main run: {main}"
        );
        assert!(
            !main.contains("github.event.pull_request.number || github.ref"),
            "main concurrency must not fall back to a shared ref group: {main}"
        );
        assert!(
            main.contains("cancel-in-progress: false"),
            "main concurrency must preserve non-cancellation: {main}"
        );
    }

    #[test]
    fn units_without_a_root_lockfile_neither_fetch_nor_verify_offline() {
        let root = temporary_repository("no-lockfile");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\n",
            ),
            "write manifest",
        );
        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan test repository",
        );
        let unit = must_some(config.units.first(), "scanned crate unit");
        assert!(
            !unit.pinned_lockfile,
            "a repository without a root Cargo.lock must not claim the pin"
        );
        let kind = must_some(
            must(
                WorkflowIr::from_config(&config).render_kind_unit_workflow(UnitKind::Rust, None),
                "render rust kind reusable",
            ),
            "rust kind has members",
        )
        .1;
        // `cargo fetch --locked` cannot hold without a lockfile, so neither the
        // preparation step nor the offline restriction may be rendered.
        assert!(!kind.contains("Prepare Cargo sources"));
        assert!(!kind.contains("CARGO_NET_OFFLINE"));
    }

    #[test]
    fn direct_generation_refuses_legacy_release_workflows_even_with_force() {
        let root = temporary_repository("preserve-release");
        must(
            fs::write(
                root.join("Cargo.toml"),
                "[package]\nname = \"fixture\"\nversion = \"0.1.0\"\n",
            ),
            "write manifest",
        );
        let legacy = root.join(".github/workflows/release.yml");
        must(
            fs::create_dir_all(must_some(legacy.parent(), "workflow parent")),
            "create workflow directory",
        );
        let release = "name: Release\non:\n  push:\n    tags: ['v*']\n";
        must(fs::write(&legacy, release), "write legacy release workflow");
        let config = must(
            scan_repository(
                &root,
                Some(std::collections::BTreeSet::from([
                    crate::s2::provider::ProviderId::GithubHosted,
                ])),
            ),
            "scan test repository",
        );
        let files = must(generated_files(&config), "generate");
        let error = must_some(
            write_generated(&root, &files, false, false, true).err(),
            "force must refuse legacy release workflow",
        );
        assert!(error.to_string().contains("will not be imported"));
        assert_eq!(
            must(fs::read_to_string(&legacy), "read preserved release"),
            release
        );
        assert!(!root.join(".github/legacy-workflows").exists());
        let _ = fs::remove_dir_all(root);
    }

